// Content for Defenders of the Body (node g20, ages 9-12, Chapter 3): NEW v2 build to GDD 20
// (mechanic-embodying), the immune-system + infection-myth-busting + HIV anti-stigma node (Thread F · Sexual
// & Reproductive Health) that CLOSES Chapter 3. "Strong body, clear facts, open heart." 84 researched,
// India-grounded scenarios across the defenders → how-germs-spread → defend-yourself → HIV-basics →
// spreads-or-not → kindness-not-fear arc, each encoded as one of the shared v2 play actions (strike-rewrite /
// sort / branch / role-play / spot / match / reflect): no binary "tap the right card". Lead mechanics:
// strike-rewrite (myth-bust ×22), sort (true/false & spreads-or-not ×16), branch (choose to include ×12).
// Teaches: the body's defence team (skin, white blood cells), how germs really spread, everyday prevention
// habits, HIV explained simply, what spreads HIV vs what NEVER does (CDC/NIH), and: the biggest lesson
// KINDNESS, NOT FEAR: people living with HIV belong fully in school, play and friendship; HIV is a virus,
// never a punishment or a verdict on character; with treatment people live long, healthy, normal lives; a
// health matter is private; defend others' dignity, not just your own health. Builds on g12 (Smart Screen
// Heroes: hygiene + be-kind-to-a-sick-friend); prereq g19. Rendered by the shared engine
// (components/games/v2-engine.tsx). gameId "defenders" (the engine-host registry id; the GDD/library
// aspirational id is "defenders-of-the-body"). DO NOT RENAME.

import type { Scenario, V2GameConfig } from "./v2-schema";

const SCENARIOS: Scenario[] = [
  // Your body's defenders
  {"id":"df-001","cat":"body-defenders","type":"match","hook":"Meet your body's defence team. Match the defender to its job.","pairs":[{"left":"Skin","right":"A wall that keeps germs out"},{"left":"White blood cells","right":"Soldiers that fight germs"},{"left":"A scab","right":"A shield over a cut"},{"left":"Fever","right":"Turns up the heat on germs"},{"left":"Snot","right":"Traps germs in the nose"}],"relearn":"Your body has a built-in defence team: skin, white blood cells and more.","persona":"Asha","source":"immune system"},
  {"id":"df-002","cat":"body-defenders","type":"match","hook":"Match the defender to what it does.","pairs":[{"left":"Snot and mucus","right":"Traps germs in your nose"},{"left":"Tears","right":"Wash germs from your eyes"},{"left":"Stomach acid","right":"Kills germs you swallow"},{"left":"Earwax","right":"Catches dirt in your ears"},{"left":"Coughing","right":"Pushes germs back out"}],"relearn":"Even snot and tears are part of your body's defences.","persona":"any","source":"immune system"},
  {"id":"df-003","cat":"body-defenders","type":"sort","hook":"Sort: a body defender, or not?","items":[{"id":"a","text":"White blood cells"},{"id":"b","text":"Your hair colour"},{"id":"c","text":"Skin"},{"id":"d","text":"Your favourite song"},{"id":"e","text":"Stomach acid"},{"id":"f","text":"Your height"}],"bins":[{"id":"def","label":"A defender","valence":"pos"},{"id":"not","label":"Not a defender","valence":"neutral"}],"key":{"a":"def","b":"not","c":"def","d":"not","e":"def","f":"not"},"relearn":"Skin, acid and white blood cells defend you; not everything about you does.","persona":"any","source":"immune system"},
  {"id":"df-004","cat":"body-defenders","type":"sort","hook":"Sort: what a fever means.","items":[{"id":"a","text":"Your body is fighting germs"},{"id":"b","text":"Your body gave up"},{"id":"c","text":"The defence team is working hard"},{"id":"d","text":"You're being punished"},{"id":"e","text":"Your body turned up the heat on germs"},{"id":"f","text":"You did something bad"}],"bins":[{"id":"true","label":"True","valence":"pos"},{"id":"false","label":"False","valence":"neg"}],"key":{"a":"true","b":"false","c":"true","d":"false","e":"true","f":"false"},"relearn":"A fever is often a sign your body is fighting germs, not a punishment.","persona":"any","source":"immune system"},
  {"id":"df-005","cat":"body-defenders","type":"sort","hook":"Sort: helps your defenders, or weakens them?","items":[{"id":"a","text":"Good sleep"},{"id":"b","text":"Never washing"},{"id":"c","text":"Healthy food"},{"id":"d","text":"Skipping all meals"},{"id":"e","text":"Drinking clean water"},{"id":"f","text":"Staying up all night, every night"}],"bins":[{"id":"helps","label":"Helps defenders","valence":"pos"},{"id":"weakens","label":"Weakens them","valence":"neg"}],"key":{"a":"helps","b":"weakens","c":"helps","d":"weakens","e":"helps","f":"weakens"},"relearn":"Sleep, clean water and good food strengthen your body's defences.","persona":"Rohit","source":"immune system"},
  {"id":"df-006","cat":"body-defenders","type":"strike-rewrite","hook":"\"Once a germ gets in, your body can't do anything.\"","myth":{"un":"If a germ gets in, your body is helpless.","re":"Your immune system fights germs every single day.","why":"You have a whole defence team inside you."},"relearn":"Your immune system actively fights germs all the time.","persona":"any","source":"immune system"},
  {"id":"df-007","cat":"body-defenders","type":"strike-rewrite","hook":"\"Getting a little sick sometimes means something is wrong with me.\"","myth":{"un":"Catching a cold sometimes means I'm weak or broken.","re":"Everyone catches germs sometimes; recovering shows your defences work.","why":"Getting better is your immune system winning."},"relearn":"Catching the odd cold is normal; recovering shows your defences work.","persona":"Aarav","source":"immune system"},
  {"id":"df-008","cat":"body-defenders","type":"reflect","hook":"Lensy: you have a tiny army defending you right now. Cool to think about?","prompt":"What do you think?","options":["Very cool","My body's amazing","Go team!"],"affirm":"Your body's defenders work around the clock, for free.","relearn":"Your body defends you constantly, without you even noticing.","persona":"any","source":"immune system"},
  {"id":"df-009","cat":"body-defenders","type":"reflect","hook":"Lensy: you can help your defenders with simple habits. Worth doing?","prompt":"What do you think?","options":["Yes","Easy wins","I'll help my team"],"affirm":"Sleep, food, water and clean hands are gifts to your defence team.","relearn":"Simple healthy habits help your body's defenders do their job.","persona":"any","source":"immune system"},
  {"id":"df-010","cat":"body-defenders","type":"spot","hook":"A cut on the knee over a few days. Spot the defenders at work.","scene":[{"id":"a","text":"Blood clots to plug the cut","trick":true},{"id":"b","text":"The knee is a bit muddy","trick":false},{"id":"c","text":"A scab forms, then new skin grows","trick":true},{"id":"d","text":"The plaster is bright blue","trick":false},{"id":"e","text":"It's a sunny afternoon","trick":false}],"why":"Clotting and scabbing then new skin are your defenders repairing the wound.","relearn":"Healing a cut is your body's defence and repair team in action.","persona":"any","source":"immune system"},
  {"id":"df-011","cat":"body-defenders","type":"match","hook":"Match the defender to the germ-threat it handles.","pairs":[{"left":"Skin barrier","right":"Germs on the outside"},{"left":"Stomach acid","right":"Germs in food"},{"left":"White blood cells","right":"Germs that get inside"},{"left":"Nose hairs","right":"Germs in the air you breathe"},{"left":"A scab","right":"Germs trying to enter a cut"}],"relearn":"Different defenders guard different doorways into the body.","persona":"Asha","source":"immune system"},
  {"id":"df-012","cat":"body-defenders","type":"match","hook":"Match: defender, and how to keep it strong.","pairs":[{"left":"Skin","right":"Keep it clean, cover cuts"},{"left":"Whole body","right":"Sleep and eat well"},{"left":"Defences","right":"Get your vaccines"},{"left":"Gut germs","right":"Eat fruit and veg"},{"left":"Energy to fight","right":"Drink enough water"}],"relearn":"You can keep each defender strong with simple care.","persona":"Rohit","source":"immune system / prevention"},
  // How germs spread
  {"id":"df-013","cat":"how-germs-spread","type":"sort","hook":"Sort: how do germs really travel?","items":[{"id":"a","text":"A cough or sneeze in the air"},{"id":"b","text":"Wishing really hard"},{"id":"c","text":"Dirty hands touching food"},{"id":"d","text":"Feeling jealous of someone"},{"id":"e","text":"Drinking from an unclean pot"},{"id":"f","text":"Being angry at a friend"}],"bins":[{"id":"real","label":"Real way germs spread","valence":"neg"},{"id":"no","label":"Not how germs spread","valence":"pos"}],"key":{"a":"real","b":"no","c":"real","d":"no","e":"real","f":"no"},"relearn":"Germs spread by coughs, dirty hands and unclean water, not by feelings.","persona":"any","source":"infection basics"},
  {"id":"df-014","cat":"how-germs-spread","type":"sort","hook":"Sort: spreads through the air, or through unclean water?","items":[{"id":"a","text":"A cold or the flu"},{"id":"b","text":"A tummy bug from dirty water"},{"id":"c","text":"A cough illness"},{"id":"d","text":"Loose motions from unclean water"},{"id":"e","text":"A sneezy throat infection"},{"id":"f","text":"Stomach germs from an open drain"}],"bins":[{"id":"air","label":"Through the air","valence":"uhoh"},{"id":"water","label":"Through water or food","valence":"uhoh"}],"key":{"a":"air","b":"water","c":"air","d":"water","e":"air","f":"water"},"relearn":"Some germs travel through air, others through unclean water or food.","persona":"Asha","source":"infection basics"},
  {"id":"df-015","cat":"how-germs-spread","type":"sort","hook":"Sort: spreads germs, or is harmless?","items":[{"id":"a","text":"Sneezing into bare hands, then sharing food"},{"id":"b","text":"Smiling at a friend"},{"id":"c","text":"Drinking unclean puddle water"},{"id":"d","text":"Sitting beside a classmate"},{"id":"e","text":"Coughing openly onto shared snacks"},{"id":"f","text":"Waving hello across the room"}],"bins":[{"id":"spreads","label":"Spreads germs","valence":"neg"},{"id":"harmless","label":"Harmless","valence":"pos"}],"key":{"a":"spreads","b":"harmless","c":"spreads","d":"harmless","e":"spreads","f":"harmless"},"relearn":"Germs spread by certain routes; sitting near or smiling at someone is safe.","persona":"any","source":"infection basics"},
  {"id":"df-016","cat":"how-germs-spread","type":"sort","hook":"Sort: spreads easily in the air, or does NOT?","items":[{"id":"a","text":"A cold (airborne)"},{"id":"b","text":"HIV (only certain fluids)"},{"id":"c","text":"The flu (airborne)"},{"id":"d","text":"HIV from a hug"},{"id":"e","text":"A cough illness in a crowded room"},{"id":"f","text":"HIV from sharing a plate"}],"bins":[{"id":"easy","label":"Spreads easily in air","valence":"neg"},{"id":"hard","label":"Does NOT spread that way","valence":"pos"}],"key":{"a":"easy","b":"hard","c":"easy","d":"hard","e":"easy","f":"hard"},"relearn":"Colds spread easily through air; HIV does not, and never from a hug or a plate.","persona":"Asha","source":"infection basics / HIV contrast"},
  {"id":"df-017","cat":"how-germs-spread","type":"spot","hook":"In the classroom. Spot the two germ-spreading moves.","scene":[{"id":"a","text":"A kid sneezes openly onto the shared books","trick":true},{"id":"b","text":"The ceiling fan is on","trick":false},{"id":"c","text":"He hands the wet books straight to a friend","trick":true},{"id":"d","text":"Sunlight comes through the window","trick":false},{"id":"e","text":"Another child is reading quietly","trick":false}],"why":"Sneezing openly and passing on the wet shared books spreads germs.","relearn":"Open sneezes onto shared things spread germs to others.","persona":"any","source":"infection basics"},
  {"id":"df-018","cat":"how-germs-spread","type":"spot","hook":"At the water point. Spot the two risks.","scene":[{"id":"a","text":"Water is scooped from an uncovered, dirty pot","trick":true},{"id":"b","text":"It is a hot afternoon","trick":false},{"id":"c","text":"No one washed their hands first","trick":true},{"id":"d","text":"There is a queue of children","trick":false},{"id":"e","text":"A cup is shared after rinsing in clean water","trick":false}],"why":"Unclean stored water and unwashed hands are common ways tummy germs spread.","relearn":"Dirty water and unwashed hands spread many infections.","persona":"Asha","source":"infection basics / India context"},
  {"id":"df-019","cat":"how-germs-spread","type":"spot","hook":"Spot the two things that do NOT spread germs.","scene":[{"id":"a","text":"Sharing a laugh with a friend","trick":true},{"id":"b","text":"Coughing right onto someone's food","trick":false},{"id":"c","text":"Sitting together at lunch","trick":true},{"id":"d","text":"Sneezing into bare hands, then sharing rotis","trick":false},{"id":"e","text":"Drinking from an unclean puddle","trick":false}],"why":"Laughing and sitting together are safe; only the other moves pass germs.","relearn":"Everyday friendly contact is safe; only certain actions spread germs.","persona":"any","source":"infection basics"},
  {"id":"df-020","cat":"how-germs-spread","type":"strike-rewrite","hook":"\"You catch colds from cold weather alone.\"","myth":{"un":"Cold weather by itself gives you a cold.","re":"Colds come from germs, which can spread more when we're indoors together.","why":"It's the germs, not the temperature, that infect you."},"relearn":"Colds come from germs, not from cold air by itself.","persona":"any","source":"infection basics"},
  {"id":"df-021","cat":"how-germs-spread","type":"strike-rewrite","hook":"\"If you can't see germs, they can't hurt you.\"","myth":{"un":"Germs are invisible, so they can't really affect you.","re":"Germs are tiny but real, and good hygiene keeps them in check.","why":"Invisible doesn't mean harmless."},"relearn":"Germs are invisible but real; hygiene keeps them in check.","persona":"any","source":"infection basics"},
  {"id":"df-022","cat":"how-germs-spread","type":"strike-rewrite","hook":"\"Only dirty or bad people get infections.\"","myth":{"un":"Only dirty or bad people catch infections.","re":"Anyone can catch an infection; it's about germs, not character.","why":"Blaming people for getting sick is unfair and untrue."},"relearn":"Anyone can get an infection; it's not about being 'good' or 'bad'.","persona":"Asha","source":"infection basics / anti-stigma"},
  {"id":"df-023","cat":"how-germs-spread","type":"match","hook":"Match the illness to how it usually spreads.","pairs":[{"left":"Common cold","right":"Coughs and sneezes in the air"},{"left":"Tummy bug","right":"Unclean water or food"},{"left":"Infected cut","right":"Germs entering an open wound"},{"left":"Cough illness in a crowd","right":"Breathing the same close air"},{"left":"Loose motions","right":"Drinking from a dirty source"}],"relearn":"Different infections spread by different, knowable routes.","persona":"any","source":"infection basics"},
  {"id":"df-024","cat":"how-germs-spread","type":"match","hook":"Match the myth about catching illness to the truth.","pairs":[{"left":"\"Wet hair gives you flu\"","right":"Flu comes from a virus, not damp hair"},{"left":"\"Sugar alone causes colds\"","right":"Colds come from germs we catch"},{"left":"\"Going out at night\"","right":"It is germs, not the dark"},{"left":"\"Only dirty people fall ill\"","right":"Anyone can catch a germ"},{"left":"\"Cold weather alone\"","right":"It is the germs, not the temperature"}],"relearn":"Illnesses come from germs, not from old wives' tales.","persona":"Asha","source":"infection basics / anti-stigma"},
  // Defend yourself
  {"id":"df-025","cat":"defend-yourself","type":"sort","hook":"Sort: a strong defence habit, or not?","items":[{"id":"a","text":"Washing hands with soap"},{"id":"b","text":"Sharing a half-eaten snack mouth-to-mouth"},{"id":"c","text":"Covering your cough"},{"id":"d","text":"Drinking from puddles"},{"id":"e","text":"Wiping a dirty hand on your shirt instead of washing"},{"id":"f","text":"Washing fruit before you eat it"}],"bins":[{"id":"good","label":"Good defence","valence":"pos"},{"id":"bad","label":"Weak defence","valence":"neg"}],"key":{"a":"good","b":"bad","c":"good","d":"bad","e":"bad","f":"good"},"relearn":"Handwashing and covering coughs are strong defence habits.","persona":"any","source":"prevention"},
  {"id":"df-026","cat":"defend-yourself","type":"sort","hook":"Sort: helps stop germs spreading to others?","items":[{"id":"a","text":"Coughing into your elbow"},{"id":"b","text":"Sneezing on your friend"},{"id":"c","text":"Staying home when very ill"},{"id":"d","text":"Sharing your water bottle when sick"},{"id":"e","text":"Using a hankie or tissue for your nose"},{"id":"f","text":"Blowing your nose into your bare hand then waving"}],"bins":[{"id":"yes","label":"Helps stop spread","valence":"pos"},{"id":"no","label":"Spreads it","valence":"neg"}],"key":{"a":"yes","b":"no","c":"yes","d":"no","e":"yes","f":"no"},"relearn":"Covering coughs and resting when ill protect others too.","persona":"any","source":"prevention"},
  {"id":"df-027","cat":"defend-yourself","type":"sort","hook":"Sort: what vaccines do.","items":[{"id":"a","text":"Train your defenders to recognise a germ"},{"id":"b","text":"Make you magnetic"},{"id":"c","text":"Help stop dangerous diseases"},{"id":"d","text":"Control your mind"},{"id":"e","text":"Prepare your defences before a germ strikes"},{"id":"f","text":"Change the music you like"}],"bins":[{"id":"true","label":"True","valence":"pos"},{"id":"false","label":"False","valence":"neg"}],"key":{"a":"true","b":"false","c":"true","d":"false","e":"true","f":"false"},"relearn":"Vaccines train your defenders to fight specific germs.","persona":"Asha","source":"prevention / vaccines"},
  {"id":"df-028","cat":"defend-yourself","type":"branch","hook":"You're about to eat but your hands are dirty from play.","options":[{"text":"Wash with soap and water first","consequence":"You wash off germs before they reach your mouth.","outcome":"healthy","best":true},{"text":"Just eat, it's fine","consequence":"Washing first stops germs from hitching a ride into you."}],"debrief":"Washing hands before eating is one of the best defences there is.","relearn":"Wash hands before eating to keep germs out.","persona":"any","source":"prevention"},
  {"id":"df-029","cat":"defend-yourself","type":"branch","hook":"You're getting over an illness; a friend asks to share your drink.","options":[{"text":"Say \"let me get you a fresh cup, I'm just recovering\"","consequence":"You protect your friend kindly.","outcome":"caring","best":true},{"text":"Share the same bottle","consequence":"A fresh cup protects your friend while you recover."}],"debrief":"Not sharing mouth-touched things when ill protects others.","relearn":"When recovering, avoid sharing mouth-touched items to protect others.","persona":"any","source":"prevention"},
  {"id":"df-030","cat":"defend-yourself","type":"branch","hook":"There's a vaccination drive at school and you feel nervous.","options":[{"text":"Get it; a quick pinch trains your defenders","consequence":"You're protected against a serious disease.","outcome":"brave","best":true},{"text":"Skip it out of nerves","consequence":"A moment's pinch gives lasting protection; it's worth it."}],"debrief":"Vaccines are a quick way to give your defenders a big advantage.","relearn":"Vaccines give lasting protection for a moment's pinch.","persona":"Aarav","source":"prevention / vaccines"},
  {"id":"df-031","cat":"defend-yourself","type":"strike-rewrite","hook":"\"Washing hands is pointless if they look clean.\"","myth":{"un":"If my hands look clean, washing is pointless.","re":"Germs are invisible; washing with soap removes them.","why":"Clean-looking isn't germ-free."},"relearn":"Hands can look clean but still carry germs; wash with soap.","persona":"any","source":"prevention"},
  {"id":"df-032","cat":"defend-yourself","type":"strike-rewrite","hook":"\"Vaccines aren't needed if you feel healthy.\"","myth":{"un":"If I feel healthy, I don't need vaccines.","re":"Vaccines protect you before a germ ever strikes.","why":"They prepare your defences in advance."},"relearn":"Vaccines protect you in advance, even when you feel fine.","persona":"Asha","source":"prevention / vaccines"},
  {"id":"df-033","cat":"defend-yourself","type":"spot","hook":"A handwashing poster. Spot the steps that matter.","scene":[{"id":"a","text":"Use soap and rub for a count of twenty","trick":true},{"id":"b","text":"The sink is blue","trick":false},{"id":"c","text":"Cover all parts, then rinse","trick":true},{"id":"d","text":"The tap has a small drip","trick":false},{"id":"e","text":"A towel hangs on the wall","trick":false}],"why":"Soap, scrubbing time, and covering all parts are what make handwashing work.","relearn":"Good handwashing means soap, time, full coverage, and a rinse.","persona":"any","source":"prevention"},
  {"id":"df-034","cat":"defend-yourself","type":"spot","hook":"In the kitchen. Spot the safe-food defence.","scene":[{"id":"a","text":"Water is boiled or filtered before drinking","trick":true},{"id":"b","text":"There's a steel tiffin","trick":false},{"id":"c","text":"Food is covered to keep flies off","trick":true},{"id":"d","text":"A calendar hangs by the door","trick":false},{"id":"e","text":"The stove is near the window","trick":false}],"why":"Clean water and covered food keep many infections away.","relearn":"Clean water and covered food are everyday defences.","persona":"Rohit","source":"prevention / India context"},
  {"id":"df-035","cat":"defend-yourself","type":"match","hook":"Match the defence habit to the germ it blocks.","pairs":[{"left":"Soap handwash","right":"Germs on hands"},{"left":"Covering a cough","right":"Germs in the air"},{"left":"Boiling water","right":"Germs in water"},{"left":"Washing fruit","right":"Germs on food"},{"left":"Resting at home when ill","right":"Passing germs to others"}],"relearn":"Each simple habit blocks a specific germ route.","persona":"any","source":"prevention"},
  {"id":"df-036","cat":"defend-yourself","type":"reflect","hook":"Lensy: which defence habit will you do better from today?","prompt":"Pick one.","options":["Wash hands properly","Cover my cough","Drink clean water"],"affirm":"Small habits, repeated, keep you and others well.","relearn":"Choosing one defence habit to improve protects you and others.","persona":"any","source":"prevention"},
  // HIV, simply explained
  {"id":"df-037","cat":"hiv-basics","type":"strike-rewrite","hook":"\"HIV is something only 'certain people' get.\"","myth":{"un":"Only certain 'bad' people get HIV.","re":"HIV is a virus; anyone can have it, and it says nothing about character.","why":"A virus doesn't judge who's 'good' or 'bad'."},"relearn":"HIV is a virus anyone can have; it's not about character.","persona":"Asha","source":"HIV basics / anti-stigma"},
  {"id":"df-038","cat":"hiv-basics","type":"strike-rewrite","hook":"\"Having HIV means you'll always be sick.\"","myth":{"un":"People with HIV are always sick and can't live normally.","re":"With daily medicine, people with HIV live long, healthy, normal lives.","why":"Treatment keeps the virus in check."},"relearn":"With treatment, people with HIV live long, healthy, normal lives.","persona":"Asha","source":"HIV basics / treatment"},
  {"id":"df-039","cat":"hiv-basics","type":"strike-rewrite","hook":"\"You can tell who has HIV just by looking.\"","myth":{"un":"You can tell someone has HIV by how they look.","re":"You cannot tell; people with HIV look just like anyone else.","why":"HIV has no 'look'."},"relearn":"You can't tell who has HIV; they look like anyone else.","persona":"any","source":"HIV basics"},
  {"id":"df-040","cat":"hiv-basics","type":"strike-rewrite","hook":"\"HIV is a punishment for doing something wrong.\"","myth":{"un":"HIV is a punishment for being bad.","re":"HIV is just an infection, not a punishment for anything.","why":"Illness isn't a verdict on a person."},"relearn":"HIV is an infection, never a punishment.","persona":"Asha","source":"HIV basics / anti-stigma"},
  {"id":"df-041","cat":"hiv-basics","type":"strike-rewrite","hook":"\"There's nothing doctors can do about HIV.\"","myth":{"un":"Doctors can't do anything about HIV.","re":"Medicine controls HIV so well that people stay healthy for life.","why":"HIV care has come a very long way."},"relearn":"Medicine controls HIV; people on treatment stay healthy.","persona":"Asha","source":"HIV basics / treatment"},
  {"id":"df-042","cat":"hiv-basics","type":"sort","hook":"Sort: true or false about HIV?","items":[{"id":"a","text":"Medicine helps people with HIV stay well"},{"id":"b","text":"HIV makes someone a bad person"},{"id":"c","text":"Anyone can get HIV"},{"id":"d","text":"You can spot HIV by looking"},{"id":"e","text":"Children with HIV can go to school"},{"id":"f","text":"HIV is a punishment"}],"bins":[{"id":"true","label":"True","valence":"pos"},{"id":"false","label":"False","valence":"neg"}],"key":{"a":"true","b":"false","c":"true","d":"false","e":"true","f":"false"},"relearn":"HIV is treatable, can affect anyone, lets kids learn, and is never a punishment.","persona":"any","source":"HIV basics"},
  {"id":"df-043","cat":"hiv-basics","type":"sort","hook":"Sort: how HIV mainly spreads, or how it does NOT?","items":[{"id":"a","text":"Through blood (like shared needles)"},{"id":"b","text":"From a parent to a baby"},{"id":"c","text":"From a friendly hug"},{"id":"d","text":"From sharing lunch"},{"id":"e","text":"Blood-to-blood contact"},{"id":"f","text":"From a mosquito bite"}],"bins":[{"id":"how","label":"How it can spread","valence":"neg"},{"id":"not","label":"NOT how it spreads","valence":"pos"}],"key":{"a":"how","b":"how","c":"not","d":"not","e":"how","f":"not"},"relearn":"HIV spreads through blood or parent-to-baby; never hugs, food or mosquitoes.","persona":"Asha","source":"HIV basics / transmission"},
  {"id":"df-044","cat":"hiv-basics","type":"branch","hook":"You hear a scary rumour about HIV and aren't sure what's true.","options":[{"text":"Ask a trusted adult or health worker for the facts","consequence":"You get the truth instead of fear.","outcome":"informed","best":true},{"text":"Believe and repeat the rumour","consequence":"Checking facts beats spreading a scary rumour."}],"debrief":"Facts from a trusted source beat rumours every time.","relearn":"Check HIV facts with a trusted adult or health worker.","persona":"Asha","source":"HIV basics / help-seeking"},
  {"id":"df-045","cat":"hiv-basics","type":"branch","hook":"A friend says \"older kids learn more about how HIV spreads, right?\"","options":[{"text":"\"Yes, and the main thing now is: it's not from everyday contact\"","consequence":"You keep it age-right and stigma-free.","outcome":"wise","best":true},{"text":"Make up scary details","consequence":"Keep to what you know: it's not from everyday contact."}],"debrief":"You'll learn more as you grow; for now, everyday contact is safe.","relearn":"You learn more about HIV as you grow; everyday contact is always safe.","persona":"any","source":"HIV basics / age-appropriate"},
  {"id":"df-046","cat":"hiv-basics","type":"spot","hook":"A health poster mixes accurate and wrong messages. Spot the TWO accurate ones.","scene":[{"id":"a","text":"\"People with HIV can live full, healthy lives\"","trick":true},{"id":"b","text":"\"You can catch HIV from a hug\"","trick":false},{"id":"c","text":"\"HIV is not spread by everyday contact\"","trick":true},{"id":"d","text":"\"Only certain people get HIV\"","trick":false},{"id":"e","text":"\"Keep people with HIV apart\"","trick":false}],"why":"Treatment works and everyday contact is safe. Those two messages are accurate.","relearn":"Accurate HIV messages: treatment works, and everyday contact is safe.","persona":"Asha","source":"HIV basics"},
  {"id":"df-047","cat":"hiv-basics","type":"reflect","hook":"Lensy: knowing the facts about HIV makes it less scary. Agree?","prompt":"What do you think?","options":["Yes","Facts beat fear","Much less scary"],"affirm":"Facts replace fear with understanding and kindness.","relearn":"Knowing the facts about HIV replaces fear with understanding.","persona":"any","source":"HIV basics"},
  {"id":"df-048","cat":"hiv-basics","type":"reflect","hook":"Lensy: a person with HIV is a whole person, not their virus. Makes sense?","prompt":"What do you think?","options":["Yes","They're a person first","Of course"],"affirm":"People are always more than any illness they live with.","relearn":"A person living with HIV is a whole person, not defined by it.","persona":"Asha","source":"HIV basics / dignity"},
  // Spreads, or doesn't?
  {"id":"df-049","cat":"spreads-or-not","type":"strike-rewrite","hook":"\"You can get HIV from hugging someone who has it.\"","myth":{"un":"Hugging someone with HIV can give you HIV.","re":"HIV is never spread by hugging; hug freely.","why":"HIV isn't in everyday touch."},"relearn":"You cannot get HIV from a hug.","persona":"any","source":"transmission / stigma (CDC)"},
  {"id":"df-050","cat":"spreads-or-not","type":"strike-rewrite","hook":"\"Sharing food or a plate spreads HIV.\"","myth":{"un":"Sharing food or a plate with someone with HIV spreads it.","re":"HIV does not spread through food, plates or cups.","why":"It's not carried that way."},"relearn":"You cannot get HIV from sharing food, plates or cups.","persona":"Asha","source":"transmission / stigma (CDC)"},
  {"id":"df-051","cat":"spreads-or-not","type":"strike-rewrite","hook":"\"Mosquito bites can give you HIV.\"","myth":{"un":"A mosquito that bit someone with HIV can give it to you.","re":"Mosquitoes do not spread HIV at all.","why":"The virus can't survive or pass on that way."},"relearn":"Mosquitoes do not spread HIV.","persona":"any","source":"transmission / stigma (CDC)"},
  {"id":"df-052","cat":"spreads-or-not","type":"strike-rewrite","hook":"\"You can catch HIV from a toilet seat.\"","myth":{"un":"Using the same toilet seat spreads HIV.","re":"HIV is not spread by toilet seats.","why":"It isn't passed by surfaces."},"relearn":"You cannot get HIV from a toilet seat.","persona":"any","source":"transmission / stigma (CDC)"},
  {"id":"df-053","cat":"spreads-or-not","type":"strike-rewrite","hook":"\"Sitting next to a classmate with HIV is risky.\"","myth":{"un":"Sitting next to a classmate with HIV could infect you.","re":"Sharing a class, desk or bench is completely safe.","why":"Everyday closeness doesn't spread HIV."},"relearn":"Sharing a class or bench with someone with HIV is completely safe.","persona":"Diya","source":"transmission / stigma"},
  {"id":"df-054","cat":"spreads-or-not","type":"strike-rewrite","hook":"\"HIV spreads through coughs and sneezes like a cold.\"","myth":{"un":"HIV spreads through the air like a cold.","re":"HIV is not airborne; coughs and sneezes don't spread it.","why":"It isn't a respiratory germ."},"relearn":"HIV is not airborne; coughs and sneezes don't spread it.","persona":"any","source":"transmission / stigma"},
  {"id":"df-055","cat":"spreads-or-not","type":"strike-rewrite","hook":"\"Playing sport with someone with HIV will infect you.\"","myth":{"un":"Playing sport or games with someone with HIV infects you.","re":"Playing together is safe; HIV isn't passed in everyday play.","why":"Sweat and casual contact don't spread it."},"relearn":"Playing sport or games with someone with HIV is safe.","persona":"Aarav","source":"transmission / stigma"},
  {"id":"df-056","cat":"spreads-or-not","type":"strike-rewrite","hook":"\"Being friends with someone with HIV puts you at risk.\"","myth":{"un":"Just being friends with someone with HIV is risky.","re":"Friendship is completely safe; your friend stays your friend.","why":"None of the things friends do spread HIV."},"relearn":"Being friends with someone with HIV is completely safe.","persona":"any","source":"transmission / stigma"},
  {"id":"df-057","type":"sort","persona":"Asha","source":"transmission","hook":"Sort: can spread HIV, or cannot?","items":[{"id":"a","text":"Sharing needles"},{"id":"b","text":"A hug"},{"id":"c","text":"Shaking hands"},{"id":"d","text":"Sharing food"},{"id":"e","text":"A mosquito bite"},{"id":"f","text":"A toilet seat"}],"bins":[{"id":"can","label":"Can spread it","valence":"neg"},{"id":"cannot","label":"Cannot","valence":"pos"}],"key":{"a":"can","b":"cannot","c":"cannot","d":"cannot","e":"cannot","f":"cannot"},"relearn":"HIV can spread by shared needles, but not by hugs, handshakes, food, insects or toilets.","cat":"spreads-or-not"},
  {"id":"df-058","type":"sort","persona":"any","source":"transmission","hook":"Sort: safe everyday thing, or actual (blood) risk?","items":[{"id":"a","text":"Sharing a water bottle with a friend with HIV"},{"id":"b","text":"A doctor using clean, new needles"},{"id":"c","text":"Hugging a relative with HIV"},{"id":"d","text":"Sharing a toothbrush or razor (blood)"},{"id":"e","text":"Sharing a meal off one plate"},{"id":"f","text":"A reused, unclean needle"}],"bins":[{"id":"safe","label":"Safe","valence":"pos"},{"id":"avoid","label":"Avoid (blood risk)","valence":"neg"}],"key":{"a":"safe","b":"safe","c":"safe","d":"avoid","e":"safe","f":"avoid"},"relearn":"Food, water and hugs are safe; only blood-contact items like razors and reused needles are avoided.","cat":"spreads-or-not"},
  {"id":"df-059","type":"sort","persona":"any","source":"transmission / stigma","hook":"Sort: safe everyday contact, or a real (blood) risk?","items":[{"id":"a","text":"Sitting together"},{"id":"b","text":"Sharing a pencil"},{"id":"c","text":"Eating lunch side by side"},{"id":"d","text":"Laughing together"},{"id":"e","text":"Walking home together"},{"id":"f","text":"A reused, unclean needle"}],"bins":[{"id":"safe","label":"Safe everyday contact","valence":"pos"},{"id":"risk","label":"A real (blood) risk","valence":"neg"}],"key":{"a":"safe","b":"safe","c":"safe","d":"safe","e":"safe","f":"risk"},"relearn":"All everyday friendly contact is safe; only blood-contact like a reused needle is a risk.","cat":"spreads-or-not"},
  {"id":"df-060","type":"sort","persona":"any","source":"transmission","hook":"Sort: fact, or myth?","items":[{"id":"a","text":"\"HIV spreads through hugs\""},{"id":"b","text":"\"HIV is not airborne\""},{"id":"c","text":"\"Mosquitoes spread HIV\""},{"id":"d","text":"\"You can't tell by looking\""},{"id":"e","text":"\"Sharing a toilet spreads HIV\""},{"id":"f","text":"\"Treatment means a normal life\""}],"bins":[{"id":"fact","label":"Fact","valence":"pos"},{"id":"myth","label":"Myth","valence":"neg"}],"key":{"a":"myth","b":"fact","c":"myth","d":"fact","e":"myth","f":"fact"},"relearn":"Hugs, mosquitoes and toilets are myths; not-airborne, not-visible and treatment-works are facts.","cat":"spreads-or-not"},
  {"id":"df-061","type":"spot","persona":"any","source":"transmission / media literacy","hook":"A 'how HIV spreads' chart. Spot the 2 wrong (myth) entries.","scene":[{"id":"a","text":"\"By sharing meals\" listed as a way","trick":true},{"id":"b","text":"\"Through certain body fluids like blood\" listed","trick":false},{"id":"c","text":"\"By holding hands\" listed as a way","trick":true},{"id":"d","text":"\"From parent to baby\" listed","trick":false},{"id":"e","text":"\"Through shared, unclean needles\" listed","trick":false}],"why":"Sharing meals and holding hands are myths; they never spread HIV.","relearn":"Watch for myths on charts: meals and hand-holding never spread HIV.","cat":"spreads-or-not"},
  {"id":"df-062","type":"spot","persona":"Asha","source":"transmission","hook":"A leaflet. Spot the 2 reassuring TRUE facts.","scene":[{"id":"a","text":"\"Everyday contact is safe\"","trick":true},{"id":"b","text":"\"Leaflet printed locally\"","trick":false},{"id":"c","text":"\"Treatment keeps people healthy\"","trick":true},{"id":"d","text":"\"Free at the centre\"","trick":false},{"id":"e","text":"\"Printed on recycled paper\"","trick":false}],"why":"Everyday contact being safe and treatment working are both true and reassuring.","relearn":"True, reassuring facts: everyday contact is safe; treatment works.","cat":"spreads-or-not"},
  {"id":"df-063","cat":"spreads-or-not","type":"branch","hook":"A classmate refuses to share a bench with a kid rumoured to have HIV.","options":[{"text":"Explain calmly that sitting together is totally safe","consequence":"You replace fear with a fact.","outcome":"informed","best":true},{"text":"Move away too, just in case","consequence":"Sitting together is safe; the fear is based on a myth."}],"debrief":"Knowing it's safe lets you act with facts, not fear.","relearn":"Sitting with someone with HIV is safe; share the bench.","persona":"Diya","source":"transmission / stigma action"},
  {"id":"df-064","cat":"spreads-or-not","type":"branch","hook":"Someone says \"don't drink from that cup, she has HIV\".","options":[{"text":"Say \"HIV doesn't spread through cups, it's fine\"","consequence":"You correct the myth kindly.","outcome":"informed","best":true},{"text":"Throw the cup away dramatically","consequence":"Cups don't spread HIV; there's no need to fear."}],"debrief":"Correcting a transmission myth protects someone from cruelty.","relearn":"HIV doesn't spread through cups; correct that myth.","persona":"any","source":"transmission / stigma action"},
  {"id":"df-065","cat":"spreads-or-not","type":"reflect","hook":"Lensy: most 'ways HIV spreads' that scare people are myths. Surprising?","prompt":"What do you think?","options":["Yes","Most are myths","Good to know"],"affirm":"Most fears about catching HIV from daily life simply aren't true.","relearn":"Most everyday fears about catching HIV are myths.","persona":"any","source":"transmission"},
  {"id":"df-066","cat":"spreads-or-not","type":"reflect","hook":"Lensy: if everyday contact is safe, what does that mean for friends with HIV?","prompt":"What do you think?","options":["We can be normal friends","Hug, share, play freely","Nothing to fear"],"affirm":"It means you can be a completely normal friend.","relearn":"Since everyday contact is safe, you can be a normal friend.","persona":"Diya","source":"transmission / stigma"},
  // Kindness, not fear
  {"id":"df-067","cat":"kindness-not-fear","type":"branch","hook":"A new classmate is known to be living with HIV; others keep their distance.","options":[{"text":"Welcome them and sit with them like anyone else","consequence":"They feel included; others see it's safe.","outcome":"kind","best":true},{"text":"Keep your distance like the others","consequence":"It's safe and kind to include them fully."}],"debrief":"Including someone with HIV is both safe and the right thing.","relearn":"Include someone living with HIV just like any other friend.","persona":"Diya","source":"stigma reduction"},
  {"id":"df-068","cat":"kindness-not-fear","type":"branch","hook":"Kids are whispering and excluding a child because of an illness.","options":[{"text":"Go include them and gently correct the fear","consequence":"You break the exclusion with facts and warmth.","outcome":"upstander","best":true},{"text":"Join the whispering","consequence":"Including them and sharing facts beats whispering."}],"debrief":"Exclusion based on illness-fear can be undone with kindness and facts.","relearn":"You can include someone shut out over illness, and correct the fear.","persona":"any","source":"stigma reduction / upstander (links g19)"},
  {"id":"df-069","cat":"kindness-not-fear","type":"branch","hook":"A relative says people with HIV should be kept apart.","options":[{"text":"Share calmly that everyday contact is safe","consequence":"You offer a fact that softens the fear.","outcome":"informed","best":true},{"text":"Agree to avoid conflict","consequence":"A gentle fact can ease an elder's fear."}],"debrief":"Even with elders, a calm fact can reduce stigma.","relearn":"You can gently correct an elder's fear about HIV with facts.","persona":"Asha","source":"stigma reduction / respect"},
  {"id":"df-070","cat":"kindness-not-fear","type":"branch","hook":"Your friend is scared to tell anyone a family member has HIV.","options":[{"text":"Be a safe, kind friend who keeps it private and supportive","consequence":"Your friend feels less alone.","outcome":"caring","best":true},{"text":"Tell others it's 'big news'","consequence":"A health matter is private; be a supportive, discreet friend."}],"debrief":"Someone's health is private; kindness means support, not gossip.","relearn":"Keep others' health private; offer support, not gossip.","persona":"any","source":"stigma reduction / privacy"},
  {"id":"df-071","cat":"kindness-not-fear","type":"branch","hook":"You catch yourself feeling a little scared around someone with HIV.","options":[{"text":"Remind yourself of the facts and act normally","consequence":"Your knowledge calms the fear.","outcome":"growth","best":true},{"text":"Avoid them to be 'safe'","consequence":"The facts say it's safe; let them calm the fear."}],"debrief":"It's okay to feel unsure; let facts guide you back to kindness.","relearn":"Let the facts calm any fear so you can act with kindness.","persona":"Aarav","source":"stigma reduction / self"},
  {"id":"df-072","cat":"kindness-not-fear","type":"role-play","hook":"A friend mocks a classmate over an illness.","setup":"Stand up for them. Say:","yourLine":[{"text":"\"That's not okay, and it's not even how it spreads.\"","best":true},{"text":"Laugh along"}],"relearn":"You can defend someone and correct the myth at once.","persona":"Aarav","source":"stigma reduction / voice"},
  {"id":"df-073","cat":"kindness-not-fear","type":"role-play","hook":"Someone says \"stay away from them, they're sick\".","setup":"Reassure and include. Say:","yourLine":[{"text":"\"It's safe, come on, let's all play together.\"","best":true},{"text":"\"Okay, I'll stay away too.\""}],"relearn":"You can lead others back to including someone.","persona":"Diya","source":"stigma reduction / voice"},
  {"id":"df-074","cat":"kindness-not-fear","type":"role-play","hook":"A child with HIV looks left out at lunch.","setup":"Invite them in. Say:","yourLine":[{"text":"\"Come sit with us!\"","best":true},{"text":"Look away"}],"relearn":"A simple 'come sit with us' fights stigma powerfully.","persona":"any","source":"stigma reduction / inclusion"},
  {"id":"df-075","cat":"kindness-not-fear","type":"role-play","hook":"Friends are spreading a scary HIV rumour about someone.","setup":"Stop the rumour. Say:","yourLine":[{"text":"\"That's not true, and it's unkind, let's drop it.\"","best":true},{"text":"Pass the rumour on"}],"relearn":"You can refuse to spread a hurtful, untrue rumour.","persona":"any","source":"stigma reduction / voice"},
  {"id":"df-076","cat":"kindness-not-fear","type":"role-play","hook":"A classmate with HIV is nervous you'll treat them differently.","setup":"Put them at ease. Say:","yourLine":[{"text":"\"You're my friend, same as always.\"","best":true},{"text":"Act awkward around them"}],"relearn":"Treating a friend the same as always is the kindest message.","persona":"Diya","source":"stigma reduction / friendship"},
  {"id":"df-077","cat":"kindness-not-fear","type":"role-play","hook":"Your younger sibling repeats a stigma myth they heard.","setup":"Gently teach them. Say:","yourLine":[{"text":"\"Actually you can't catch HIV that way, let me explain.\"","best":true},{"text":"Let the myth stand"}],"relearn":"You can pass accurate, kind facts to younger kids.","persona":"any","source":"stigma reduction / mentoring"},
  {"id":"df-078","cat":"kindness-not-fear","type":"role-play","hook":"A teacher asks the class to welcome a student with a health condition.","setup":"Set a warm tone. Say:","yourLine":[{"text":"\"Welcome! You'll like it here.\"","best":true},{"text":"Stay silent and unsure"}],"relearn":"A warm welcome sets the tone for everyone else.","persona":"any","source":"stigma reduction / inclusion"},
  {"id":"df-079","cat":"kindness-not-fear","type":"role-play","hook":"Someone insists HIV makes a person 'less'.","setup":"Affirm their worth. Say:","yourLine":[{"text":"\"Having HIV doesn't make anyone less of a person.\"","best":true},{"text":"Say nothing"}],"relearn":"A person's worth is never reduced by an illness.","persona":"Asha","source":"stigma reduction / dignity"},
  {"id":"df-080","cat":"kindness-not-fear","type":"strike-rewrite","hook":"\"People with HIV should be kept separate from everyone.\"","myth":{"un":"People with HIV should be kept apart from others.","re":"They belong fully in school, play and friendship; it's safe.","why":"Separation is based on fear, not facts."},"relearn":"People with HIV belong fully in everyday life; separating them is wrong.","persona":"any","source":"stigma reduction"},
  {"id":"df-081","cat":"kindness-not-fear","type":"strike-rewrite","hook":"\"It's fine to tease someone about being ill.\"","myth":{"un":"Teasing someone about an illness is harmless fun.","re":"Mocking illness is cruel and can really hurt.","why":"No one chooses to be ill."},"relearn":"Teasing someone about illness is cruel, not funny.","persona":"any","source":"stigma reduction"},
  {"id":"df-082","cat":"kindness-not-fear","type":"reflect","hook":"Lensy: the real 'defender of the body' includes defending others' dignity. See it?","prompt":"What do you think?","options":["Yes","Defend dignity too","Kindness is strength"],"affirm":"Defending someone's dignity is the bravest defence of all.","relearn":"Being a defender includes protecting others' dignity, not just health.","persona":"any","source":"stigma reduction / values"},
  {"id":"df-083","cat":"kindness-not-fear","type":"reflect","hook":"Lensy: biggest take-away from Defenders of the Body?","prompt":"Pick your motto.","options":["My body defends me","Germs spread in known ways","HIV isn't everyday contact","Kindness, not fear"],"affirm":"Strong body, clear facts, open heart, you're a true defender.","relearn":"Know your defences, know the facts, and choose kindness over fear.","persona":"any","source":"consolidation"},
  {"id":"df-084","cat":"kindness-not-fear","type":"reflect","hook":"Lensy: would you be a kind, fact-knowing friend to someone with HIV now?","prompt":"What do you think?","options":["Definitely","Yes, easily","Friend, same as always"],"affirm":"That's exactly the defender the world needs more of.","relearn":"You can be a safe, kind, well-informed friend to anyone with HIV.","persona":"Diya","source":"consolidation"},
  {"id":"df-900","cat":"body-defenders","type":"match","hook":"Match each defender to the doorway it guards.","pairs":[{"left":"Nose hairs","right":"The air you breathe in"},{"left":"Eyelashes","right":"Dust near your eyes"},{"left":"Lips and gums","right":"Your mouth"},{"left":"Skin","right":"Your whole outside"},{"left":"Stomach acid","right":"Food you swallow"}],"relearn":"Every doorway into your body has its own little guard.","persona":"Asha","source":"immune system"},
  {"id":"df-901","cat":"body-defenders","type":"match","hook":"Match the defender to the picture a child might draw of it.","pairs":[{"left":"White blood cells","right":"Tiny soldiers on patrol"},{"left":"Skin","right":"A strong outer wall"},{"left":"A scab","right":"A little roof over a cut"},{"left":"Fever","right":"The body's heater switched on"},{"left":"Mucus","right":"Sticky germ-traps"}],"relearn":"Your defenders each do a job you can picture.","persona":"any","source":"immune system"},
  {"id":"df-902","cat":"body-defenders","type":"match","hook":"Asha asks: match the helper to what it does when you get a cut.","pairs":[{"left":"Blood clotting","right":"Plugs the hole fast"},{"left":"A scab","right":"Covers it while it mends"},{"left":"White blood cells","right":"Clean out any germs"},{"left":"New skin","right":"Seals it up for good"},{"left":"Itching","right":"A sign it is healing"}],"relearn":"Healing a cut is a team effort, step by step.","persona":"Asha","source":"immune system"},
  {"id":"df-903","cat":"body-defenders","type":"match","hook":"Match: defender, and the habit that keeps it strong.","pairs":[{"left":"Skin","right":"Wash and cover cuts"},{"left":"Lungs","right":"Breathe clean air"},{"left":"Tummy","right":"Eat fresh, washed food"},{"left":"Whole body","right":"Sleep well at night"},{"left":"Defences","right":"Take your vaccines"}],"relearn":"Each defender has a simple habit that keeps it strong.","persona":"Rohit","source":"immune system / prevention"},
  {"id":"df-904","cat":"body-defenders","type":"match","hook":"Match the sign to the defender behind it.","pairs":[{"left":"A scab on your knee","right":"Skin repairing itself"},{"left":"A runny nose","right":"Mucus flushing out germs"},{"left":"Watery eyes","right":"Tears washing germs away"},{"left":"A mild fever","right":"The body heating up germs"},{"left":"A cough","right":"Lungs pushing germs out"}],"relearn":"Many things you notice are defenders quietly at work.","persona":"any","source":"immune system"},
  {"id":"df-905","cat":"body-defenders","type":"match","hook":"Match each defender to where it lives in your body.","pairs":[{"left":"Stomach acid","right":"In your tummy"},{"left":"Earwax","right":"In your ears"},{"left":"Tears","right":"Around your eyes"},{"left":"Skin","right":"All over you"},{"left":"White blood cells","right":"In your blood"}],"relearn":"Your defence team is spread right across your body.","persona":"Asha","source":"immune system"},
  {"id":"df-906","cat":"body-defenders","type":"match","hook":"Match the myth-y idea to the calm true fact.","pairs":[{"left":"A fever means I'm broken","right":"It means I'm fighting germs"},{"left":"My body is helpless","right":"It defends me all day"},{"left":"Only medicine can help","right":"My defenders help too"},{"left":"Getting sick = weak","right":"Recovering = defences working"},{"left":"Cuts never heal alone","right":"My body repairs them"}],"relearn":"Calm facts replace scary ideas about your own body.","persona":"Aarav","source":"immune system / anti-fear"},
  {"id":"df-907","cat":"body-defenders","type":"match","hook":"Match the everyday food or habit to the defender it boosts.","pairs":[{"left":"Dal and veg","right":"Builds strong defences"},{"left":"A full night's sleep","right":"Recharges your soldiers"},{"left":"Clean drinking water","right":"Keeps tummy germs out"},{"left":"Washing hands","right":"Helps your skin guard"},{"left":"Playing outside","right":"Keeps the whole body fit"}],"relearn":"Simple daily choices feed your body's defenders.","persona":"Rohit","source":"immune system / prevention"},
  {"id":"df-908","cat":"body-defenders","type":"match","hook":"Match the defender to the kind of germ it stops best.","pairs":[{"left":"Skin","right":"Germs touching you outside"},{"left":"Mucus in the nose","right":"Germs you breathe in"},{"left":"Stomach acid","right":"Germs you eat"},{"left":"White blood cells","right":"Germs that slip inside"},{"left":"Tears","right":"Germs near your eyes"}],"relearn":"Each germ route has a defender ready for it.","persona":"any","source":"immune system"},
  {"id":"df-909","cat":"body-defenders","type":"match","hook":"Match: what a vaccine does, paired with a simple picture.","pairs":[{"left":"Shows your body a germ's photo","right":"So it knows the enemy"},{"left":"Trains your defenders","right":"Like a practice drill"},{"left":"Builds a memory","right":"Ready for the real germ"},{"left":"Works before you're sick","right":"Protection in advance"},{"left":"A quick pinch","right":"Long-lasting shield"}],"relearn":"A vaccine is a practice drill that trains your defenders.","persona":"Asha","source":"prevention / vaccines"},
  {"id":"df-910","cat":"body-defenders","type":"match","hook":"Match the defender to a true fact about it.","pairs":[{"left":"White blood cells","right":"Travel in your blood to fight"},{"left":"Skin","right":"Heals itself after a scratch"},{"left":"A fever","right":"Can be your body fighting back"},{"left":"Mucus","right":"Is sticky on purpose"},{"left":"Your defences","right":"Work even while you sleep"}],"relearn":"Your defenders are busy even when you don't notice them.","persona":"any","source":"immune system"},
  {"id":"df-911","cat":"body-defenders","type":"match","hook":"Asha: match each calm fact to why it's true.","pairs":[{"left":"Anyone can catch a germ","right":"Germs don't judge people"},{"left":"Recovering shows defences work","right":"Your team won that round"},{"left":"Rest helps you heal","right":"It saves energy to fight"},{"left":"Clean water protects you","right":"It blocks tummy germs"},{"left":"Vaccines help everyone","right":"They prevent serious illness"}],"relearn":"Knowing why a fact is true makes it easy to remember.","persona":"Asha","source":"immune system / health literacy"},
  {"id":"df-912","cat":"body-defenders","type":"match","hook":"Match the body part to its surprising defender job.","pairs":[{"left":"Spit","right":"Starts cleaning your mouth"},{"left":"Nose","right":"Warms and filters air"},{"left":"Skin oil","right":"Helps block some germs"},{"left":"Throat","right":"Catches germs before the lungs"},{"left":"Bones","right":"Make new blood defenders"}],"relearn":"Even ordinary body parts quietly help defend you.","persona":"any","source":"immune system"},
  {"id":"df-913","cat":"body-defenders","type":"match","hook":"Match the worry to the reassuring fact.","pairs":[{"left":"\"A scab is gross\"","right":"It's a shield while you heal"},{"left":"\"A fever is scary\"","right":"It's often your body fighting"},{"left":"\"I'm always going to be sick\"","right":"You recover; defences work"},{"left":"\"Germs are everywhere\"","right":"Habits keep most out"},{"left":"\"My body is weak\"","right":"It defends you every day"}],"relearn":"Most body worries have a calm, true answer.","persona":"Aarav","source":"immune system / anti-fear"},
  {"id":"df-914","cat":"body-defenders","type":"match","hook":"Match each defence step to where it happens in a healing cut.","pairs":[{"left":"First","right":"Blood clots to stop bleeding"},{"left":"Next","right":"White blood cells clean it"},{"left":"Then","right":"A scab covers the gap"},{"left":"After that","right":"New skin grows underneath"},{"left":"Finally","right":"The scab falls off"}],"relearn":"A cut heals in clear steps, each one a defender's job.","persona":"any","source":"immune system"},
  {"id":"df-915","cat":"body-defenders","type":"match","hook":"Match the defender to the friendly nickname a kid gave it.","pairs":[{"left":"White blood cells","right":"The germ-busters"},{"left":"Skin","right":"The big wall"},{"left":"Stomach acid","right":"The germ-melter"},{"left":"Mucus","right":"The sticky trap"},{"left":"Fever","right":"The heat blast"}],"relearn":"Picturing your defenders makes them easy to remember.","persona":"any","source":"immune system"},
  {"id":"df-916","cat":"body-defenders","type":"match","hook":"Match: a habit, and the defender it protects.","pairs":[{"left":"Covering a cut","right":"Keeps your skin wall sealed"},{"left":"Eating well","right":"Feeds your white blood cells"},{"left":"Resting when ill","right":"Saves energy to fight"},{"left":"Brushing teeth","right":"Helps your mouth defences"},{"left":"Boiling water","right":"Backs up your stomach acid"}],"relearn":"Good habits team up with the defenders you already have.","persona":"Rohit","source":"immune system / prevention"},
  {"id":"df-917","cat":"body-defenders","type":"sort","hook":"Sort: a real job your defence team does, or made-up?","items":[{"id":"a","text":"Skin keeps germs out"},{"id":"b","text":"Earwax sends you dreams"},{"id":"c","text":"White blood cells fight germs"},{"id":"d","text":"A fever changes your eye colour"},{"id":"e","text":"Tears wash germs from eyes"},{"id":"f","text":"Snot tells the future"}],"bins":[{"id":"real","label":"Real defender job","valence":"pos"},{"id":"made","label":"Made-up","valence":"neg"}],"key":{"a":"real","b":"made","c":"real","d":"made","e":"real","f":"made"},"relearn":"Your defenders do real jobs; the silly ones are just made up.","persona":"any","source":"immune system"},
  {"id":"df-918","cat":"body-defenders","type":"sort","hook":"Sort: helps your defenders, or doesn't really do anything?","items":[{"id":"a","text":"Eating fruit and veg"},{"id":"b","text":"Wearing a lucky colour"},{"id":"c","text":"Getting enough sleep"},{"id":"d","text":"Carrying a charm"},{"id":"e","text":"Drinking clean water"},{"id":"f","text":"Crossing your fingers"}],"bins":[{"id":"helps","label":"Really helps","valence":"pos"},{"id":"no","label":"Does nothing","valence":"neutral"}],"key":{"a":"helps","b":"no","c":"helps","d":"no","e":"helps","f":"no"},"relearn":"Food, sleep and clean water help; charms and luck do not.","persona":"Aarav","source":"immune system / health literacy"},
  {"id":"df-919","cat":"body-defenders","type":"sort","hook":"Sort: true or false about your immune system?","items":[{"id":"a","text":"It works even while you sleep"},{"id":"b","text":"It only works if you're scared"},{"id":"c","text":"It fights germs every day"},{"id":"d","text":"It gives up after one cold"},{"id":"e","text":"It can learn from a vaccine"},{"id":"f","text":"It can be seen with bare eyes"}],"bins":[{"id":"true","label":"True","valence":"pos"},{"id":"false","label":"False","valence":"neg"}],"key":{"a":"true","b":"false","c":"true","d":"false","e":"true","f":"false"},"relearn":"Your immune system works all day, every day, and can learn.","persona":"Asha","source":"immune system"},
  {"id":"df-920","cat":"body-defenders","type":"sort","hook":"Sort: a sign your defenders are working, or not a sign at all?","items":[{"id":"a","text":"A scab forming on a cut"},{"id":"b","text":"Your favourite colour"},{"id":"c","text":"A mild fever during a cold"},{"id":"d","text":"The length of your hair"},{"id":"e","text":"A runny nose clearing germs"},{"id":"f","text":"Your shoe size"}],"bins":[{"id":"sign","label":"A sign they work","valence":"pos"},{"id":"not","label":"Not a sign","valence":"neutral"}],"key":{"a":"sign","b":"not","c":"sign","d":"not","e":"sign","f":"not"},"relearn":"Scabs, a mild fever and a runny nose can be your defenders at work.","persona":"any","source":"immune system"},
  {"id":"df-921","cat":"body-defenders","type":"sort","hook":"Sort: which part of the healing team, or not part of it?","items":[{"id":"a","text":"Blood clotting"},{"id":"b","text":"The plaster's colour"},{"id":"c","text":"White blood cells cleaning"},{"id":"d","text":"The room being noisy"},{"id":"e","text":"New skin growing"},{"id":"f","text":"The time on the clock"}],"bins":[{"id":"team","label":"Part of healing","valence":"pos"},{"id":"not","label":"Not part of it","valence":"neutral"}],"key":{"a":"team","b":"not","c":"team","d":"not","e":"team","f":"not"},"relearn":"Clotting, cleaning and new skin heal a cut; the room around it doesn't.","persona":"any","source":"immune system"},
  {"id":"df-922","cat":"body-defenders","type":"sort","hook":"Sort: strengthens your defences, or weakens them?","items":[{"id":"a","text":"A balanced meal"},{"id":"b","text":"Skipping sleep for days"},{"id":"c","text":"Staying active"},{"id":"d","text":"Never drinking water"},{"id":"e","text":"Getting your vaccines"},{"id":"f","text":"Eating only junk, never veg"}],"bins":[{"id":"strong","label":"Strengthens","valence":"pos"},{"id":"weak","label":"Weakens","valence":"neg"}],"key":{"a":"strong","b":"weak","c":"strong","d":"weak","e":"strong","f":"weak"},"relearn":"Food, sleep, water, activity and vaccines strengthen your defences.","persona":"Rohit","source":"immune system / prevention"},
  {"id":"df-923","cat":"body-defenders","type":"sort","hook":"Sort: does this defender guard outside the body, or inside?","items":[{"id":"a","text":"Skin"},{"id":"b","text":"White blood cells"},{"id":"c","text":"Eyelashes"},{"id":"d","text":"Stomach acid"},{"id":"e","text":"Nose hairs"},{"id":"f","text":"Clotting in a wound"}],"bins":[{"id":"out","label":"Guards outside","valence":"neutral"},{"id":"in","label":"Works inside","valence":"neutral"}],"key":{"a":"out","b":"in","c":"out","d":"in","e":"out","f":"in"},"relearn":"Some defenders guard your outside; others fight germs deep inside.","persona":"Asha","source":"immune system"},
  {"id":"df-924","cat":"body-defenders","type":"sort","hook":"Sort: a calm fact about getting sick, or a scary myth?","items":[{"id":"a","text":"Anyone can catch a common germ"},{"id":"b","text":"Only bad people get sick"},{"id":"c","text":"Recovering shows defences work"},{"id":"d","text":"A cold means you're broken"},{"id":"e","text":"Rest helps you heal"},{"id":"f","text":"Getting sick is a punishment"}],"bins":[{"id":"fact","label":"Calm fact","valence":"pos"},{"id":"myth","label":"Scary myth","valence":"neg"}],"key":{"a":"fact","b":"myth","c":"fact","d":"myth","e":"fact","f":"myth"},"relearn":"Getting sick is normal and not a punishment; calm facts beat scary myths.","persona":"Aarav","source":"immune system / anti-stigma"},
  {"id":"df-925","cat":"body-defenders","type":"sort","hook":"Sort: what a vaccine really does, or a made-up claim?","items":[{"id":"a","text":"Trains your defenders"},{"id":"b","text":"Makes you magnetic"},{"id":"c","text":"Helps stop serious diseases"},{"id":"d","text":"Controls your mind"},{"id":"e","text":"Works before a germ strikes"},{"id":"f","text":"Changes who you are"}],"bins":[{"id":"real","label":"Really does","valence":"pos"},{"id":"made","label":"Made-up","valence":"neg"}],"key":{"a":"real","b":"made","c":"real","d":"made","e":"real","f":"made"},"relearn":"Vaccines train your defenders; the magnet and mind stories are made up.","persona":"Asha","source":"prevention / vaccines"},
  {"id":"df-926","cat":"body-defenders","type":"sort","hook":"Sort: gives your defenders energy, or drains it?","items":[{"id":"a","text":"A good breakfast"},{"id":"b","text":"Days with no food"},{"id":"c","text":"Plenty of water"},{"id":"d","text":"No rest at all"},{"id":"e","text":"Calm time to recover"},{"id":"f","text":"Constant stress, no breaks"}],"bins":[{"id":"energy","label":"Gives energy","valence":"pos"},{"id":"drain","label":"Drains it","valence":"neg"}],"key":{"a":"energy","b":"drain","c":"energy","d":"drain","e":"energy","f":"drain"},"relearn":"Food, water and rest fuel your defenders; going without drains them.","persona":"Rohit","source":"immune system / prevention"},
  {"id":"df-927","cat":"body-defenders","type":"sort","hook":"Sort: this body sign is a defender at work, or just normal you?","items":[{"id":"a","text":"A scab over a cut"},{"id":"b","text":"Your eye colour"},{"id":"c","text":"Watery eyes near smoke"},{"id":"d","text":"Being tall or short"},{"id":"e","text":"Coughing out dust"},{"id":"f","text":"Your handwriting"}],"bins":[{"id":"work","label":"Defender at work","valence":"pos"},{"id":"you","label":"Just normal you","valence":"neutral"}],"key":{"a":"work","b":"you","c":"work","d":"you","e":"work","f":"you"},"relearn":"Scabs, watery eyes and coughs can be defenders; your traits just make you you.","persona":"any","source":"immune system"},
  {"id":"df-928","cat":"body-defenders","type":"sort","hook":"Sort: this helps you recover, or won't make a difference?","items":[{"id":"a","text":"Resting in bed"},{"id":"b","text":"Wearing a lucky shirt"},{"id":"c","text":"Drinking fluids"},{"id":"d","text":"Avoiding a black cat"},{"id":"e","text":"Eating light, fresh food"},{"id":"f","text":"Blaming yourself"}],"bins":[{"id":"helps","label":"Helps recovery","valence":"pos"},{"id":"no","label":"No difference","valence":"neutral"}],"key":{"a":"helps","b":"no","c":"helps","d":"no","e":"helps","f":"no"},"relearn":"Rest, fluids and good food help you recover; luck and blame do not.","persona":"Aarav","source":"immune system / health literacy"},
  {"id":"df-929","cat":"body-defenders","type":"sort","hook":"Sort: a defender that fights germs, or a defender that blocks them at the door?","items":[{"id":"a","text":"White blood cells"},{"id":"b","text":"Skin"},{"id":"c","text":"Clotting in a wound"},{"id":"d","text":"Nose hairs"},{"id":"e","text":"Fever heating germs"},{"id":"f","text":"Eyelashes"}],"bins":[{"id":"fight","label":"Fights inside","valence":"neutral"},{"id":"block","label":"Blocks at the door","valence":"neutral"}],"key":{"a":"fight","b":"block","c":"fight","d":"block","e":"fight","f":"block"},"relearn":"Some defenders block germs at the door; others fight them once inside.","persona":"Asha","source":"immune system"},
  {"id":"df-930","cat":"body-defenders","type":"sort","hook":"Sort: true or false about a fever?","items":[{"id":"a","text":"It can mean your body is fighting"},{"id":"b","text":"It means you are a bad kid"},{"id":"c","text":"Rest and fluids help"},{"id":"d","text":"It is a sign you gave up"},{"id":"e","text":"A trusted adult can help if it's high"},{"id":"f","text":"It changes your personality"}],"bins":[{"id":"true","label":"True","valence":"pos"},{"id":"false","label":"False","valence":"neg"}],"key":{"a":"true","b":"false","c":"true","d":"false","e":"true","f":"false"},"relearn":"A fever can mean your body is fighting; tell a trusted adult if it's high.","persona":"any","source":"immune system"},
  {"id":"df-931","cat":"body-defenders","type":"strike-rewrite","hook":"\"A scab is dirty and you should pick it off.\"","myth":{"un":"A scab is just dirt; pick it off.","re":"A scab is a shield your body makes; leave it to do its job.","why":"It protects the new skin growing underneath."},"relearn":"A scab is a shield, not dirt; leave it to protect the healing skin.","persona":"any","source":"immune system"},
  {"id":"df-932","cat":"body-defenders","type":"strike-rewrite","hook":"\"If you're healthy, your immune system isn't doing anything.\"","myth":{"un":"When I feel fine, my defences are switched off.","re":"Your immune system works around the clock, even when you feel great.","why":"Feeling well often means it's quietly winning."},"relearn":"Your immune system works all the time, even when you feel perfectly well.","persona":"Asha","source":"immune system"},
  {"id":"df-933","cat":"body-defenders","type":"strike-rewrite","hook":"\"A fever is always dangerous and means something is badly wrong.\"","myth":{"un":"Any fever means something is badly wrong.","re":"A mild fever is often your body fighting germs; tell an adult if it's high.","why":"It's usually your defence team at work, not a disaster."},"relearn":"A mild fever is often your body fighting; tell a trusted adult if it gets high.","persona":"any","source":"immune system"},
  {"id":"df-934","cat":"body-defenders","type":"strike-rewrite","hook":"\"Eating one orange will stop you ever getting sick.\"","myth":{"un":"One healthy food makes you germ-proof.","re":"Good food helps your defenders, but no single food blocks all germs.","why":"Habits over time matter more than one magic snack."},"relearn":"Good food helps your defences over time; no single food makes you germ-proof.","persona":"Rohit","source":"immune system / health literacy"},
  {"id":"df-935","cat":"body-defenders","type":"strike-rewrite","hook":"\"White blood cells only work when you take medicine.\"","myth":{"un":"My white blood cells only fight if I take medicine.","re":"White blood cells fight germs on their own, every day.","why":"Medicine sometimes helps, but your defenders never wait for it."},"relearn":"White blood cells fight germs on their own; they don't wait for medicine.","persona":"Asha","source":"immune system"},
  {"id":"df-936","cat":"body-defenders","type":"strike-rewrite","hook":"\"You can wash germs away with water alone, no soap.\"","myth":{"un":"Plain water washes all germs off your hands.","re":"Soap lifts germs off far better; use soap and water.","why":"Soap grabs germs so the water can rinse them away."},"relearn":"Soap lifts germs far better than water alone; use both.","persona":"any","source":"immune system / prevention"},
  {"id":"df-937","cat":"body-defenders","type":"strike-rewrite","hook":"\"Some kids are just born with no defences at all.\"","myth":{"un":"Some kids have no body defences at all.","re":"Every child is born with a defence team that grows stronger over time.","why":"Everyone's immune system learns as they grow."},"relearn":"Every child has a defence team that grows stronger over time.","persona":"Aarav","source":"immune system / anti-stigma"},
  {"id":"df-938","cat":"body-defenders","type":"strike-rewrite","hook":"\"Take an antibiotic and any cold or flu goes away fast.\"","myth":{"un":"Antibiotics cure colds and the flu.","re":"Colds and flu are viruses, and antibiotics only work on bacteria.","why":"Your own defenders clear the virus; the pill does nothing to it."},"relearn":"Antibiotics fight bacteria, not the viruses behind colds and flu.","persona":"Rohit","source":"immune system / prevention"},
  {"id":"df-939","cat":"body-defenders","type":"strike-rewrite","hook":"\"Vaccines put the disease into you and make you ill.\"","myth":{"un":"A vaccine gives you the disease.","re":"A vaccine teaches your defenders to recognise a germ, without the illness.","why":"It's a practice drill, not the real infection."},"relearn":"A vaccine teaches your defenders to recognise a germ, without giving you the disease.","persona":"Asha","source":"prevention / vaccines"},
  {"id":"df-940","cat":"body-defenders","type":"reflect","hook":"Lensy: right now, your defence team is on duty. Want to thank it?","prompt":"What do you think?","options":["Thanks, team","My body's got my back","Pretty amazing"],"affirm":"Your defenders work for you all day and night, for free.","relearn":"Your body defends you constantly, even when you're not thinking about it.","persona":"any","source":"immune system"},
  {"id":"df-941","cat":"body-defenders","type":"reflect","hook":"Lensy: which defender do you find most surprising?","prompt":"Pick one.","options":["Stomach acid","White blood cells","Tears and snot"],"affirm":"Every one of them is on your side, doing a real job.","relearn":"Even the surprising defenders, like stomach acid, are working for you.","persona":"any","source":"immune system"},
  {"id":"df-942","cat":"body-defenders","type":"reflect","hook":"Lensy: a fever can mean your body is fighting. Does that change how you see it?","prompt":"What do you think?","options":["Less scary now","It's my team working","Good to know"],"affirm":"A fever is often your defenders turning up the heat on germs.","relearn":"Knowing a fever can be your body fighting makes it less scary.","persona":"any","source":"immune system"},
  {"id":"df-943","cat":"body-defenders","type":"reflect","hook":"Lensy: you can help your defenders with simple habits. Which feels easiest?","prompt":"Pick one.","options":["Sleep well","Drink clean water","Eat fresh food"],"affirm":"Small, steady habits are real gifts to your defence team.","relearn":"Simple daily habits help your body's defenders do their job.","persona":"any","source":"immune system / prevention"},
  {"id":"df-944","cat":"body-defenders","type":"reflect","hook":"Lensy: recovering from a cold shows your defences won. How does that feel?","prompt":"What do you think?","options":["Proud of my body","My team's strong","Reassuring"],"affirm":"Getting better is your immune system quietly winning.","relearn":"Recovering from an illness shows your body's defences work.","persona":"any","source":"immune system"},
  {"id":"df-945","cat":"body-defenders","type":"reflect","hook":"Lensy: anyone can catch a common germ. Does that make 'getting sick' feel less like a fault?","prompt":"What do you think?","options":["Yes, it's normal","Not my fault","Everyone catches germs"],"affirm":"Catching a germ is normal and never a sign you did something wrong.","relearn":"Anyone can catch a germ; getting sick is not your fault.","persona":"any","source":"immune system / anti-stigma"},
  {"id":"df-946","cat":"body-defenders","type":"reflect","hook":"Lensy: a vaccine is like a practice drill for your defenders. Cool idea?","prompt":"What do you think?","options":["Pretty clever","My team gets to practise","Makes sense"],"affirm":"A vaccine lets your defenders practise before the real germ arrives.","relearn":"A vaccine trains your defenders in advance, before a germ ever strikes.","persona":"any","source":"prevention / vaccines"},
  {"id":"df-947","cat":"body-defenders","type":"reflect","hook":"Lensy: your skin is healing a tiny scratch even now. Amazing or what?","prompt":"What do you think?","options":["Amazing","Skin's a builder","Go skin"],"affirm":"Your skin quietly repairs itself, day after day.","relearn":"Your skin heals small scratches on its own, all the time.","persona":"any","source":"immune system"},
  {"id":"df-948","cat":"body-defenders","type":"reflect","hook":"Lensy: which habit will you give your defenders today?","prompt":"Pick one.","options":["A good night's sleep","Clean water","A proper meal"],"affirm":"Choosing one kind habit for your body is a real win.","relearn":"Picking one healthy habit each day supports your body's defenders.","persona":"any","source":"immune system / prevention"},
  {"id":"df-949","cat":"body-defenders","type":"spot","hook":"A child recovering from a cold. Spot the defenders doing their work.","scene":[{"id":"a","text":"A runny nose flushing out germs","trick":true},{"id":"b","text":"The blanket is red","trick":false},{"id":"c","text":"A mild fever heating the germs","trick":true},{"id":"d","text":"It's raining outside","trick":false},{"id":"e","text":"The clock reads three","trick":false}],"why":"A runny nose and mild fever can both be your defenders clearing the germs.","relearn":"A runny nose and a mild fever can be your body's defenders at work.","persona":"any","source":"immune system"},
  {"id":"df-950","cat":"body-defenders","type":"spot","hook":"At dinner, building strong defences. Spot the choices that help.","scene":[{"id":"a","text":"A plate of dal, rice and veg","trick":true},{"id":"b","text":"The plate is steel","trick":false},{"id":"c","text":"A glass of clean, boiled water","trick":true},{"id":"d","text":"The fan is spinning","trick":false},{"id":"e","text":"A poster on the wall","trick":false}],"why":"A balanced meal and clean water both feed and protect your defenders.","relearn":"Balanced food and clean water are everyday gifts to your defence team.","persona":"Rohit","source":"immune system / prevention"},
  {"id":"df-951","cat":"body-defenders","type":"spot","hook":"A handwashing moment. Spot what actually helps your defences.","scene":[{"id":"a","text":"Rubbing soap over all the hand","trick":true},{"id":"b","text":"The soap smells of lemon","trick":false},{"id":"c","text":"Rinsing well under clean water","trick":true},{"id":"d","text":"The tap is shiny","trick":false},{"id":"e","text":"A towel hangs nearby","trick":false}],"why":"Soaping every part and rinsing well are what remove the germs.","relearn":"Soaping all over and rinsing well are what make handwashing work.","persona":"any","source":"immune system / prevention"},
  {"id":"df-952","cat":"body-defenders","type":"spot","hook":"A poster about your immune system. Spot the true facts.","scene":[{"id":"a","text":"\"Your body defends you every day\"","trick":true},{"id":"b","text":"The poster is laminated","trick":false},{"id":"c","text":"\"Sleep and food keep defences strong\"","trick":true},{"id":"d","text":"It's pinned with a tack","trick":false},{"id":"e","text":"The corner is folded","trick":false}],"why":"Both messages are true: your body defends you, and habits keep it strong.","relearn":"True facts: your body defends you daily, and good habits keep it strong.","persona":"Asha","source":"immune system"},
  {"id":"df-953","cat":"body-defenders","type":"spot","hook":"A scraped elbow over a week. Spot the healing steps.","scene":[{"id":"a","text":"Blood clots to stop the bleeding","trick":true},{"id":"b","text":"The sleeve is torn","trick":false},{"id":"c","text":"A scab forms over the graze","trick":true},{"id":"d","text":"It happened at the park","trick":false},{"id":"e","text":"The grass was wet","trick":false}],"why":"Clotting and a scab forming are your defence-and-repair team in action.","relearn":"Clotting and scabbing are your body repairing a graze, step by step.","persona":"any","source":"immune system"},
  {"id":"df-954","cat":"body-defenders","type":"spot","hook":"A 'keep your defenders strong' chart. Spot the real tips.","scene":[{"id":"a","text":"\"Get enough sleep\"","trick":true},{"id":"b","text":"\"Painted in blue ink\"","trick":false},{"id":"c","text":"\"Drink clean water\"","trick":true},{"id":"d","text":"\"Printed on A4 paper\"","trick":false},{"id":"e","text":"\"Has a border\"","trick":false}],"why":"Sleep and clean water genuinely keep your defences strong.","relearn":"Real tips to keep defences strong: enough sleep and clean water.","persona":"Rohit","source":"immune system / prevention"},
  {"id":"df-955","cat":"body-defenders","type":"spot","hook":"A vaccine-day leaflet. Spot the accurate lines.","scene":[{"id":"a","text":"\"Vaccines train your defenders\"","trick":true},{"id":"b","text":"\"The clinic opens at nine\"","trick":false},{"id":"c","text":"\"They protect before a germ strikes\"","trick":true},{"id":"d","text":"\"Bring your card\"","trick":false},{"id":"e","text":"\"The room is upstairs\"","trick":false}],"why":"Both health facts are true: vaccines train defenders and protect in advance.","relearn":"Accurate facts: vaccines train your defenders and protect you in advance.","persona":"Asha","source":"prevention / vaccines"},
  {"id":"df-956","cat":"body-defenders","type":"role-play","hook":"A younger cousin says a fever means they're being punished.","setup":"Reassure them calmly. Say:","yourLine":[{"text":"\"A fever often means your body is fighting germs.\"","best":true},{"text":"\"Yeah, maybe you did something bad.\""}],"relearn":"A fever is often your body fighting germs, not a punishment.","persona":"Asha","source":"immune system"},
  {"id":"df-957","cat":"body-defenders","type":"role-play","hook":"A friend wants to pick their scab off because it 'looks gross'.","setup":"Explain why to leave it. Say:","yourLine":[{"text":"\"Leave it, the scab is a shield while your skin heals.\"","best":true},{"text":"\"Yeah, just rip it off.\""}],"relearn":"A scab is a shield protecting the new skin; leave it to heal.","persona":"any","source":"immune system"},
  {"id":"df-958","cat":"body-defenders","type":"role-play","hook":"Someone says washing hands is pointless if they look clean.","setup":"Share the fact kindly. Say:","yourLine":[{"text":"\"Hands can look clean but still carry germs, soap helps.\"","best":true},{"text":"\"True, skip the soap then.\""}],"relearn":"Hands can look clean but still carry germs; wash with soap.","persona":"any","source":"immune system / prevention"},
  {"id":"df-959","cat":"body-defenders","type":"role-play","hook":"A classmate is scared of getting a vaccine at school.","setup":"Encourage them gently. Say:","yourLine":[{"text":"\"It's a quick pinch that trains your defenders, you've got this.\"","best":true},{"text":"\"Yeah, vaccines are scary, maybe skip it.\""}],"relearn":"A vaccine is a quick pinch that gives your defenders lasting practice.","persona":"Asha","source":"prevention / vaccines"},
  {"id":"df-960","cat":"body-defenders","type":"role-play","hook":"A friend says they're 'weak' because they caught a cold.","setup":"Reassure them. Say:","yourLine":[{"text":"\"Anyone catches colds; recovering shows your defences work.\"","best":true},{"text":"\"Yeah, you must be really weak.\""}],"relearn":"Catching a cold is normal; recovering shows your defences work.","persona":"Aarav","source":"immune system / anti-stigma"},
  {"id":"df-961","cat":"body-defenders","type":"role-play","hook":"Your sibling says skipping sleep makes them tougher.","setup":"Set them straight, kindly. Say:","yourLine":[{"text":"\"Sleep is when your defenders recharge, it keeps you stronger.\"","best":true},{"text":"\"Sure, sleep is for the weak.\""}],"relearn":"Sleep recharges your defenders and keeps you stronger, not weaker.","persona":"Rohit","source":"immune system / prevention"},
  {"id":"df-962","cat":"body-defenders","type":"role-play","hook":"A friend wants to drink straight from a roadside puddle on a hot day.","setup":"Suggest a safer choice. Say:","yourLine":[{"text":"\"Let's get clean water, puddles carry tummy germs.\"","best":true},{"text":"\"Go ahead, a sip won't matter.\""}],"relearn":"Clean water protects you from tummy germs; avoid drinking from puddles.","persona":"any","source":"immune system / prevention"},
  {"id":"df-963","cat":"body-defenders","type":"role-play","hook":"A younger kid thinks white blood cells only work if you take medicine.","setup":"Correct it warmly. Say:","yourLine":[{"text":"\"Your white blood cells fight germs on their own, every day.\"","best":true},{"text":"\"Right, they only work with pills.\""}],"relearn":"White blood cells fight germs on their own, without waiting for medicine.","persona":"Asha","source":"immune system"},
  {"id":"df-964","cat":"body-defenders","type":"branch","hook":"You scraped your knee and a scab has formed; it itches a bit.","options":[{"text":"Leave the scab alone and let it heal","consequence":"The new skin underneath stays protected.","outcome":"healthy","best":true},{"text":"Pick the scab off because it itches","consequence":"The scab is a shield; picking it can reopen the cut."}],"debrief":"A scab is your body's shield; leaving it lets the skin heal cleanly.","relearn":"Leave a scab to do its job; it protects the healing skin.","persona":"any","source":"immune system"},
  {"id":"df-965","cat":"body-defenders","type":"branch","hook":"You feel a mild fever coming on during a cold.","options":[{"text":"Rest, drink fluids, and tell a trusted adult","consequence":"You support your defenders and get help if needed.","outcome":"calm","best":true},{"text":"Panic and assume the worst","consequence":"A mild fever is often your body fighting; rest and tell an adult."}],"debrief":"A mild fever is often your defence team working; rest and tell an adult.","relearn":"With a mild fever, rest, take fluids, and tell a trusted adult.","persona":"any","source":"immune system"},
  {"id":"df-966","cat":"body-defenders","type":"branch","hook":"It's vaccine day at school and you feel nervous.","options":[{"text":"Get the vaccine; a quick pinch trains your defenders","consequence":"You gain lasting protection from a serious disease.","outcome":"brave","best":true},{"text":"Hide and skip it","consequence":"A moment's pinch gives lasting protection; it's worth it."}],"debrief":"A vaccine gives your defenders a big head start for one quick pinch.","relearn":"Vaccines give lasting protection for a moment's pinch.","persona":"Asha","source":"prevention / vaccines"},
  {"id":"df-967","cat":"body-defenders","type":"branch","hook":"You're about to eat a snack but your hands are dusty from play.","options":[{"text":"Wash with soap and water first","consequence":"You remove germs before they reach your mouth.","outcome":"healthy","best":true},{"text":"Just eat, the dust looks harmless","consequence":"Washing first stops invisible germs from hitching a ride in."}],"debrief":"Washing hands before eating is one of the best defences there is.","relearn":"Wash hands with soap before eating to keep germs out.","persona":"any","source":"immune system / prevention"},
  {"id":"df-968","cat":"body-defenders","type":"branch","hook":"You're tired but want to stay up late again all week.","options":[{"text":"Get a proper night's sleep","consequence":"Your defenders recharge and guard you better.","outcome":"healthy","best":true},{"text":"Skip sleep every night","consequence":"Sleep is when your defenders recharge; skipping it wears them down."}],"debrief":"Good sleep recharges your defence team so it can protect you.","relearn":"A good night's sleep recharges your defenders.","persona":"Rohit","source":"immune system / prevention"},
  {"id":"df-969","cat":"body-defenders","type":"branch","hook":"You're recovering from a stomach bug and a friend offers shared street water.","options":[{"text":"Choose clean, boiled or filtered water","consequence":"You protect your recovering tummy from more germs.","outcome":"healthy","best":true},{"text":"Drink the shared street water","consequence":"Clean water protects your tummy while it recovers."}],"debrief":"Clean water backs up your defences, especially while you recover.","relearn":"Pick clean, boiled or filtered water to protect your tummy.","persona":"any","source":"immune system / prevention"},
  {"id":"df-970","cat":"body-defenders","type":"branch","hook":"A friend says 'eat this one fruit and you'll never get sick again'.","options":[{"text":"Enjoy it, but keep all your healthy habits","consequence":"Good food helps; steady habits matter more than one snack.","outcome":"sensible","best":true},{"text":"Skip washing hands, the fruit 'protects' you","consequence":"No single food blocks all germs; keep your habits too."}],"debrief":"Good food helps, but no one food makes you germ-proof.","relearn":"Healthy food helps, but no single food makes you germ-proof.","persona":"Aarav","source":"immune system / health literacy"},
  {"id":"df-972","cat":"body-defenders","type":"match","hook":"Match the defender to a true fact you can tell a worried friend.","pairs":[{"left":"Your immune system","right":"Defends you all day"},{"left":"A scab","right":"Protects a healing cut"},{"left":"A mild fever","right":"Can mean you're fighting germs"},{"left":"Vaccines","right":"Train your defenders early"},{"left":"Recovering","right":"Shows your defences work"}],"relearn":"Calm, true facts about your body are easy to share with a friend.","persona":"Asha","source":"immune system / health literacy"},
  {"id":"df-971","cat":"body-defenders","type":"branch","hook":"You're getting over a cough and a friend asks to share your cup.","options":[{"text":"Offer a fresh cup since you're still recovering","consequence":"You protect your friend kindly while you heal.","outcome":"caring","best":true},{"text":"Share the same cup anyway","consequence":"A fresh cup protects your friend while you recover."}],"debrief":"Not sharing mouth-touched things while recovering protects others too.","relearn":"While recovering, offer a fresh cup instead of sharing your own.","persona":"any","source":"immune system / prevention"},
  {"id":"df-990","cat":"defend-yourself","type":"sort","hook":"Sort: when should you wash your hands with soap?","items":[{"id":"a","text":"After using the toilet"},{"id":"b","text":"Before eating a meal"},{"id":"c","text":"Only on your birthday"},{"id":"d","text":"After playing outside in the mud"},{"id":"e","text":"Never, water alone is enough every time"},{"id":"f","text":"After helping clean up a sick sibling"}],"bins":[{"id":"wash","label":"Wash now","valence":"pos"},{"id":"skip","label":"Not a soap moment","valence":"neg"}],"key":{"a":"wash","b":"wash","c":"skip","d":"wash","e":"skip","f":"wash"},"relearn":"Wash with soap before eating and after the toilet, play or sickness.","persona":"any","source":"prevention"},
  {"id":"df-991","cat":"defend-yourself","type":"sort","hook":"Sort: safe to drink, or not?","items":[{"id":"a","text":"Boiled and cooled water"},{"id":"b","text":"Water from a puddle after rain"},{"id":"c","text":"Filtered water from a clean pot"},{"id":"d","text":"Water from a stagnant pond"},{"id":"e","text":"Sealed packaged water"},{"id":"f","text":"Water with bits floating in it"}],"bins":[{"id":"safe","label":"Safe to drink","valence":"pos"},{"id":"unsafe","label":"Risky","valence":"neg"}],"key":{"a":"safe","b":"unsafe","c":"safe","d":"unsafe","e":"safe","f":"unsafe"},"relearn":"Boiled, filtered or sealed water is safe; puddles and ponds are not.","persona":"any","source":"prevention / clean water"},
  {"id":"df-992","cat":"defend-yourself","type":"sort","hook":"Sort: a calm prevention habit, or a fear myth?","items":[{"id":"a","text":"Covering a sneeze with your elbow"},{"id":"b","text":"Refusing to ever leave the house"},{"id":"c","text":"Getting your shots on time"},{"id":"d","text":"Burning herbs to scare germs away"},{"id":"e","text":"Washing hands before cooking"},{"id":"f","text":"Wearing a lucky thread instead of washing"}],"bins":[{"id":"habit","label":"Real habit","valence":"pos"},{"id":"myth","label":"Fear myth","valence":"neg"}],"key":{"a":"habit","b":"myth","c":"habit","d":"myth","e":"habit","f":"myth"},"relearn":"Prevention is calm, sensible habits, not fear or charms.","persona":"Asha","source":"prevention"},
  {"id":"df-993","cat":"defend-yourself","type":"sort","hook":"Sort: which germ route does each habit block?","items":[{"id":"a","text":"Covering your cough"},{"id":"b","text":"Boiling drinking water"},{"id":"c","text":"Washing hands with soap"},{"id":"d","text":"Opening a window for fresh air"},{"id":"e","text":"Filtering muddy water"},{"id":"f","text":"Not touching your face with dirty hands"}],"bins":[{"id":"air","label":"Germs in air","valence":"neutral"},{"id":"water","label":"Germs in water","valence":"neutral"},{"id":"hands","label":"Germs on hands","valence":"neutral"}],"key":{"a":"air","b":"water","c":"hands","d":"air","e":"water","f":"hands"},"relearn":"Each habit blocks a specific route: air, water or hands.","persona":"any","source":"prevention"},
  {"id":"df-994","cat":"defend-yourself","type":"sort","hook":"Sort: covering a cough the right way, or not?","items":[{"id":"a","text":"Cough into the bend of your elbow"},{"id":"b","text":"Cough into your bare hands then shake hands"},{"id":"c","text":"Cough into a tissue, then bin it"},{"id":"d","text":"Cough openly at the dinner table"},{"id":"e","text":"Turn away and cough into your sleeve"},{"id":"f","text":"Cough toward your little brother for fun"}],"bins":[{"id":"right","label":"Right way","valence":"pos"},{"id":"wrong","label":"Spreads germs","valence":"neg"}],"key":{"a":"right","b":"wrong","c":"right","d":"wrong","e":"right","f":"wrong"},"relearn":"Cough into your elbow or a tissue, never bare hands or at people.","persona":"any","source":"prevention"},
  {"id":"df-995","cat":"defend-yourself","type":"sort","hook":"Sort: protects others when you're sick, or not?","items":[{"id":"a","text":"Resting at home till you're better"},{"id":"b","text":"Going to a crowded fair with a fever"},{"id":"c","text":"Using your own cup and plate"},{"id":"d","text":"Letting friends sip from your bottle"},{"id":"e","text":"Telling a grown-up you feel unwell"},{"id":"f","text":"Hiding your cough so you can play"}],"bins":[{"id":"protects","label":"Protects others","valence":"pos"},{"id":"risks","label":"Risks others","valence":"neg"}],"key":{"a":"protects","b":"risks","c":"protects","d":"risks","e":"protects","f":"risks"},"relearn":"Resting and not sharing mouth-touched things keeps others safe too.","persona":"any","source":"prevention"},
  {"id":"df-996","cat":"defend-yourself","type":"sort","hook":"Sort: a real reason vaccines help, or a made-up scare?","items":[{"id":"a","text":"They teach defenders to know a germ early"},{"id":"b","text":"They put a chip inside you"},{"id":"c","text":"They stop some serious diseases for years"},{"id":"d","text":"They steal your shadow"},{"id":"e","text":"A quick pinch gives lasting protection"},{"id":"f","text":"They make you forget your friends"}],"bins":[{"id":"real","label":"Real reason","valence":"pos"},{"id":"scare","label":"Made-up scare","valence":"neg"}],"key":{"a":"real","b":"scare","c":"real","d":"scare","e":"real","f":"scare"},"relearn":"Vaccines train your defenders; the scary stories are just made up.","persona":"Asha","source":"prevention / vaccines"},
  {"id":"df-997","cat":"defend-yourself","type":"sort","hook":"Sort: keeps street food safer, or not?","items":[{"id":"a","text":"Food served hot and freshly cooked"},{"id":"b","text":"Cut fruit left open in the dust"},{"id":"c","text":"A stall that keeps food covered"},{"id":"d","text":"Water from an unwashed jug"},{"id":"e","text":"Eating with washed or sanitised hands"},{"id":"f","text":"Sharing one spoon round the whole group"}],"bins":[{"id":"safer","label":"Safer choice","valence":"pos"},{"id":"riskier","label":"Riskier choice","valence":"neg"}],"key":{"a":"safer","b":"riskier","c":"safer","d":"riskier","e":"safer","f":"riskier"},"relearn":"Hot, covered food and clean hands make eating out safer.","persona":"any","source":"prevention / India context"},
  {"id":"df-998","cat":"defend-yourself","type":"sort","hook":"Sort: a sensible monsoon habit, or not?","items":[{"id":"a","text":"Drying your feet after wading through water"},{"id":"b","text":"Drinking rainwater straight off the road"},{"id":"c","text":"Boiling water when supply looks murky"},{"id":"d","text":"Eating food a flood touched"},{"id":"e","text":"Covering stored water so flies stay out"},{"id":"f","text":"Wading barefoot through a drain"}],"bins":[{"id":"sensible","label":"Sensible","valence":"pos"},{"id":"risky","label":"Risky","valence":"neg"}],"key":{"a":"sensible","b":"risky","c":"sensible","d":"risky","e":"sensible","f":"risky"},"relearn":"In the rains, keep water clean and covered and dry off after wading.","persona":"any","source":"prevention / India context"},
  {"id":"df-999","cat":"defend-yourself","type":"sort","hook":"Sort: lowers your chance of a tummy bug, or not?","items":[{"id":"a","text":"Washing hands before serving food"},{"id":"b","text":"Eating with hands you didn't wash"},{"id":"c","text":"Keeping cooked food covered"},{"id":"d","text":"Leaving milk out in the heat all day"},{"id":"e","text":"Rinsing veggies before cutting"},{"id":"f","text":"Drinking water you scooped from a tank"}],"bins":[{"id":"lowers","label":"Lowers risk","valence":"pos"},{"id":"raises","label":"Raises risk","valence":"neg"}],"key":{"a":"lowers","b":"raises","c":"lowers","d":"raises","e":"lowers","f":"raises"},"relearn":"Clean hands, covered food and clean water keep tummy bugs away.","persona":"any","source":"prevention"},
  {"id":"df-1000","cat":"defend-yourself","type":"sort","hook":"Sort: helps you get well faster when ill, or not?","items":[{"id":"a","text":"Resting and sleeping enough"},{"id":"b","text":"Forcing yourself to play in the sun with a fever"},{"id":"c","text":"Drinking clean fluids"},{"id":"d","text":"Hiding that you feel unwell"},{"id":"e","text":"Telling a trusted grown-up how you feel"},{"id":"f","text":"Skipping every meal on purpose"}],"bins":[{"id":"helps","label":"Helps you heal","valence":"pos"},{"id":"hurts","label":"Sets you back","valence":"neg"}],"key":{"a":"helps","b":"hurts","c":"helps","d":"hurts","e":"helps","f":"hurts"},"relearn":"Rest, clean fluids and telling a grown-up help your body heal.","persona":"any","source":"prevention"},
  {"id":"df-1001","cat":"defend-yourself","type":"sort","hook":"Sort: a clean-water step, or not?","items":[{"id":"a","text":"Boiling water for a rolling minute"},{"id":"b","text":"Adding a pinch of mud for 'minerals'"},{"id":"c","text":"Storing water in a covered, clean pot"},{"id":"d","text":"Dipping dirty hands into the drinking pot"},{"id":"e","text":"Using a clean ladle to pour water out"},{"id":"f","text":"Leaving the pot open near the cooking smoke"}],"bins":[{"id":"clean","label":"Keeps water clean","valence":"pos"},{"id":"dirty","label":"Makes it dirty","valence":"neg"}],"key":{"a":"clean","b":"dirty","c":"clean","d":"dirty","e":"clean","f":"dirty"},"relearn":"Boil, store covered, and pour with a clean ladle to keep water safe.","persona":"any","source":"prevention / clean water"},
  {"id":"df-1002","cat":"defend-yourself","type":"sort","hook":"Sort: smart at a vaccination camp, or not?","items":[{"id":"a","text":"Telling the nurse if you feel faint"},{"id":"b","text":"Running off before your turn out of nerves"},{"id":"c","text":"Keeping your vaccine card safe"},{"id":"d","text":"Believing a rumour that shots are 'poison'"},{"id":"e","text":"Asking a calm question if unsure"},{"id":"f","text":"Daring a friend to skip theirs"}],"bins":[{"id":"smart","label":"Smart move","valence":"pos"},{"id":"notsmart","label":"Not smart","valence":"neg"}],"key":{"a":"smart","b":"notsmart","c":"smart","d":"notsmart","e":"smart","f":"notsmart"},"relearn":"Ask calm questions, keep your card, and trust the camp over rumours.","persona":"Asha","source":"prevention / vaccines"},
  {"id":"df-1003","cat":"defend-yourself","type":"sort","hook":"Sort: stops germs spreading round the house, or not?","items":[{"id":"a","text":"Everyone keeping their own towel"},{"id":"b","text":"Sharing one hankie all day"},{"id":"c","text":"Cleaning shared door handles"},{"id":"d","text":"Coughing over the cooking pot"},{"id":"e","text":"Washing hands before touching shared food"},{"id":"f","text":"Wiping a runny nose on the curtain"}],"bins":[{"id":"stops","label":"Stops spread","valence":"pos"},{"id":"spreads","label":"Helps it spread","valence":"neg"}],"key":{"a":"stops","b":"spreads","c":"stops","d":"spreads","e":"stops","f":"spreads"},"relearn":"Own towels, clean handles and washed hands keep a home healthier.","persona":"any","source":"prevention"},
  {"id":"df-1004","cat":"defend-yourself","type":"branch","hook":"You come home from cricket, hands muddy, and snacks are out.","options":[{"text":"Wash up with soap before you grab a snack","consequence":"Mud and germs go down the drain, not into you.","outcome":"healthy","best":true},{"text":"Brush hands on your shorts and dig in","consequence":"A quick wash first stops germs hitching a ride into your mouth."}],"debrief":"Washing hands before eating is one of the best defences there is.","relearn":"Wash with soap before you eat, even after a fun game.","persona":"any","source":"prevention"},
  {"id":"df-1005","cat":"defend-yourself","type":"branch","hook":"A sneeze is coming and you're standing in a packed bus.","options":[{"text":"Turn your face down and sneeze into your elbow","consequence":"You catch the germs in your sleeve, not on others.","outcome":"considerate","best":true},{"text":"Sneeze straight ahead, it's quicker","consequence":"Your elbow would have stopped the spray reaching strangers."}],"debrief":"Covering a sneeze into your elbow keeps your germs to yourself.","relearn":"Sneeze into your elbow, even in a crowd, to protect others.","persona":"any","source":"prevention"},
  {"id":"df-1006","cat":"defend-yourself","type":"branch","hook":"At a wedding, the only water around is from an open roadside pot.","options":[{"text":"Ask for sealed or boiled water instead","consequence":"You skip the germs that open, unclean water can carry.","outcome":"sensible","best":true},{"text":"Drink it, you're really thirsty","consequence":"Open roadside water can carry germs; sealed or boiled is safer."}],"debrief":"Choosing clean water over unclean protects you from tummy bugs.","relearn":"When unsure, pick sealed or boiled water over open pots.","persona":"any","source":"prevention / clean water"},
  {"id":"df-1007","cat":"defend-yourself","type":"branch","hook":"You wake with a high fever on exam day and feel awful.","options":[{"text":"Tell a grown-up; rest and get looked after","consequence":"You recover properly and don't spread it around school.","outcome":"caring","best":true},{"text":"Hide it and go anyway","consequence":"Resting helps you heal and keeps your germs away from classmates."}],"debrief":"Staying home when very ill protects you and everyone around you.","relearn":"When very ill, tell a grown-up and rest; it protects everyone.","persona":"any","source":"prevention"},
  {"id":"df-1008","cat":"defend-yourself","type":"branch","hook":"Your cousin offers you a bite of the laddoo he's already nibbling.","options":[{"text":"Break off a clean piece with washed hands","consequence":"You share the treat without sharing mouth germs.","outcome":"clever","best":true},{"text":"Take a bite right where he bit","consequence":"A clean piece lets you share without passing germs along."}],"debrief":"Sharing a clean piece, not mouth-to-mouth, keeps the fun germ-free.","relearn":"Share food in clean pieces, not bite-for-bite.","persona":"any","source":"prevention"},
  {"id":"df-1009","cat":"defend-yourself","type":"branch","hook":"A vaccine camp is at school; a classmate whispers it's 'dangerous'.","options":[{"text":"Ask the nurse your question, then get the shot","consequence":"You get real answers and protection from a quick pinch.","outcome":"brave","best":true},{"text":"Believe the whisper and slip away","consequence":"Asking the nurse beats a rumour; the shot trains your defences."}],"debrief":"A calm question to a health worker beats a scary rumour.","relearn":"Trust health workers and ask questions over rumours.","persona":"Aarav","source":"prevention / vaccines"},
  {"id":"df-1010","cat":"defend-yourself","type":"branch","hook":"Friends dare you to drink straight from the hand-pump stream.","options":[{"text":"Pass, and fill a bottle with water you know is clean","consequence":"You skip the risk and still get a drink.","outcome":"sensible","best":true},{"text":"Take the dare so they don't tease you","consequence":"A dare isn't worth a tummy bug; clean water is the smart drink."}],"debrief":"You don't have to take a dare that could make you ill.","relearn":"Say no to risky-water dares; choose water you trust.","persona":"any","source":"prevention / clean water"},
  {"id":"df-1011","cat":"defend-yourself","type":"branch","hook":"You sneezed into your hand and now everyone's reaching for the snacks.","options":[{"text":"Go wash your hands before you touch the food","consequence":"Germs from your hand don't end up on the shared plate.","outcome":"thoughtful","best":true},{"text":"Wipe on your trousers and grab a samosa","consequence":"Washing first stops sneeze-germs spreading to the whole plate."}],"debrief":"After a sneeze into your hands, wash before touching shared food.","relearn":"Wash sneeze-germs off your hands before shared food.","persona":"any","source":"prevention"},
  {"id":"df-1012","cat":"defend-yourself","type":"branch","hook":"Your little sister has a cough; she wants to drink from your glass.","options":[{"text":"Pour her a fresh glass of her own","consequence":"You both stay well and her germs stay with her.","outcome":"caring","best":true},{"text":"Let her use yours, it's easier","consequence":"A separate glass keeps her cough germs from reaching you."}],"debrief":"Separate cups when someone's sick stop germs passing along.","relearn":"Give a sick person their own cup; don't share when ill.","persona":"any","source":"prevention"},
  {"id":"df-1013","cat":"defend-yourself","type":"branch","hook":"The school tap is running; a friend says 'just rinse, skip the soap'.","options":[{"text":"Use soap and scrub for a slow count of twenty","consequence":"Soap lifts off germs that plain water leaves behind.","outcome":"clean","best":true},{"text":"Just splash water, it's faster","consequence":"Soap and scrubbing remove far more germs than a quick splash."}],"debrief":"Soap and a proper scrub beat a quick rinse every time.","relearn":"Use soap and scrub; a fast water splash isn't enough.","persona":"any","source":"prevention"},
  {"id":"df-1014","cat":"defend-yourself","type":"branch","hook":"You're getting over chickenpox; a neighbour invites you to a crowded mela.","options":[{"text":"Wait till you're fully better before going out","consequence":"You don't pass it on and you heal properly first.","outcome":"responsible","best":true},{"text":"Go anyway, you feel mostly fine","consequence":"Waiting till you're well stops you spreading it in the crowd."}],"debrief":"Wait until you're recovered before heading into a crowd.","relearn":"Recover fully before crowds, so you don't spread an illness.","persona":"any","source":"prevention"},
  {"id":"df-1015","cat":"defend-yourself","type":"branch","hook":"You spot a friend about to drink from a green, slimy pond.","options":[{"text":"Stop them and offer your clean bottle","consequence":"You keep a friend from a tummy bug.","outcome":"kind","best":true},{"text":"Say nothing, it's their choice","consequence":"A quick word and your clean bottle could save your friend a bug."}],"debrief":"Helping a friend choose clean water is a real defence move.","relearn":"Warn a friend off unsafe water; share clean water instead.","persona":"any","source":"prevention / clean water"},
  {"id":"df-1016","cat":"defend-yourself","type":"branch","hook":"Your hands are wet and the only towel is your sick brother's.","options":[{"text":"Air-dry or use a clean cloth instead","consequence":"You don't pick up his germs from a shared towel.","outcome":"smart","best":true},{"text":"Use his towel, it's right there","consequence":"A clean cloth or air-drying avoids the germs on his towel."}],"debrief":"Skip a sick person's towel; use a clean one or air-dry.","relearn":"Don't share a sick person's towel; dry hands a clean way.","persona":"any","source":"prevention"},
  {"id":"df-1017","cat":"defend-yourself","type":"branch","hook":"At a roadside stall the bhel looks great but the water jug looks murky.","options":[{"text":"Skip anything made with that water, pick a hot snack","consequence":"You avoid water-borne germs and still enjoy a treat.","outcome":"sensible","best":true},{"text":"Eat it all, it smells fine","consequence":"Murky water can carry germs; a freshly cooked hot snack is safer."}],"debrief":"When the water looks unclean, choose food that's freshly cooked hot.","relearn":"Avoid food made with murky water; pick hot, fresh snacks.","persona":"any","source":"prevention / India context"},
  {"id":"df-1018","cat":"defend-yourself","type":"strike-rewrite","hook":"\"You only need to wash hands if they look or smell dirty.\"","myth":{"un":"Hands only need washing if they look or smell dirty.","re":"Germs are invisible and have no smell; wash before eating anyway.","why":"You can't see or smell most germs."},"relearn":"Wash before eating even when hands look and smell fine.","persona":"any","source":"prevention"},
  {"id":"df-1019","cat":"defend-yourself","type":"strike-rewrite","hook":"\"Boiling water just makes it hot, it doesn't make it safer.\"","myth":{"un":"Boiling water only heats it; it doesn't make it safer.","re":"Boiling kills the germs in water, then you let it cool to drink.","why":"Heat destroys water-borne germs."},"relearn":"Boiling water kills germs; cool it and it's safer to drink.","persona":"Asha","source":"prevention / clean water"},
  {"id":"df-1020","cat":"defend-yourself","type":"strike-rewrite","hook":"\"Covering your cough is just being fussy.\"","myth":{"un":"Covering your cough is just being fussy.","re":"Covering a cough stops tiny germ droplets reaching other people.","why":"Coughs send germs into the air."},"relearn":"Covering a cough is real protection, not fussiness.","persona":"any","source":"prevention"},
  {"id":"df-1021","cat":"defend-yourself","type":"strike-rewrite","hook":"\"A strong kid doesn't need vaccines.\"","myth":{"un":"A strong, healthy kid doesn't need vaccines.","re":"Even strong bodies meet germs they've never faced; vaccines prepare them.","why":"Vaccines ready your defences in advance."},"relearn":"Being strong isn't enough; vaccines prepare you for new germs.","persona":"Aarav","source":"prevention / vaccines"},
  {"id":"df-1022","cat":"defend-yourself","type":"strike-rewrite","hook":"\"Hand sanitiser is useless, only soap works.\"","myth":{"un":"Sanitiser is useless; only soap and water work.","re":"Soap and water is best, but sanitiser helps when no tap is near.","why":"Both can cut germs on your hands."},"relearn":"Soap is best; sanitiser is a good backup with no tap around.","persona":"any","source":"prevention"},
  {"id":"df-1023","cat":"defend-yourself","type":"strike-rewrite","hook":"\"If you swallow a few germs, your stomach kills them all anyway.\"","myth":{"un":"Your stomach kills every germ, so unclean water is fine.","re":"Stomach acid stops many germs, but unclean water can still make you ill.","why":"Some water germs get past your defences."},"relearn":"Your stomach helps, but still choose clean water to be safe.","persona":"Asha","source":"prevention / clean water"},
  {"id":"df-1024","cat":"defend-yourself","type":"strike-rewrite","hook":"\"Going out with wet hair gives you a cold.\"","myth":{"un":"Wet hair or cold weather is what gives you a cold.","re":"Colds come from germs spreading, not from being chilly or damp.","why":"A cold is caused by a germ, not the weather."},"relearn":"Colds spread by germs, not by wet hair or cold air.","persona":"any","source":"prevention"},
  {"id":"df-1025","cat":"defend-yourself","type":"strike-rewrite","hook":"\"Staying home when sick is just being lazy.\"","myth":{"un":"Staying home when you're ill is just being lazy.","re":"Resting at home helps you heal and keeps your germs away from others.","why":"Rest aids recovery and stops spread."},"relearn":"Resting when ill is care, not laziness; it protects everyone.","persona":"any","source":"prevention"},
  {"id":"df-1026","cat":"defend-yourself","type":"strike-rewrite","hook":"\"Covering food doesn't matter, a fly landing is harmless.\"","myth":{"un":"A fly on your food is harmless, so why cover it?","re":"Flies carry germs from dirt to food; covering it keeps it cleaner.","why":"Flies move germs onto open food."},"relearn":"Cover food; flies can carry germs onto it.","persona":"any","source":"prevention / India context"},
  {"id":"df-1027","cat":"defend-yourself","type":"spot","hook":"A clinic wall during a vaccine drive. Spot the two scary rumours.","scene":[{"id":"a","text":"The shot trains your defenders to know a germ","trick":false},{"id":"b","text":"A poster lists the day's timings","trick":false},{"id":"c","text":"'Vaccines make you magnetic'","trick":true},{"id":"d","text":"A nurse asks if you feel okay first","trick":false},{"id":"e","text":"'The shot controls your mind'","trick":true}],"why":"Magnetism and mind-control are myths; vaccines just train your defences.","relearn":"Vaccine scare stories are made up; shots train your defenders.","persona":"Asha","source":"prevention / vaccines"},
  {"id":"df-1028","cat":"defend-yourself","type":"spot","hook":"A handwash sink. Spot the two things that DON'T make it work.","scene":[{"id":"a","text":"Rubbing soap over all parts of your hands","trick":false},{"id":"b","text":"Scrubbing for a slow count of twenty","trick":false},{"id":"c","text":"Just waving hands under water for a second","trick":true},{"id":"d","text":"Rinsing the soap off well","trick":false},{"id":"e","text":"Drying on a dirty cloth that was on the floor","trick":true}],"why":"A one-second splash and a dirty towel undo a good wash.","relearn":"Soap, scrub time and a clean dry make handwashing work.","persona":"any","source":"prevention"},
  {"id":"df-1029","cat":"defend-yourself","type":"spot","hook":"A water-storage corner. Spot the two habits that spoil clean water.","scene":[{"id":"a","text":"Water was boiled before storing","trick":false},{"id":"b","text":"The pot has a lid on it","trick":false},{"id":"c","text":"People dip dirty hands in to scoop water","trick":true},{"id":"d","text":"A clean ladle hangs beside the pot","trick":false},{"id":"e","text":"The lid is left off near the bin","trick":true}],"why":"Dipping dirty hands and leaving the pot open let germs back in.","relearn":"Keep stored water covered and scoop with a clean ladle.","persona":"any","source":"prevention / clean water"},
  {"id":"df-1030","cat":"defend-yourself","type":"spot","hook":"A street-food stall. Spot the two safer-eating signs.","scene":[{"id":"a","text":"Food is cooked fresh and served hot","trick":true},{"id":"b","text":"The stall has a colourful banner","trick":false},{"id":"c","text":"There's a chair to sit on","trick":false},{"id":"d","text":"The cook keeps the food covered","trick":true},{"id":"e","text":"Loud music is playing","trick":false}],"why":"Hot, freshly cooked and covered food is the safer choice.","relearn":"Look for hot, fresh, covered food when eating out.","persona":"any","source":"prevention / India context"},
  {"id":"df-1031","cat":"defend-yourself","type":"spot","hook":"A sick-day room. Spot the two habits that protect the family.","scene":[{"id":"a","text":"The patient uses their own cup and plate","trick":true},{"id":"b","text":"A fan is switched on","trick":false},{"id":"c","text":"They rest and stay home from school","trick":true},{"id":"d","text":"A clock ticks on the wall","trick":false},{"id":"e","text":"A water jug sits on the table","trick":false}],"why":"Own dishes and resting at home stop germs reaching the rest.","relearn":"When ill, use your own dishes and rest to protect the family.","persona":"any","source":"prevention"},
  {"id":"df-1032","cat":"defend-yourself","type":"spot","hook":"A monsoon kitchen. Spot the two water-safety moves.","scene":[{"id":"a","text":"Drinking water is boiled and cooled","trick":true},{"id":"b","text":"An umbrella drips by the door","trick":false},{"id":"c","text":"Stored water is kept tightly covered","trick":true},{"id":"d","text":"The window is open for air","trick":false},{"id":"e","text":"A radio plays the news","trick":false}],"why":"In the rains, boiled and covered water keeps water-borne germs out.","relearn":"During monsoon, boil and cover drinking water.","persona":"any","source":"prevention / India context"},
  {"id":"df-1033","cat":"defend-yourself","type":"spot","hook":"A playground. Spot the two real germ-defence habits.","scene":[{"id":"a","text":"Washing hands before sharing the lunchbox","trick":true},{"id":"b","text":"The slide is painted red","trick":false},{"id":"c","text":"Covering a sneeze with your elbow","trick":true},{"id":"d","text":"A kite is stuck in a tree","trick":false},{"id":"e","text":"The bell rings for break","trick":false}],"why":"Washed hands and a covered sneeze are everyday defences.","relearn":"Wash before sharing food and cover your sneezes at play.","persona":"any","source":"prevention"},
  {"id":"df-1034","cat":"defend-yourself","type":"match","hook":"Match the moment to the right prevention move.","pairs":[{"left":"Before eating a meal","right":"Wash your hands with soap"},{"left":"A sneeze coming in a crowd","right":"Cover it with your elbow"},{"left":"Water looks murky","right":"Boil it first"},{"left":"You have a high fever","right":"Rest and stay home"},{"left":"A vaccine camp at school","right":"Get the shot"}],"relearn":"The right move matches the moment, from washing to resting.","persona":"any","source":"prevention"},
  {"id":"df-1035","cat":"defend-yourself","type":"match","hook":"Match each part of a proper handwash to what it does.","pairs":[{"left":"Soap","right":"Lifts germs off skin"},{"left":"Scrubbing for twenty","right":"Loosens stubborn germs"},{"left":"Covering all parts","right":"Reaches between fingers"},{"left":"Rinsing well","right":"Washes germs away"},{"left":"Drying clean","right":"Stops picking up new germs"}],"relearn":"Each handwash step has its own job in removing germs.","persona":"any","source":"prevention"},
  {"id":"df-1036","cat":"defend-yourself","type":"match","hook":"Match the unsafe thing to the safer swap.","pairs":[{"left":"Puddle water","right":"Boiled water"},{"left":"Coughing in bare hands","right":"Coughing in your elbow"},{"left":"Sharing a sick friend's cup","right":"Using your own cup"},{"left":"Open, fly-covered food","right":"Covered food"},{"left":"A skipped vaccine","right":"A shot on time"}],"relearn":"For each risky habit there's a simple, safer swap.","persona":"any","source":"prevention"},
  {"id":"df-1037","cat":"defend-yourself","type":"match","hook":"Match the germ route to the habit that blocks it.","pairs":[{"left":"Germs in the air","right":"Cover your cough"},{"left":"Germs on your hands","right":"Wash with soap"},{"left":"Germs in water","right":"Boil before drinking"},{"left":"Germs on open food","right":"Keep it covered"},{"left":"Germs from a new disease","right":"Get vaccinated"}],"relearn":"Match each germ route to the habit that shuts it down.","persona":"Asha","source":"prevention"},
  {"id":"df-1038","cat":"defend-yourself","type":"match","hook":"Match each helper to how they keep you well.","pairs":[{"left":"ASHA worker","right":"Brings vaccines and health advice"},{"left":"Clean water pot","right":"Stores safe drinking water"},{"left":"Soap bar","right":"Washes germs off hands"},{"left":"A good night's rest","right":"Helps your body heal"},{"left":"A covered tiffin","right":"Keeps food germ-free"}],"relearn":"People and simple tools each help keep you healthy.","persona":"any","source":"prevention / India context"},
  {"id":"df-1039","cat":"defend-yourself","type":"match","hook":"Match the question to who can answer it best.","pairs":[{"left":"Is this vaccine safe?","right":"Ask the nurse or ASHA worker"},{"left":"My fever won't go","right":"See a doctor"},{"left":"How do I wash hands right?","right":"Follow the clinic poster"},{"left":"Is this water safe?","right":"Boil it to be sure"},{"left":"I feel unwell at school","right":"Tell a trusted grown-up"}],"relearn":"For each health question there's a trusted place to turn.","persona":"any","source":"prevention"},
  {"id":"df-1040","cat":"defend-yourself","type":"reflect","hook":"Lensy: which prevention habit feels easiest to start today?","prompt":"Pick the one you'll try first.","options":["Wash hands before meals","Cover my coughs","Drink only clean water","Rest properly when ill"],"affirm":"Any habit you choose, repeated, keeps you and others well.","relearn":"Picking one habit to begin makes prevention feel doable.","persona":"any","source":"prevention"},
  {"id":"df-1041","cat":"defend-yourself","type":"reflect","hook":"Lensy: where would you put up a handwashing reminder at home?","prompt":"Pick a spot.","options":["By the kitchen tap","Near the toilet","On the dining wall","By the front door"],"affirm":"A reminder where you'll see it makes a habit stick.","relearn":"A well-placed reminder helps a good habit become routine.","persona":"any","source":"prevention"},
  {"id":"df-1042","cat":"defend-yourself","type":"reflect","hook":"Lensy: who would you tell first if you felt really unwell?","prompt":"Pick who you'd turn to.","options":["A parent","A grandparent","A teacher","The school nurse"],"affirm":"Telling someone you trust is a strong first move when you're ill.","relearn":"Knowing who you'd tell makes asking for help easier.","persona":"any","source":"prevention"},
  {"id":"df-1043","cat":"defend-yourself","type":"reflect","hook":"Lensy: how do you feel about your next vaccine?","prompt":"Pick what fits.","options":["Calm, it's quick","A bit nervous","Curious how it works","Glad it protects me"],"affirm":"However you feel, asking a health worker your questions helps.","relearn":"Naming how you feel about a shot makes it easier to face.","persona":"Asha","source":"prevention / vaccines"},
  {"id":"df-1044","cat":"defend-yourself","type":"reflect","hook":"Lensy: which clean-water habit could your family build on?","prompt":"Pick one to talk about at home.","options":["Boiling drinking water","Covering the water pot","Using a clean ladle","Storing water somewhere clean"],"affirm":"Sharing one idea at home can keep the whole family healthier.","relearn":"Talking over one water habit helps the family stay well.","persona":"any","source":"prevention / clean water"},
  {"id":"df-1045","cat":"defend-yourself","type":"reflect","hook":"Lensy: what helps you remember to cover a cough?","prompt":"Pick your trick.","options":["Aim for my elbow","Keep a tissue handy","Turn away first","Picture the germs"],"affirm":"Whatever cue works for you, covering coughs protects others.","relearn":"Your own reminder makes covering a cough automatic.","persona":"any","source":"prevention"},
  {"id":"df-1046","cat":"defend-yourself","type":"reflect","hook":"Lensy: which prevention skill do you feel proudest of?","prompt":"Pick the one you've got down.","options":["Proper handwashing","Covering my sneezes","Choosing clean water","Resting when I'm ill"],"affirm":"Calm, everyday habits like these are a real strength.","relearn":"Noticing a skill you've built keeps you doing it.","persona":"any","source":"prevention"},
  {"id":"df-1047","cat":"defend-yourself","type":"role-play","hook":"A friend says 'skip the soap, the water's enough'.","setup":"Speak up for a proper wash. Say:","yourLine":[{"text":"\"Soap gets the germs off, it only takes a few seconds.\"","best":true},{"text":"\"Yeah, water's fine I guess.\""}],"relearn":"You can stand by soap without making it awkward.","persona":"any","source":"prevention / voice"},
  {"id":"df-1048","cat":"defend-yourself","type":"role-play","hook":"A cousin offers water from an open roadside pot.","setup":"Ask for a safer option. Say:","yourLine":[{"text":"\"Could I get sealed or boiled water instead? Thanks.\"","best":true},{"text":"\"Okay, I'll just drink that.\""}],"relearn":"It's fine to politely ask for water you trust.","persona":"any","source":"prevention / clean water"},
  {"id":"df-1049","cat":"defend-yourself","type":"role-play","hook":"You're nervous at the vaccine camp and it's your turn.","setup":"Tell the nurse how you feel. Say:","yourLine":[{"text":"\"I'm a bit nervous, can you tell me what happens?\"","best":true},{"text":"Say nothing and try to slip away."}],"relearn":"Saying you're nervous gets you the calm answers you need.","persona":"Asha","source":"prevention / vaccines"},
  {"id":"df-1050","cat":"defend-yourself","type":"role-play","hook":"You're recovering and a friend reaches for your water bottle.","setup":"Protect them kindly. Say:","yourLine":[{"text":"\"Let me get you a fresh cup, I'm still getting over a bug.\"","best":true},{"text":"\"Sure, go ahead and drink from mine.\""}],"relearn":"You can keep a friend safe without any fuss.","persona":"any","source":"prevention"},
  {"id":"df-1051","cat":"defend-yourself","type":"role-play","hook":"Your grandmother is unsure about your school vaccine.","setup":"Reassure her with a calm fact. Say:","yourLine":[{"text":"\"Dadi, the nurse said it just trains my body to fight a germ.\"","best":true},{"text":"\"I don't really know why we get it.\""}],"relearn":"A calm fact can ease an elder's worry about a shot.","persona":"Rohit","source":"prevention / vaccines"},
  {"id":"df-1052","cat":"defend-yourself","type":"role-play","hook":"A friend laughs that washing hands is 'for babies'.","setup":"Hold your ground lightly. Say:","yourLine":[{"text":"\"It keeps germs out of my food, that's not babyish to me.\"","best":true},{"text":"\"Fine, I won't bother then.\""}],"relearn":"You can keep a good habit even if someone teases.","persona":"Aarav","source":"prevention / voice"},
  {"id":"df-1053","cat":"defend-yourself","type":"role-play","hook":"At a picnic everyone wants to share one cup of juice.","setup":"Suggest a safer way. Say:","yourLine":[{"text":"\"Let's pour into separate cups so no one swaps germs.\"","best":true},{"text":"\"Okay, we can all sip from the one cup.\""}],"relearn":"Suggesting separate cups keeps shared fun germ-free.","persona":"any","source":"prevention"},
  {"id":"df-1054","cat":"defend-yourself","type":"role-play","hook":"A younger kid copies you sneezing into bare hands.","setup":"Show them the better way. Say:","yourLine":[{"text":"\"Watch, sneeze into your elbow, like this, so germs stay in.\"","best":true},{"text":"\"Whatever, it doesn't matter.\""}],"relearn":"Showing a younger kid the right move passes on a good habit.","persona":"any","source":"prevention"},
  {"id":"df-1055","cat":"defend-yourself","type":"spot","hook":"Collecting water at the hand-pump. Spot the two clean-water slips.","scene":[{"id":"a","text":"The collecting pot was rinsed clean first","trick":false},{"id":"b","text":"A child carries the lid carefully","trick":false},{"id":"c","text":"Someone sets the pot down in a muddy puddle","trick":true},{"id":"d","text":"The pot is covered for the walk home","trick":false},{"id":"e","text":"A dog drinks straight from the open pot","trick":true}],"why":"Mud under the pot and a dog drinking from it put germs in the water.","relearn":"Keep the collecting pot off the mud and covered from animals.","persona":"any","source":"prevention / clean water"},
  {"id":"df-1056","cat":"defend-yourself","type":"spot","hook":"Deciding whether to go to school today. Spot the two 'stay home' signs.","scene":[{"id":"a","text":"You have a high fever","trick":true},{"id":"b","text":"It's a bit chilly outside","trick":false},{"id":"c","text":"You're throwing up since morning","trick":true},{"id":"d","text":"You didn't finish your homework","trick":false},{"id":"e","text":"You feel a little sleepy","trick":false}],"why":"A high fever or vomiting means rest at home; the others don't.","relearn":"Stay home for a real illness like fever or vomiting, and rest.","persona":"any","source":"prevention"},
  {"id":"df-1057","cat":"defend-yourself","type":"match","hook":"Match the situation to its top prevention concern.","pairs":[{"left":"A dusty street stall","right":"Is the food covered?"},{"left":"After the toilet","right":"Wash hands with soap"},{"left":"A flooded lane","right":"Is the drinking water clean?"},{"left":"A sneezy, crowded bus","right":"Cover your mouth"},{"left":"A school health camp","right":"Get your shots updated"}],"relearn":"Each situation has a top prevention move to keep in mind.","persona":"any","source":"prevention"},
  {"id":"df-1080","cat":"hiv-basics","type":"strike-rewrite","hook":"\"If you have HIV, you can't grow up to work or marry.\"","myth":{"un":"Having HIV stops you having a job or family.","re":"People with HIV study, work, marry and raise families like anyone.","why":"On treatment, HIV doesn't decide your future. You do."},"relearn":"On treatment, people with HIV build full lives: work, family, all of it.","persona":"Asha","source":"HIV basics / treatment"},
  {"id":"df-1081","cat":"hiv-basics","type":"strike-rewrite","hook":"\"HIV medicine has to be taken forever, so it must not really work.\"","myth":{"un":"Daily medicine for life means HIV is winning.","re":"Daily medicine keeps the virus so low that people stay well for life.","why":"Like glasses you wear every day, it just keeps things working."},"relearn":"Daily HIV medicine keeps people well; taking it for life is how it works.","persona":"Asha","source":"HIV basics / treatment"},
  {"id":"df-1082","cat":"hiv-basics","type":"strike-rewrite","hook":"\"A baby born to a parent with HIV is sure to have it too.\"","myth":{"un":"A parent with HIV always passes it to the baby.","re":"With the right medicine in pregnancy, most babies are born HIV-free.","why":"Care during pregnancy protects the baby. It isn't automatic."},"relearn":"With proper care, most babies of parents with HIV are born HIV-free.","persona":"Asha","source":"HIV basics / transmission"},
  {"id":"df-1083","cat":"hiv-basics","type":"strike-rewrite","hook":"\"Kids with HIV should study from home, away from everyone.\"","myth":{"un":"A child with HIV must be kept out of normal school.","re":"Children with HIV go to school and learn beside everyone, safely.","why":"Nothing about a normal school day can pass HIV to a classmate."},"relearn":"Children with HIV belong in school with everyone. It's completely safe.","persona":"Asha","source":"HIV basics / inclusion"},
  {"id":"df-1084","cat":"hiv-basics","type":"strike-rewrite","hook":"\"A person with HIV looks weak and thin, so you'd know.\"","myth":{"un":"You can tell someone has HIV by how thin or weak they look.","re":"People with HIV look just like anyone; you cannot tell by looking.","why":"On treatment they're as healthy-looking as their friends."},"relearn":"You can't tell who has HIV by looking. They look like anyone else.","persona":"Aarav","source":"HIV basics"},
  {"id":"df-1085","cat":"hiv-basics","type":"strike-rewrite","hook":"\"HIV and AIDS are the same word for the same thing.\"","myth":{"un":"HIV always means a person already has AIDS.","re":"HIV is the virus; with treatment it's kept in check and stays controlled.","why":"Medicine stops the virus from harming the body over time."},"relearn":"HIV is a virus that medicine controls; treatment keeps people healthy.","persona":"Asha","source":"HIV basics"},
  {"id":"df-1086","cat":"hiv-basics","type":"strike-rewrite","hook":"\"Only grown-ups can have HIV, never children.\"","myth":{"un":"Children can never have HIV.","re":"Anyone can have HIV, including children; it says nothing about them.","why":"A virus doesn't check someone's age before infecting."},"relearn":"Anyone, including children, can have HIV. It says nothing about them.","persona":"Asha","source":"HIV basics / anti-stigma"},
  {"id":"df-1087","cat":"hiv-basics","type":"strike-rewrite","hook":"\"If a classmate has HIV, the whole class is in danger.\"","myth":{"un":"One child with HIV puts a whole classroom at risk.","re":"Sharing a classroom can't pass HIV; everyday school contact is safe.","why":"HIV doesn't travel through air, desks, or being near someone."},"relearn":"A classmate with HIV puts no one at risk. School contact is safe.","persona":"Asha","source":"HIV basics / inclusion"},
  {"id":"df-1088","cat":"hiv-basics","type":"strike-rewrite","hook":"\"People get HIV because they did something shameful.\"","myth":{"un":"HIV is proof a person did something shameful.","re":"HIV is just an infection; it is never proof of anything about character.","why":"An illness is something that happens, not a verdict on a person."},"relearn":"HIV is an infection, never proof of wrongdoing or a 'bad' person.","persona":"Asha","source":"HIV basics / anti-stigma"},
  {"id":"df-1089","cat":"hiv-basics","type":"strike-rewrite","hook":"\"Someone with HIV will pass it just by touching your things.\"","myth":{"un":"Touching the things of someone with HIV gives you HIV.","re":"HIV does not live on objects; touching their things is completely safe.","why":"HIV needs specific routes, never a pen, book, or shared bench."},"relearn":"HIV isn't on objects; touching someone's things is completely safe.","persona":"Asha","source":"HIV basics / transmission"},
  {"id":"df-1090","cat":"hiv-basics","type":"strike-rewrite","hook":"\"A person with HIV must keep all their own plates and never share.\"","myth":{"un":"Someone with HIV needs separate plates so no one catches it.","re":"Sharing plates and cups never spreads HIV; separate plates aren't needed.","why":"HIV doesn't spread through food, plates, or cups at all."},"relearn":"Sharing plates never spreads HIV. Separate plates aren't needed.","persona":"Asha","source":"HIV basics / transmission"},
  {"id":"df-1091","cat":"hiv-basics","type":"strike-rewrite","hook":"\"HIV is so new there's nothing doctors really understand about it.\"","myth":{"un":"Doctors barely understand HIV, so it's hopeless.","re":"Doctors understand HIV well; medicine controls it and people stay healthy.","why":"HIV care has improved so much that it's a manageable condition."},"relearn":"Doctors understand HIV well; medicine controls it and people stay healthy.","persona":"Asha","source":"HIV basics / treatment"},
  {"id":"df-1092","cat":"hiv-basics","type":"strike-rewrite","hook":"\"My cousin has HIV, so something must be wrong with our family.\"","myth":{"un":"HIV in the family means the family is bad or cursed.","re":"HIV is an infection, not a family flaw or a curse on anyone.","why":"A virus has no opinion about a family's worth."},"relearn":"HIV is an infection, never a flaw or curse on a person or family.","persona":"Aarav","source":"HIV basics / anti-stigma"},
  {"id":"df-1093","cat":"hiv-basics","type":"strike-rewrite","hook":"\"If you befriend someone with HIV, you'll get it eventually.\"","myth":{"un":"Being friends with someone who has HIV means you'll catch it.","re":"Friendship can't pass HIV; sitting, playing and talking are all safe.","why":"Everyday closeness with a friend never carries HIV."},"relearn":"Friendship can't pass HIV. Sitting, playing and talking are all safe.","persona":"Diya","source":"HIV basics / inclusion"},
  {"id":"df-1094","cat":"hiv-basics","type":"strike-rewrite","hook":"\"People with HIV have to take their medicine in secret or be ashamed.\"","myth":{"un":"Taking HIV medicine is something to hide in shame.","re":"Taking HIV medicine is just self-care, like any daily medicine: no shame.","why":"Looking after your health is never something to be ashamed of."},"relearn":"HIV medicine is ordinary self-care, like any daily medicine: no shame.","persona":"Asha","source":"HIV basics / dignity"},
  {"id":"df-1095","cat":"hiv-basics","type":"strike-rewrite","hook":"\"If you sit on the same bench as someone with HIV, you risk it.\"","myth":{"un":"Sharing a bench with someone who has HIV is risky.","re":"Sharing a bench or seat is completely safe; HIV isn't on surfaces.","why":"HIV needs specific routes, never a seat you share."},"relearn":"Sharing a bench is completely safe. HIV isn't on seats or surfaces.","persona":"Asha","source":"HIV basics / transmission"},
  {"id":"df-1096","cat":"hiv-basics","type":"strike-rewrite","hook":"\"A person with HIV can never play sport or run around.\"","myth":{"un":"Having HIV means you can't play sport or be active.","re":"On treatment, people with HIV play sport and run around like anyone.","why":"Staying active is part of a healthy life with HIV."},"relearn":"On treatment, people with HIV play sport and stay active like anyone.","persona":"Diya","source":"HIV basics / treatment"},
  {"id":"df-1097","cat":"hiv-basics","type":"strike-rewrite","hook":"\"You catch HIV by drinking from the same water tap or bottle.\"","myth":{"un":"A shared tap or water bottle can give you HIV.","re":"HIV never spreads through water, taps, or sharing a bottle.","why":"HIV doesn't live in water or pass through drinking."},"relearn":"HIV never spreads through water, taps, or a shared bottle.","persona":"Asha","source":"HIV basics / transmission"},
  {"id":"df-1098","cat":"hiv-basics","type":"strike-rewrite","hook":"\"Once people know someone has HIV, it's fine to talk about it freely.\"","myth":{"un":"A person's HIV status is everyone's business once it's known.","re":"Someone's HIV status is private; kindness means support, not gossip.","why":"Health information belongs to the person, not the rumour mill."},"relearn":"Someone's HIV status is private. Support them, never gossip.","persona":"Asha","source":"HIV basics / dignity"},
  {"id":"df-1099","cat":"hiv-basics","type":"strike-rewrite","hook":"\"A scratch or graze from a friend with HIV will pass it on.\"","myth":{"un":"A small scratch from someone with HIV spreads it.","re":"Everyday scrapes don't spread HIV; playing together is safe.","why":"HIV isn't passed by ordinary cuts and play between friends."},"relearn":"Everyday scrapes don't spread HIV. Playing together is safe.","persona":"Asha","source":"HIV basics / transmission"},
  {"id":"df-1100","cat":"hiv-basics","type":"strike-rewrite","hook":"\"People with HIV should sit apart so the rest stay clean.\"","myth":{"un":"Keeping people with HIV apart keeps everyone else safe.","re":"Sitting together is completely safe; separating people only spreads fear.","why":"There's nothing about closeness that passes HIV."},"relearn":"Sitting together is safe; separating people only spreads fear, not safety.","persona":"Asha","source":"HIV basics / inclusion"},
  {"id":"df-1101","cat":"hiv-basics","type":"strike-rewrite","hook":"\"If a teacher has HIV, kids shouldn't be in that class.\"","myth":{"un":"A teacher with HIV is a danger to the class.","re":"A teacher with HIV teaches safely; classroom contact never spreads it.","why":"Teaching, talking and helping a class can't carry HIV."},"relearn":"A teacher with HIV teaches safely. Classroom contact never spreads it.","persona":"Asha","source":"HIV basics / inclusion"},
  {"id":"df-1102","cat":"hiv-basics","type":"strike-rewrite","hook":"\"HIV can be passed through tears or sweat if you're close enough.\"","myth":{"un":"Tears or sweat from someone with HIV can infect you.","re":"HIV is not passed through tears or sweat; being close is safe.","why":"These body fluids don't carry HIV in a way that infects."},"relearn":"HIV isn't passed through tears or sweat. Being close is safe.","persona":"Asha","source":"HIV basics / transmission"},
  {"id":"df-1103","cat":"hiv-basics","type":"sort","hook":"Sort: true or false about living with HIV?","items":[{"id":"a","text":"Medicine lets people with HIV live long, healthy lives"},{"id":"b","text":"You can tell who has HIV by looking"},{"id":"c","text":"Children with HIV can go to school"},{"id":"d","text":"HIV is a punishment for being bad"},{"id":"e","text":"Anyone can have HIV"},{"id":"f","text":"People with HIV are always sick"}],"bins":[{"id":"true","label":"True","valence":"pos"},{"id":"false","label":"False","valence":"neg"}],"key":{"a":"true","b":"false","c":"true","d":"false","e":"true","f":"false"},"relearn":"True: treatment works, anyone can have HIV, kids belong in school. The rest are myths.","persona":"Asha","source":"HIV basics"},
  {"id":"df-1104","cat":"hiv-basics","type":"sort","hook":"Sort: a way HIV can spread, or a way it cannot?","items":[{"id":"a","text":"Through blood, like shared needles"},{"id":"b","text":"From a parent to a baby"},{"id":"c","text":"From a hug or a handshake"},{"id":"d","text":"From sharing a meal"},{"id":"e","text":"From a mosquito bite"},{"id":"f","text":"From sitting together in class"}],"bins":[{"id":"can","label":"Can spread","valence":"neg"},{"id":"cannot","label":"Cannot spread","valence":"pos"}],"key":{"a":"can","b":"can","c":"cannot","d":"cannot","e":"cannot","f":"cannot"},"relearn":"HIV spreads only via blood or parent-to-baby, never hugs, food, mosquitoes or class.","persona":"Asha","source":"HIV basics / transmission"},
  {"id":"df-1105","cat":"hiv-basics","type":"sort","hook":"Sort: kind and true, or a hurtful myth?","items":[{"id":"a","text":"\"Come sit with us\" to a classmate with HIV"},{"id":"b","text":"\"A person is more than their illness\""},{"id":"c","text":"\"Keep away, you might catch it\""},{"id":"d","text":"\"It's their own fault\""},{"id":"e","text":"\"You can play with us, it's safe\""},{"id":"f","text":"\"Don't tell anyone, it's shameful\""}],"bins":[{"id":"kind","label":"Kind & true","valence":"pos"},{"id":"myth","label":"Hurtful myth","valence":"neg"}],"key":{"a":"kind","b":"kind","c":"myth","d":"myth","e":"kind","f":"myth"},"relearn":"Including and reassuring is kind and true; fear, blame and shame are myths.","persona":"Diya","source":"HIV basics / kindness"},
  {"id":"df-1106","cat":"hiv-basics","type":"sort","hook":"Sort: a real HIV fact, or fear talking?","items":[{"id":"a","text":"Daily medicine keeps HIV in check"},{"id":"b","text":"HIV says nothing about your character"},{"id":"c","text":"HIV floats in the air like a cold"},{"id":"d","text":"You catch HIV from a toilet seat"},{"id":"e","text":"People with HIV can marry and have kids"},{"id":"f","text":"You can spot HIV across a room"}],"bins":[{"id":"fact","label":"Real fact","valence":"pos"},{"id":"fear","label":"Fear talking","valence":"neg"}],"key":{"a":"fact","b":"fact","c":"fear","d":"fear","e":"fact","f":"fear"},"relearn":"Facts: treatment works, no 'look', full lives. Air, toilets and 'spotting' are fear.","persona":"Asha","source":"HIV basics"},
  {"id":"df-1107","cat":"hiv-basics","type":"sort","hook":"Sort: safe everyday contact, or actually risky?","items":[{"id":"a","text":"Hugging a friend with HIV"},{"id":"b","text":"Sharing a tiffin with them"},{"id":"c","text":"Sharing a used needle"},{"id":"d","text":"Holding hands"},{"id":"e","text":"Playing cricket together"},{"id":"f","text":"Doing homework side by side"}],"bins":[{"id":"safe","label":"Safe","valence":"pos"},{"id":"risky","label":"Risky","valence":"neg"}],"key":{"a":"safe","b":"safe","c":"risky","d":"safe","e":"safe","f":"safe"},"relearn":"Hugs, food, play and study are all safe; only a shared needle carries blood risk.","persona":"Asha","source":"HIV basics / transmission"},
  {"id":"df-1108","cat":"hiv-basics","type":"sort","hook":"Sort: who can have HIV?","items":[{"id":"a","text":"A neighbour aunty"},{"id":"b","text":"A schoolboy"},{"id":"c","text":"A famous cricketer"},{"id":"d","text":"A new baby"},{"id":"e","text":"A 'bad' person only"},{"id":"f","text":"A 'dirty' person only"}],"bins":[{"id":"yes","label":"Anyone can","valence":"pos"},{"id":"no","label":"Myth: only 'them'","valence":"neg"}],"key":{"a":"yes","b":"yes","c":"yes","d":"yes","e":"no","f":"no"},"relearn":"Anyone can have HIV; it never marks someone as 'bad' or 'dirty'.","persona":"Asha","source":"HIV basics / anti-stigma"},
  {"id":"df-1109","cat":"hiv-basics","type":"sort","hook":"Sort: a helpful response to HIV, or a harmful one?","items":[{"id":"a","text":"Asking a health worker for facts"},{"id":"b","text":"Including a classmate as normal"},{"id":"c","text":"Spreading a scary rumour"},{"id":"d","text":"Whispering about who has it"},{"id":"e","text":"Reminding a friend they belong"},{"id":"f","text":"Telling people to stay away"}],"bins":[{"id":"help","label":"Helpful","valence":"pos"},{"id":"harm","label":"Harmful","valence":"neg"}],"key":{"a":"help","b":"help","c":"harm","d":"harm","e":"help","f":"harm"},"relearn":"Facts, inclusion and reassurance help; rumours, gossip and exclusion harm.","persona":"Asha","source":"HIV basics / kindness"},
  {"id":"df-1110","cat":"hiv-basics","type":"sort","hook":"Sort: something HIV medicine does, or doesn't do?","items":[{"id":"a","text":"Keeps the virus low so people stay well"},{"id":"b","text":"Lets people live a normal life"},{"id":"c","text":"Helps a parent protect their baby"},{"id":"d","text":"Changes who a person is"},{"id":"e","text":"Makes HIV catch from a hug"},{"id":"f","text":"Is something to feel ashamed of"}],"bins":[{"id":"does","label":"It does","valence":"pos"},{"id":"doesnt","label":"It doesn't","valence":"neg"}],"key":{"a":"does","b":"does","c":"does","d":"doesnt","e":"doesnt","f":"doesnt"},"relearn":"Medicine keeps people well and protects babies; it never changes who they are.","persona":"Asha","source":"HIV basics / treatment"},
  {"id":"df-1111","cat":"hiv-basics","type":"sort","hook":"Sort: private and personal, or okay to share around?","items":[{"id":"a","text":"Whether a classmate has HIV"},{"id":"b","text":"Someone's health details"},{"id":"c","text":"Today's school timetable"},{"id":"d","text":"The score in your match"},{"id":"e","text":"A friend's medicine times"},{"id":"f","text":"Tomorrow's lunch menu"}],"bins":[{"id":"private","label":"Private","valence":"uhoh"},{"id":"open","label":"Okay to share","valence":"neutral"}],"key":{"a":"private","b":"private","c":"open","d":"open","e":"private","f":"open"},"relearn":"Health details, like HIV status and medicine, are private; ordinary news isn't.","persona":"Asha","source":"HIV basics / dignity"},
  {"id":"df-1112","cat":"hiv-basics","type":"branch","hook":"A new classmate has HIV and some kids are unsure about sitting near them.","options":[{"text":"Sit beside them and say it's good to have them here","consequence":"They feel welcome and the fear fades.","outcome":"kind","best":true},{"text":"Move to a far seat just in case","consequence":"Sitting near is safe; moving away only spreads fear."}],"debrief":"Sitting together is completely safe. Your welcome is what matters.","relearn":"It's safe to sit with a classmate who has HIV; make them feel welcome.","persona":"Diya","source":"HIV basics / inclusion"},
  {"id":"df-1113","cat":"hiv-basics","type":"branch","hook":"Your little brother asks if your friend with HIV is going to die.","options":[{"text":"\"No, medicine keeps them well, they live a normal life\"","consequence":"He learns the calm truth, not fear.","outcome":"calm","best":true},{"text":"\"Maybe, better stay away from them\"","consequence":"That's a myth; medicine means a long, normal life."}],"debrief":"Treatment keeps people with HIV healthy for life. Share that, not fear.","relearn":"With medicine, people with HIV live long, healthy lives; say so calmly.","persona":"Asha","source":"HIV basics / treatment"},
  {"id":"df-1114","cat":"hiv-basics","type":"branch","hook":"A relative says \"don't eat from that family's home, they have HIV.\"","options":[{"text":"Gently say sharing food can't pass HIV","consequence":"A calm fact eases an elder's fear.","outcome":"respectful","best":true},{"text":"Agree and avoid their home","consequence":"Food never spreads HIV; avoiding only feeds stigma."}],"debrief":"Food, plates and cups never spread HIV. A calm fact can ease an elder's worry.","relearn":"Sharing food never spreads HIV; you can gently correct an elder's fear.","persona":"Rohit","source":"HIV basics / transmission"},
  {"id":"df-1115","cat":"hiv-basics","type":"branch","hook":"Kids are whispering that a girl in class \"has that disease.\"","options":[{"text":"Don't join in; go talk and play with her as normal","consequence":"You break the whisper and she's not alone.","outcome":"upstander","best":true},{"text":"Listen and pass it on","consequence":"Whispering hurts; her status is private, not gossip."}],"debrief":"Don't join the whispering: include her, and keep her health private.","relearn":"Don't spread whispers about HIV; include the person and protect their privacy.","persona":"Diya","source":"HIV basics / dignity"},
  {"id":"df-1116","cat":"hiv-basics","type":"branch","hook":"You're not sure if you can share a water bottle with a friend who has HIV.","options":[{"text":"Share it: water and bottles never carry HIV","consequence":"You stay close friends, safely.","outcome":"informed","best":true},{"text":"Refuse and act strange about it","consequence":"Sharing water is safe; acting strange only hurts."}],"debrief":"HIV never spreads through water or a shared bottle. Share freely.","relearn":"Sharing a water bottle can't pass HIV; it's completely safe.","persona":"any","source":"HIV basics / transmission"},
  {"id":"df-1117","cat":"hiv-basics","type":"branch","hook":"A friend with HIV looks sad because others moved their desk away.","options":[{"text":"Move your desk next to theirs and say you've got them","consequence":"They feel they belong again.","outcome":"kind","best":true},{"text":"Pretend you didn't notice","consequence":"A small move toward them undoes a lot of hurt."}],"debrief":"A friend pushed out by fear needs someone to move closer, not away.","relearn":"When fear pushes someone out, move closer; sitting together is safe.","persona":"Diya","source":"HIV basics / inclusion"},
  {"id":"df-1118","cat":"hiv-basics","type":"branch","hook":"Someone forwards a message saying you can catch HIV from sweat in PT class.","options":[{"text":"Don't forward it; check the facts with a health worker","consequence":"You stop a false scare spreading.","outcome":"wise","best":true},{"text":"Forward it to warn everyone","consequence":"HIV isn't in sweat; forwarding spreads a false scare."}],"debrief":"Sweat doesn't spread HIV. Check before forwarding, don't spread a scare.","relearn":"HIV isn't spread through sweat; check facts before forwarding a message.","persona":"Aarav","source":"HIV basics / help-seeking"},
  {"id":"df-1119","cat":"hiv-basics","type":"branch","hook":"Your friend with HIV worries you'll tell the class about their medicine.","options":[{"text":"Promise to keep it private: it's their news to share","consequence":"They trust you and feel safe.","outcome":"trusted","best":true},{"text":"Tell a few friends anyway","consequence":"Their health is private; sharing it breaks trust."}],"debrief":"Someone's HIV status is theirs alone. Keeping it private is real friendship.","relearn":"A friend's HIV status is private; keep it unless they choose to share.","persona":"Diya","source":"HIV basics / dignity"},
  {"id":"df-1120","cat":"hiv-basics","type":"branch","hook":"A younger cousin is scared to hug grandma's friend who has HIV.","options":[{"text":"Show them a hug is safe and hug first yourself","consequence":"They copy you and the fear melts.","outcome":"reassuring","best":true},{"text":"Tell them to keep their distance","consequence":"Hugs never spread HIV; distance only teaches fear."}],"debrief":"A hug never spreads HIV. Show a scared child that closeness is safe.","relearn":"Hugging someone with HIV is completely safe; model it for a scared child.","persona":"any","source":"HIV basics / inclusion"},
  {"id":"df-1121","cat":"hiv-basics","type":"spot","hook":"A health poster has facts and myths. Spot the TWO myths.","scene":[{"id":"a","text":"\"People with HIV live full, healthy lives\"","trick":false},{"id":"b","text":"\"You can catch HIV from a hug\"","trick":true},{"id":"c","text":"\"Children with HIV can go to school\"","trick":false},{"id":"d","text":"\"Only bad people get HIV\"","trick":true},{"id":"e","text":"\"Daily medicine keeps the virus in check\"","trick":false}],"why":"Hugs never spread HIV, and anyone can have it. Those two lines are myths.","relearn":"Spotting HIV myths: hugs don't spread it, and anyone can have it.","persona":"Asha","source":"HIV basics"},
  {"id":"df-1122","cat":"hiv-basics","type":"spot","hook":"A chat about HIV. Spot the TWO things that are NOT true.","scene":[{"id":"a","text":"\"HIV is a virus anyone can have\"","trick":false},{"id":"b","text":"\"You can tell who has it by looking\"","trick":true},{"id":"c","text":"\"Treatment means a long, normal life\"","trick":false},{"id":"d","text":"\"Sharing food gives you HIV\"","trick":true},{"id":"e","text":"\"HIV is never a punishment\"","trick":false}],"why":"You can't tell by looking, and sharing food never spreads HIV. Both are false.","relearn":"You can't spot HIV by looking, and food never spreads it.","persona":"Asha","source":"HIV basics"},
  {"id":"df-1123","cat":"hiv-basics","type":"spot","hook":"Ways germs travel. Spot the TWO that do NOT spread HIV.","scene":[{"id":"a","text":"Sharing a needle","trick":false},{"id":"b","text":"A mosquito bite","trick":true},{"id":"c","text":"Parent to baby","trick":false},{"id":"d","text":"A toilet seat","trick":true},{"id":"e","text":"Blood-to-blood contact","trick":false}],"why":"Mosquitoes and toilet seats never carry HIV; only blood and parent-to-baby do.","relearn":"Mosquitoes and toilet seats don't spread HIV, only blood and parent-to-baby.","persona":"Asha","source":"HIV basics / transmission"},
  {"id":"df-1124","cat":"hiv-basics","type":"spot","hook":"Things kids said about a classmate with HIV. Spot the TWO unkind ones.","scene":[{"id":"a","text":"\"Want to join our game?\"","trick":false},{"id":"b","text":"\"Don't touch them, you'll catch it\"","trick":true},{"id":"c","text":"\"Sit with us at lunch\"","trick":false},{"id":"d","text":"\"Their family must be cursed\"","trick":true},{"id":"e","text":"\"You're good at maths, help me?\"","trick":false}],"why":"Fear of catching it and 'cursed' are unkind myths; the rest simply include.","relearn":"Including a classmate is kind; 'you'll catch it' and 'cursed' are unkind myths.","persona":"Diya","source":"HIV basics / kindness"},
  {"id":"df-1125","cat":"hiv-basics","type":"spot","hook":"A worried elder's beliefs. Spot the TWO that are myths.","scene":[{"id":"a","text":"\"Medicine keeps people with HIV well\"","trick":false},{"id":"b","text":"\"Don't share a bench with them\"","trick":true},{"id":"c","text":"\"They can still work and live normally\"","trick":false},{"id":"d","text":"\"Keep their plates separate\"","trick":true},{"id":"e","text":"\"HIV is not a punishment\"","trick":false}],"why":"Sharing a bench and plates is completely safe; both worries are myths.","relearn":"Benches and plates never spread HIV. Calm facts can ease an elder's fear.","persona":"Rohit","source":"HIV basics / transmission"},
  {"id":"df-1126","cat":"hiv-basics","type":"spot","hook":"Reasons given to exclude a child with HIV. Spot the TWO false reasons.","scene":[{"id":"a","text":"\"School contact can't spread HIV\"","trick":false},{"id":"b","text":"\"They might infect us in class\"","trick":true},{"id":"c","text":"\"They have the same right to learn\"","trick":false},{"id":"d","text":"\"Their cough will give it to us\"","trick":true},{"id":"e","text":"\"They can play sport with us\"","trick":false}],"why":"HIV isn't passed in class or by coughs; those reasons to exclude are false.","relearn":"Children with HIV can't infect a class or cough it onto anyone. They belong.","persona":"Asha","source":"HIV basics / inclusion"},
  {"id":"df-1127","cat":"hiv-basics","type":"spot","hook":"A friend's questions about HIV. Spot the TWO based on a myth.","scene":[{"id":"a","text":"\"Can they live a long life?\"","trick":false},{"id":"b","text":"\"Will I catch it from their tears?\"","trick":true},{"id":"c","text":"\"Is it safe to be friends?\"","trick":false},{"id":"d","text":"\"Did they get it for being bad?\"","trick":true},{"id":"e","text":"\"Can they go to school with me?\"","trick":false}],"why":"Tears don't spread HIV, and it's never about being 'bad'. Both rest on myths.","relearn":"HIV isn't in tears and is never about being 'bad'; the other questions are fine.","persona":"Aarav","source":"HIV basics"},
  {"id":"df-1128","cat":"hiv-basics","type":"reflect","hook":"Lensy: a friend with HIV is still the same friend. True for you?","prompt":"What do you think?","options":["Yes","Same friend","Of course"],"affirm":"An illness never changes who someone is to you.","relearn":"A person with HIV is the same whole person they always were.","persona":"any","source":"HIV basics / dignity"},
  {"id":"df-1129","cat":"hiv-basics","type":"reflect","hook":"Lensy: learning the facts makes HIV feel less scary. Does it for you?","prompt":"How does it feel?","options":["Much less scary","Calmer now","Facts help"],"affirm":"Facts replace fear with calm understanding.","relearn":"Knowing the facts about HIV turns fear into calm understanding.","persona":"any","source":"HIV basics"},
  {"id":"df-1130","cat":"hiv-basics","type":"reflect","hook":"Lensy: everyone deserves to be included, illness or not. Agree?","prompt":"What do you think?","options":["Yes","Everyone belongs","Always"],"affirm":"Belonging isn't something an illness can take away.","relearn":"Everyone belongs and deserves inclusion, whatever their health.","persona":"Diya","source":"HIV basics / inclusion"},
  {"id":"df-1131","cat":"hiv-basics","type":"reflect","hook":"Lensy: someone's health is their own private business. Makes sense?","prompt":"What do you think?","options":["Yes","It's private","Their choice"],"affirm":"Health details belong to the person. Kindness keeps them private.","relearn":"A person's health status is private and deserves respect.","persona":"any","source":"HIV basics / dignity"},
  {"id":"df-1132","cat":"hiv-basics","type":"reflect","hook":"Lensy: a hug is a safe, kind thing to give a friend with HIV. Feel right?","prompt":"What do you think?","options":["Yes","Hugs are safe","Of course"],"affirm":"A hug is always safe, and sometimes exactly what a friend needs.","relearn":"Hugging a friend with HIV is completely safe and kind.","persona":"any","source":"HIV basics / inclusion"},
  {"id":"df-1133","cat":"hiv-basics","type":"reflect","hook":"Lensy: getting sick is something that happens, not a person's fault. Agree?","prompt":"What do you think?","options":["Yes","Never their fault","It just happens"],"affirm":"Illness is never a verdict on a person.","relearn":"HIV and other illness are never a person's fault.","persona":"Asha","source":"HIV basics / anti-stigma"},
  {"id":"df-1134","cat":"hiv-basics","type":"reflect","hook":"Lensy: you can be the one who makes a left-out classmate feel welcome. Could you?","prompt":"What do you think?","options":["Yes","I could","I'd try"],"affirm":"One kind person changing the room is how stigma ends.","relearn":"You can be the one who includes a left-out classmate.","persona":"Diya","source":"HIV basics / kindness"},
  {"id":"df-1135","cat":"hiv-basics","type":"reflect","hook":"Lensy: a person living with HIV is much more than their virus. True?","prompt":"What do you think?","options":["Yes","Much more","A whole person"],"affirm":"People are always more than any illness they carry.","relearn":"A person living with HIV is a whole person, not their virus.","persona":"any","source":"HIV basics / dignity"},
  {"id":"df-1136","cat":"hiv-basics","type":"reflect","hook":"Lensy: facts you trust come from a health worker, not a rumour. Agree?","prompt":"What do you think?","options":["Yes","Ask a health worker","Not rumours"],"affirm":"Trusted facts calm fear; rumours only feed it.","relearn":"Trust HIV facts from a health worker over any rumour.","persona":"Asha","source":"HIV basics / help-seeking"},
  {"id":"df-1137","cat":"hiv-basics","type":"role-play","setup":"A classmate with HIV is sitting alone at lunch.","yourLine":[{"text":"\"Come sit with us. We saved you a spot.\"","best":true},{"text":"(say nothing and look away)"}],"relearn":"A warm \"come sit with us\" is all it takes to include someone.","persona":"Diya","source":"HIV basics / inclusion","hook":"What do you say to a classmate sitting alone?"},
  {"id":"df-1138","cat":"hiv-basics","type":"role-play","setup":"Your aunt says she's scared to share tea with a neighbour who has HIV.","yourLine":[{"text":"\"Tea and cups never spread HIV, auntie. It's safe.\"","best":true},{"text":"\"Maybe just use a different cup then.\""}],"relearn":"A calm fact about cups can ease an elder's fear.","persona":"Rohit","source":"HIV basics / transmission","hook":"What do you tell a worried elder about sharing tea?"},
  {"id":"df-1139","cat":"hiv-basics","type":"role-play","setup":"A friend asks if they'll catch HIV by being on your team.","yourLine":[{"text":"\"No way. Playing together is completely safe.\"","best":true},{"text":"\"Hmm, I'm not totally sure, maybe sit out.\""}],"relearn":"Playing on a team together never spreads HIV. Say it plainly.","persona":"any","source":"HIV basics / inclusion","hook":"What do you say when a friend fears catching HIV from play?"},
  {"id":"df-1140","cat":"hiv-basics","type":"role-play","setup":"Kids start whispering that a boy in class \"has HIV.\"","yourLine":[{"text":"\"That's his private business. Let's just go play.\"","best":true},{"text":"\"Really? Tell me what you heard.\""}],"relearn":"Shutting down a whisper protects a classmate's privacy.","persona":"Diya","source":"HIV basics / dignity","hook":"What do you say when kids whisper about a classmate's HIV?"},
  {"id":"df-1141","cat":"hiv-basics","type":"role-play","setup":"Your friend with HIV is nervous about starting at a new school.","yourLine":[{"text":"\"You'll be great. It's just like any school day for you.\"","best":true},{"text":"\"Maybe don't tell anyone and keep to yourself.\""}],"relearn":"A friend with HIV belongs at school like anyone. Reassure them.","persona":"Diya","source":"HIV basics / inclusion","hook":"What do you say to reassure a nervous friend with HIV?"},
  {"id":"df-1142","cat":"hiv-basics","type":"role-play","setup":"A younger kid asks you, \"is HIV a punishment for being bad?\"","yourLine":[{"text":"\"No, it's just a virus. It's never a punishment for anything.\"","best":true},{"text":"\"I think only bad people get it, so be careful.\""}],"relearn":"HIV is an infection, never a punishment. Tell a younger kid the truth.","persona":"Asha","source":"HIV basics / anti-stigma","hook":"How do you answer a kid who thinks HIV is a punishment?"},
  {"id":"df-1143","cat":"hiv-basics","type":"role-play","setup":"Someone says your friend with HIV \"won't live long.\"","yourLine":[{"text":"\"With medicine they'll live a long, normal life.\"","best":true},{"text":"(stay quiet, even though it isn't true)"}],"relearn":"Treatment means a long, normal life. Correct the myth kindly.","persona":"Asha","source":"HIV basics / treatment","hook":"What do you say when someone repeats a myth about HIV and lifespan?"},
  {"id":"df-1144","cat":"hiv-basics","type":"role-play","setup":"Your cousin won't share crayons with a child who has HIV.","yourLine":[{"text":"\"Crayons can't pass HIV. Here, let's all share.\"","best":true},{"text":"\"Okay, you keep your own crayons then.\""}],"relearn":"Objects like crayons never spread HIV. Model sharing for a younger child.","persona":"any","source":"HIV basics / transmission","hook":"What do you say to a cousin who won't share with a child who has HIV?"},
  {"id":"df-1145","cat":"hiv-basics","type":"match","hook":"Match each HIV fact to what it means.","pairs":[{"left":"Daily medicine","right":"keeps the virus in check"},{"left":"Anyone can have HIV","right":"it says nothing about character"},{"left":"You can't tell by looking","right":"people with HIV look like anyone"},{"left":"Kids with HIV","right":"can go to school safely"},{"left":"A person with HIV","right":"is a whole person, not their virus"}],"relearn":"The facts: treatment works, anyone can have it, no 'look', kids belong, dignity.","persona":"Asha","source":"HIV basics"},
  {"id":"df-1146","cat":"hiv-basics","type":"match","hook":"Match each everyday contact to whether HIV can pass.","pairs":[{"left":"A hug","right":"completely safe"},{"left":"Sharing food","right":"safe: food never carries it"},{"left":"A mosquito bite","right":"safe: insects don't spread HIV"},{"left":"A shared needle","right":"a real blood route to avoid"},{"left":"Parent to baby","right":"a route that care can prevent"}],"relearn":"Hugs, food and mosquitoes are safe; needles and parent-to-baby are real routes.","persona":"Asha","source":"HIV basics / transmission"},
  {"id":"df-1147","cat":"hiv-basics","type":"match","hook":"Match each kind action to who it helps.","pairs":[{"left":"\"Come sit with us\"","right":"a classmate eating alone"},{"left":"Keeping a status private","right":"a friend who trusted you"},{"left":"Sharing a calm fact","right":"a worried elder"},{"left":"Not joining a whisper","right":"someone being gossiped about"},{"left":"Hugging first","right":"a scared younger child"}],"relearn":"Each kindness fits a person: include, protect, reassure, defend, model.","persona":"Diya","source":"HIV basics / kindness"},
  {"id":"df-1148","cat":"hiv-basics","type":"match","hook":"Match each myth to the fact that beats it.","pairs":[{"left":"\"Catch it from a hug\"","right":"hugs never spread HIV"},{"left":"\"Always sick\"","right":"treatment means a normal life"},{"left":"\"Tell by looking\"","right":"there's no HIV 'look'"},{"left":"\"A punishment\"","right":"it's just an infection"},{"left":"\"Only bad people\"","right":"anyone can have it"}],"relearn":"Every HIV myth has a calm fact that beats it.","persona":"Asha","source":"HIV basics"},
  {"id":"df-1149","cat":"hiv-basics","type":"match","hook":"Match each question to the person who can answer it well.","pairs":[{"left":"\"How does treatment work?\"","right":"a health worker"},{"left":"\"Is everyday contact safe?\"","right":"a trusted grown-up"},{"left":"\"What does my friend need?\"","right":"your friend themselves"},{"left":"\"Is this rumour true?\"","right":"a doctor or nurse"},{"left":"\"How can I include them?\"","right":"a kind classmate"}],"relearn":"Trusted people, not rumours, answer HIV questions well.","persona":"Asha","source":"HIV basics / help-seeking"},
  {"id":"df-1150","cat":"hiv-basics","type":"match","hook":"Match each part of a healthy life to a person with HIV doing it.","pairs":[{"left":"Going to school","right":"learning beside everyone"},{"left":"Playing sport","right":"running around like anyone"},{"left":"Taking medicine","right":"ordinary daily self-care"},{"left":"Making friends","right":"sitting and laughing together"},{"left":"Growing up","right":"a long, normal future"}],"relearn":"With treatment, people with HIV do everything anyone else does.","persona":"Asha","source":"HIV basics / treatment"},
  {"id":"df-1151","cat":"hiv-basics","type":"match","hook":"Match each worry to the reassuring truth.","pairs":[{"left":"\"Will I catch it in class?\"","right":"school contact is safe"},{"left":"\"From their water bottle?\"","right":"water never carries HIV"},{"left":"\"From their tears?\"","right":"tears don't spread it"},{"left":"\"By being friends?\"","right":"friendship is completely safe"},{"left":"\"From a toilet seat?\"","right":"seats never pass HIV"}],"relearn":"Class, water, tears, friendship and seats are all completely safe.","persona":"Asha","source":"HIV basics / transmission"},
  {"id":"df-1152","cat":"hiv-basics","type":"match","hook":"Match each word to whether it's kind or hurtful about HIV.","pairs":[{"left":"\"You belong here\"","right":"kind and true"},{"left":"\"Stay away from us\"","right":"a hurtful myth"},{"left":"\"Let's play together\"","right":"kind and safe"},{"left":"\"It's your own fault\"","right":"a hurtful untruth"},{"left":"\"Your secret's safe\"","right":"kind and respectful"}],"relearn":"Welcoming words are kind and true; blame and exclusion are hurtful myths.","persona":"Diya","source":"HIV basics / kindness"},
  {"id":"df-1170","cat":"how-germs-spread","type":"sort","hook":"Sort: a real germ route, or a feeling?","items":[{"id":"a","text":"Shaking unwashed hands then eating"},{"id":"b","text":"Feeling shy"},{"id":"c","text":"A sneeze landing on your snacks"},{"id":"d","text":"Being scared of the dark"},{"id":"e","text":"Sharing a half-eaten samosa while sick"},{"id":"f","text":"Missing your friend"}],"bins":[{"id":"route","label":"A real germ route","valence":"neg"},{"id":"feeling","label":"Just a feeling","valence":"pos"}],"key":{"a":"route","b":"feeling","c":"route","d":"feeling","e":"route","f":"feeling"},"relearn":"Germs travel by physical routes, never by feelings like shyness or worry.","persona":"any","source":"infection basics"},
  {"id":"df-1171","cat":"how-germs-spread","type":"sort","hook":"Sort: catches germs from the air, or from water?","items":[{"id":"a","text":"A sneezy cold in a packed bus"},{"id":"b","text":"Cholera from a dirty handpump"},{"id":"c","text":"A flu going round the class"},{"id":"d","text":"Typhoid from unclean drinking water"},{"id":"e","text":"A cough passing in a crowded room"},{"id":"f","text":"A stomach bug from street ice"}],"bins":[{"id":"air","label":"From the air","valence":"uhoh"},{"id":"water","label":"From water or food","valence":"uhoh"}],"key":{"a":"air","b":"water","c":"air","d":"water","e":"air","f":"water"},"relearn":"Airborne germs ride the air; water germs ride unclean water and food.","persona":"Asha","source":"infection basics"},
  {"id":"df-1172","cat":"how-germs-spread","type":"sort","hook":"Sort: spreads germs to others, or keeps them in?","items":[{"id":"a","text":"Coughing into your bare hand"},{"id":"b","text":"Coughing into your elbow"},{"id":"c","text":"Sneezing openly at the table"},{"id":"d","text":"Covering a sneeze with a cloth"},{"id":"e","text":"Wiping your nose then sharing a pen"},{"id":"f","text":"Washing hands after you sneeze"}],"bins":[{"id":"spreads","label":"Sends germs out","valence":"neg"},{"id":"blocks","label":"Keeps germs in","valence":"pos"}],"key":{"a":"spreads","b":"blocks","c":"spreads","d":"blocks","e":"spreads","f":"blocks"},"relearn":"Covering coughs and washing hands keep your germs from reaching others.","persona":"any","source":"infection basics"},
  {"id":"df-1173","cat":"how-germs-spread","type":"sort","hook":"Sort: a way HIV spreads, or a way it does NOT?","items":[{"id":"a","text":"A hug from a classmate"},{"id":"b","text":"A shared, unclean needle"},{"id":"c","text":"Sharing a tiffin box"},{"id":"d","text":"From a parent to their baby"},{"id":"e","text":"A mosquito bite"},{"id":"f","text":"Sitting on the same bench"}],"bins":[{"id":"does","label":"HIV can spread this way","valence":"neg"},{"id":"not","label":"HIV does NOT spread this way","valence":"pos"}],"key":{"a":"not","b":"does","c":"not","d":"does","e":"not","f":"not"},"relearn":"HIV spreads only by blood like shared needles, or parent to baby, never by hugs, food or mosquitoes.","persona":"Asha","source":"HIV basics / CDC-NIH"},
  {"id":"df-1174","cat":"how-germs-spread","type":"sort","hook":"Sort: blocks the germ route, or opens it?","items":[{"id":"a","text":"Boiling drinking water"},{"id":"b","text":"Drinking straight from a puddle"},{"id":"c","text":"Washing hands with soap"},{"id":"d","text":"Eating with dusty unwashed hands"},{"id":"e","text":"Covering food from flies"},{"id":"f","text":"Leaving food open near a drain"}],"bins":[{"id":"block","label":"Blocks the germ route","valence":"pos"},{"id":"open","label":"Opens the germ route","valence":"neg"}],"key":{"a":"block","b":"open","c":"block","d":"open","e":"block","f":"open"},"relearn":"Boiling water, soap and covering food block germ routes; the opposites open them.","persona":"any","source":"infection basics / prevention"},
  {"id":"df-1175","cat":"how-germs-spread","type":"sort","hook":"Sort: a fact about catching illness, or a myth?","items":[{"id":"a","text":"Anyone can catch a common germ"},{"id":"b","text":"Only poor people fall ill"},{"id":"c","text":"Washing hands cuts the spread"},{"id":"d","text":"Illness means you are 'bad'"},{"id":"e","text":"Germs spread by routes we can prevent"},{"id":"f","text":"Getting sick is a punishment"}],"bins":[{"id":"fact","label":"True fact","valence":"pos"},{"id":"myth","label":"Myth","valence":"neg"}],"key":{"a":"fact","b":"myth","c":"fact","d":"myth","e":"fact","f":"myth"},"relearn":"Anyone can catch a germ; illness is never about being poor, bad, or punished.","persona":"any","source":"infection basics / anti-stigma"},
  {"id":"df-1176","cat":"how-germs-spread","type":"sort","hook":"Sort: safe contact, or a real germ risk?","items":[{"id":"a","text":"Holding a friend's hand"},{"id":"b","text":"Sharing a water bottle while ill"},{"id":"c","text":"Playing kabaddi together"},{"id":"d","text":"Sneezing on a shared towel"},{"id":"e","text":"Sitting next to someone on the bus"},{"id":"f","text":"Eating off the same plate when sick"}],"bins":[{"id":"safe","label":"Safe contact","valence":"pos"},{"id":"risk","label":"A real germ risk","valence":"neg"}],"key":{"a":"safe","b":"risk","c":"safe","d":"risk","e":"safe","f":"risk"},"relearn":"Hands, play and sitting close are safe; sharing things while ill is the real risk.","persona":"any","source":"infection basics"},
  {"id":"df-1177","cat":"how-germs-spread","type":"sort","hook":"Sort: where germs can hide, or where they cannot.","items":[{"id":"a","text":"On unwashed hands"},{"id":"b","text":"On a kind thought"},{"id":"c","text":"In unclean drinking water"},{"id":"d","text":"On your favourite colour"},{"id":"e","text":"On a door handle many touch"},{"id":"f","text":"On a happy memory"}],"bins":[{"id":"can","label":"Germs can be here","valence":"neg"},{"id":"cannot","label":"Germs cannot be here","valence":"pos"}],"key":{"a":"can","b":"cannot","c":"can","d":"cannot","e":"can","f":"cannot"},"relearn":"Germs live on hands, water and surfaces, never on thoughts, colours or memories.","persona":"any","source":"infection basics"},
  {"id":"df-1178","cat":"how-germs-spread","type":"sort","hook":"Sort: which illness rides which route?","items":[{"id":"a","text":"A sneezy cold"},{"id":"b","text":"Diarrhoea from bad water"},{"id":"c","text":"A throat infection in class"},{"id":"d","text":"A tummy bug from street food"},{"id":"e","text":"Flu in a crowded fair"},{"id":"f","text":"Jaundice from unclean water"}],"bins":[{"id":"air","label":"Travels by air","valence":"uhoh"},{"id":"gut","label":"Travels by water/food","valence":"uhoh"}],"key":{"a":"air","b":"gut","c":"air","d":"gut","e":"air","f":"gut"},"relearn":"Coughs and sneezes ride the air; tummy bugs ride unclean water and food.","persona":"Asha","source":"infection basics"},
  {"id":"df-1179","cat":"how-germs-spread","type":"sort","hook":"Sort: makes germs spread more, or spread less?","items":[{"id":"a","text":"Coughing without covering your mouth"},{"id":"b","text":"Covering your mouth when you cough"},{"id":"c","text":"Sharing a glass when you are sick"},{"id":"d","text":"Using your own glass when sick"},{"id":"e","text":"Skipping handwash before lunch"},{"id":"f","text":"Washing hands before lunch"}],"bins":[{"id":"more","label":"Spreads more","valence":"neg"},{"id":"less","label":"Spreads less","valence":"pos"}],"key":{"a":"more","b":"less","c":"more","d":"less","e":"more","f":"less"},"relearn":"Covering coughs, own glass and clean hands all cut how far germs spread.","persona":"any","source":"infection basics / prevention"},
  {"id":"df-1180","cat":"how-germs-spread","type":"sort","hook":"Sort: a germ that needs close contact, or one that floats far?","items":[{"id":"a","text":"A cold sneeze across a room"},{"id":"b","text":"Germs from a shared spoon"},{"id":"c","text":"A cough drifting in close air"},{"id":"d","text":"Germs on a passed-around snack"},{"id":"e","text":"A sneeze in a packed classroom"},{"id":"f","text":"Germs from a dirty shared cup"}],"bins":[{"id":"air","label":"Floats in the air","valence":"uhoh"},{"id":"touch","label":"Needs touching shared things","valence":"uhoh"}],"key":{"a":"air","b":"touch","c":"air","d":"touch","e":"air","f":"touch"},"relearn":"Some germs float in the air; others ride shared spoons, cups and snacks.","persona":"any","source":"infection basics"},
  {"id":"df-1181","cat":"how-germs-spread","type":"sort","hook":"Sort: tells fact from fear about germs.","items":[{"id":"a","text":"Germs are tiny but real"},{"id":"b","text":"Germs can read your mind"},{"id":"c","text":"Clean water stops many germs"},{"id":"d","text":"You catch germs from being unlucky"},{"id":"e","text":"Some germs spread, many do not"},{"id":"f","text":"Every illness is catching"}],"bins":[{"id":"fact","label":"Calm fact","valence":"pos"},{"id":"fear","label":"Fear, not fact","valence":"neg"}],"key":{"a":"fact","b":"fear","c":"fact","d":"fear","e":"fact","f":"fear"},"relearn":"Germs are real but knowable; not every illness is catching, and luck has nothing to do with it.","persona":"any","source":"infection basics"},
  {"id":"df-1182","cat":"how-germs-spread","type":"sort","hook":"Sort: spreads HIV, or spreads a common cold?","items":[{"id":"a","text":"A cough in the air"},{"id":"b","text":"A shared unclean needle"},{"id":"c","text":"Sneezing in a crowd"},{"id":"d","text":"Blood meeting an open cut"},{"id":"e","text":"Breathing close shared air"},{"id":"f","text":"Parent to baby"}],"bins":[{"id":"cold","label":"This spreads a cold","valence":"uhoh"},{"id":"hiv","label":"This is an HIV route","valence":"neg"}],"key":{"a":"cold","b":"hiv","c":"cold","d":"hiv","e":"cold","f":"hiv"},"relearn":"Colds ride coughs and air; HIV rides only blood like shared needles, or parent to baby.","persona":"Asha","source":"HIV contrast / CDC-NIH"},
  {"id":"df-1183","cat":"how-germs-spread","type":"sort","hook":"Sort: a smart habit, or a germ-spreading slip?","items":[{"id":"a","text":"Carrying your own water bottle"},{"id":"b","text":"Drinking from a roadside puddle"},{"id":"c","text":"Washing fruit before eating"},{"id":"d","text":"Eating with muddy hands"},{"id":"e","text":"Coughing into a tissue"},{"id":"f","text":"Sneezing onto a shared plate"}],"bins":[{"id":"smart","label":"Smart habit","valence":"pos"},{"id":"slip","label":"Germ-spreading slip","valence":"neg"}],"key":{"a":"smart","b":"slip","c":"smart","d":"slip","e":"smart","f":"slip"},"relearn":"Own bottle, washed fruit and tissues block germs; the opposites spread them.","persona":"any","source":"infection basics / prevention"},
  {"id":"df-1184","cat":"how-germs-spread","type":"sort","hook":"Sort: how an infection passes, or a thing that never matters.","items":[{"id":"a","text":"Touching a sick person's used tissue"},{"id":"b","text":"What clothes they wear"},{"id":"c","text":"Drinking their leftover half-glass"},{"id":"d","text":"Their caste or money"},{"id":"e","text":"Sharing a spoon mid-illness"},{"id":"f","text":"Which festival they like"}],"bins":[{"id":"route","label":"How germs pass","valence":"neg"},{"id":"nope","label":"Never matters","valence":"pos"}],"key":{"a":"route","b":"nope","c":"route","d":"nope","e":"route","f":"nope"},"relearn":"Germs pass by shared tissues, glasses and spoons, never by clothes, caste, money or festivals.","persona":"Asha","source":"infection basics / anti-stigma"},
  {"id":"df-1185","cat":"how-germs-spread","type":"sort","hook":"Sort: where a sneeze sends germs, or where it does not.","items":[{"id":"a","text":"Onto a friend's face nearby"},{"id":"b","text":"To the next building"},{"id":"c","text":"Onto shared books on the desk"},{"id":"d","text":"To a person you thought about"},{"id":"e","text":"Onto your own hands you then share"},{"id":"f","text":"To a photo on the wall"}],"bins":[{"id":"reaches","label":"A sneeze reaches here","valence":"neg"},{"id":"cannot","label":"It cannot reach here","valence":"pos"}],"key":{"a":"reaches","b":"cannot","c":"reaches","d":"cannot","e":"reaches","f":"cannot"},"relearn":"A sneeze reaches nearby faces, hands and shared things, not photos or thoughts.","persona":"any","source":"infection basics"},
  {"id":"df-1186","cat":"how-germs-spread","type":"sort","hook":"Sort: which germ jumps person to person, or stays put?","items":[{"id":"a","text":"A flu passing round the hostel"},{"id":"b","text":"A bruise from falling"},{"id":"c","text":"A cold going through the family"},{"id":"d","text":"A headache from no sleep"},{"id":"e","text":"A tummy bug shared at a feast"},{"id":"f","text":"A sprained ankle"}],"bins":[{"id":"jumps","label":"Catching (jumps to others)","valence":"neg"},{"id":"stays","label":"Not catching","valence":"pos"}],"key":{"a":"jumps","b":"stays","c":"jumps","d":"stays","e":"jumps","f":"stays"},"relearn":"Colds, flu and tummy bugs are catching; bruises, sprains and sleep headaches are not.","persona":"any","source":"infection basics"},
  {"id":"df-1187","cat":"how-germs-spread","type":"sort","hook":"Sort: cleans the route, or carries germs along it.","items":[{"id":"a","text":"Soap on your hands"},{"id":"b","text":"A shared dirty hand towel"},{"id":"c","text":"Boiled, cooled water"},{"id":"d","text":"Flies landing on open food"},{"id":"e","text":"A washed, covered glass"},{"id":"f","text":"A spit-shared whistle pipe"}],"bins":[{"id":"clean","label":"Cleans the route","valence":"pos"},{"id":"carry","label":"Carries germs along","valence":"neg"}],"key":{"a":"clean","b":"carry","c":"clean","d":"carry","e":"clean","f":"carry"},"relearn":"Soap, boiled water and clean glasses clean the route; dirty towels, flies and shared pipes carry germs.","persona":"any","source":"infection basics / prevention"},
  {"id":"df-1188","cat":"how-germs-spread","type":"spot","hook":"At the dhaba. Spot the two germ-spreading moves.","scene":[{"id":"a","text":"The cook sneezes onto his bare hand, then kneads dough","trick":true},{"id":"b","text":"A fan turns slowly above","trick":false},{"id":"c","text":"A fly sits on the open daal, no cover on it","trick":true},{"id":"d","text":"Customers chat at the next table","trick":false},{"id":"e","text":"The tea is freshly boiled","trick":false}],"why":"A bare-hand sneeze into dough and an uncovered dish let germs reach the food.","relearn":"Bare-hand sneezes and uncovered food are real germ routes.","persona":"Asha","source":"infection basics / India context"},
  {"id":"df-1189","cat":"how-germs-spread","type":"spot","hook":"In a packed bus. Spot the two real risks.","scene":[{"id":"a","text":"A man coughs openly, no hand over his mouth","trick":true},{"id":"b","text":"The bus is crowded and standing-only","trick":false},{"id":"c","text":"A boy wipes his runny nose, then grips the shared pole","trick":true},{"id":"d","text":"The window is open for air","trick":false},{"id":"e","text":"Two friends are laughing together","trick":false}],"why":"An open cough and a nose-wiped hand on the shared pole pass germs to others.","relearn":"Open coughs and germy hands on shared poles spread germs.","persona":"any","source":"infection basics"},
  {"id":"df-1190","cat":"how-germs-spread","type":"spot","hook":"Spot the two things that do NOT spread any germs.","scene":[{"id":"a","text":"Greeting a friend with a namaste","trick":true},{"id":"b","text":"Sneezing onto a shared notebook","trick":false},{"id":"c","text":"Sharing a smile across the class","trick":true},{"id":"d","text":"Drinking from an unclean roadside tap","trick":false},{"id":"e","text":"Coughing right onto a friend's lunch","trick":false}],"why":"A namaste and a smile pass no germs; the others are real routes.","relearn":"A namaste or a smile is completely safe; only certain moves spread germs.","persona":"any","source":"infection basics"},
  {"id":"df-1191","cat":"how-germs-spread","type":"spot","hook":"At a wedding feast. Spot the two germ risks.","scene":[{"id":"a","text":"A child with a cold dips his hand in the shared bowl","trick":true},{"id":"b","text":"The marquee is decorated brightly","trick":false},{"id":"c","text":"One glass of water is passed mouth to mouth","trick":true},{"id":"d","text":"A band plays nearby","trick":false},{"id":"e","text":"Guests sit together on the floor","trick":false}],"why":"A sick hand in a shared bowl and one passed-around glass spread germs.","relearn":"Shared bowls touched by sick hands and a passed-around glass spread germs.","persona":"any","source":"infection basics / India context"},
  {"id":"df-1192","cat":"how-germs-spread","type":"spot","hook":"At the handpump. Spot the two slips.","scene":[{"id":"a","text":"Kids fill bottles but no one washes hands","trick":true},{"id":"b","text":"The handle is metal and old","trick":false},{"id":"c","text":"One child drinks straight from a muddy puddle beside it","trick":true},{"id":"d","text":"It is the morning rush","trick":false},{"id":"e","text":"A girl carries a clean covered pot","trick":false}],"why":"Skipping handwash and drinking puddle water are how tummy germs get in.","relearn":"Unwashed hands and puddle water spread tummy germs.","persona":"Asha","source":"infection basics / India context"},
  {"id":"df-1193","cat":"how-germs-spread","type":"spot","hook":"Spot the two HIV myths hiding in this scene.","scene":[{"id":"a","text":"Someone says 'don't share his plate, you'll catch HIV'","trick":true},{"id":"b","text":"A boy with HIV takes his daily medicine","trick":false},{"id":"c","text":"Another says 'a mosquito bit him, now we'll get it'","trick":true},{"id":"d","text":"Friends sit and eat together calmly","trick":false},{"id":"e","text":"The teacher welcomes everyone to the table","trick":false}],"why":"Sharing a plate and mosquito bites never spread HIV. Both are myths.","relearn":"HIV never spreads through shared plates or mosquito bites.","persona":"Asha","source":"HIV basics / CDC-NIH"},
  {"id":"df-1194","cat":"how-germs-spread","type":"spot","hook":"In the school kitchen. Spot the two germ-spreading moves.","scene":[{"id":"a","text":"A helper coughs over the open rice pot","trick":true},{"id":"b","text":"The stove flame is steady","trick":false},{"id":"c","text":"Vegetables are chopped with unwashed hands","trick":true},{"id":"d","text":"Plates are stacked to one side","trick":false},{"id":"e","text":"Water for cooking is freshly boiled","trick":false}],"why":"Coughing over open food and chopping with unwashed hands carry germs into the meal.","relearn":"Coughs over open food and unwashed hands spread germs into meals.","persona":"any","source":"infection basics"},
  {"id":"df-1195","cat":"how-germs-spread","type":"spot","hook":"Spot the two safe, germ-free actions.","scene":[{"id":"a","text":"Sitting on the same bench as a sick friend, both well-covered","trick":true},{"id":"b","text":"Sipping from a friend's glass while you have a cold","trick":false},{"id":"c","text":"Waving hello from across the field","trick":true},{"id":"d","text":"Sneezing into your palm, then shaking hands","trick":false},{"id":"e","text":"Sharing a spoon mid-fever","trick":false}],"why":"Sitting near and waving spread nothing; the others are real germ routes.","relearn":"Sitting near or waving is safe; sharing glasses or spoons while ill is not.","persona":"any","source":"infection basics"},
  {"id":"df-1196","cat":"how-germs-spread","type":"spot","hook":"At the cinema queue. Spot the two real risks.","scene":[{"id":"a","text":"A girl sneezes into the air, covering nothing","trick":true},{"id":"b","text":"The queue is long and slow","trick":false},{"id":"c","text":"Friends pass one popcorn tub, hands in and out","trick":true},{"id":"d","text":"The poster lights are bright","trick":false},{"id":"e","text":"A couple chats quietly ahead","trick":false}],"why":"An uncovered sneeze and many hands in one shared tub move germs around.","relearn":"Uncovered sneezes and many hands in one shared snack spread germs.","persona":"any","source":"infection basics"},
  {"id":"df-1197","cat":"how-germs-spread","type":"spot","hook":"Spot the two fear-myths, not real germ routes.","scene":[{"id":"a","text":"'You'll catch his illness by sitting near him'","trick":true},{"id":"b","text":"A boy coughs onto the shared ball","trick":false},{"id":"c","text":"'Looking at a sick person makes you sick'","trick":true},{"id":"d","text":"Someone drinks from a dirty open tank","trick":false},{"id":"e","text":"A friend sneezes into bare hands, then high-fives","trick":false}],"why":"Sitting near or looking at someone never spreads germs. Both are fears.","relearn":"Sitting near or looking spreads nothing; only contact does.","persona":"Asha","source":"infection basics / anti-stigma"},
  {"id":"df-1198","cat":"how-germs-spread","type":"spot","hook":"After the toilet. Spot the two germ-spreading slips.","scene":[{"id":"a","text":"A boy skips washing and goes straight to eat","trick":true},{"id":"b","text":"The tap is running with clean water","trick":false},{"id":"c","text":"He then dips his fingers in the shared pickle jar","trick":true},{"id":"d","text":"Soap sits right by the basin","trick":false},{"id":"e","text":"A sign says 'wash your hands'","trick":false}],"why":"Skipping the wash and then touching shared food carry toilet germs onto the meal.","relearn":"Not washing after the toilet, then touching shared food, spreads germs.","persona":"any","source":"infection basics / prevention"},
  {"id":"df-1199","cat":"how-germs-spread","type":"spot","hook":"Spot the two safe ways to be near a sick classmate.","scene":[{"id":"a","text":"Sitting beside her, both covering coughs","trick":true},{"id":"b","text":"Sipping her water bottle to 'show you're brave'","trick":false},{"id":"c","text":"Passing her notes and homework","trick":true},{"id":"d","text":"Sharing her half-eaten tiffin","trick":false},{"id":"e","text":"Using her used handkerchief","trick":false}],"why":"Sitting near and passing notes are safe; sharing her bottle, food or hanky is not.","relearn":"You can sit with a sick friend safely; just don't share food, drinks or used things.","persona":"Diya","source":"infection basics"},
  {"id":"df-1200","cat":"how-germs-spread","type":"spot","hook":"At the tea stall. Spot the two germ risks.","scene":[{"id":"a","text":"Glasses are rinsed in one bucket of cloudy water","trick":true},{"id":"b","text":"Steam rises from the kettle","trick":false},{"id":"c","text":"A customer with a cold sips, then hands his glass back unwashed","trick":true},{"id":"d","text":"The stall is busy at dawn","trick":false},{"id":"e","text":"Biscuits sit in a closed jar","trick":false}],"why":"Cloudy rinse water and a sick person's unwashed glass let germs reach the next drinker.","relearn":"Rinsing glasses in dirty water and reusing a sick person's glass spread germs.","persona":"Asha","source":"infection basics / India context"},
  {"id":"df-1201","cat":"how-germs-spread","type":"spot","hook":"Spot the two real germ routes at the cricket ground.","scene":[{"id":"a","text":"Players share one water bottle, mouth to mouth","trick":true},{"id":"b","text":"The sun is strong overhead","trick":false},{"id":"c","text":"A boy with a cold spits on his palm to grip the ball","trick":true},{"id":"d","text":"The crowd cheers loudly","trick":false},{"id":"e","text":"Friends high-five with clean dry hands","trick":false}],"why":"A mouth-to-mouth bottle and a spit-wet ball pass germs between players.","relearn":"Sharing a bottle mouth to mouth and a spit-wet ball spread germs.","persona":"any","source":"infection basics"},
  {"id":"df-1202","cat":"how-germs-spread","type":"strike-rewrite","hook":"\"You catch a cold just from getting wet in the rain.\"","myth":{"un":"Getting wet in the rain by itself gives you a cold.","re":"Colds come from germs; rain alone cannot make a cold.","why":"It is a virus that infects you, not the rainwater."},"relearn":"Colds come from germs we catch, not from getting wet.","persona":"any","source":"infection basics"},
  {"id":"df-1203","cat":"how-germs-spread","type":"strike-rewrite","hook":"\"Germs spread to people who deserve it.\"","myth":{"un":"Germs only reach people who somehow deserve to fall ill.","re":"Germs spread by routes anyone can meet; they do not choose who is 'good'.","why":"A germ has no idea who you are. It just follows air, water and hands."},"relearn":"Germs follow routes, not character; anyone can catch one.","persona":"Asha","source":"infection basics / anti-stigma"},
  {"id":"df-1204","cat":"how-germs-spread","type":"strike-rewrite","hook":"\"If a friend has a cough, stop being friends.\"","myth":{"un":"Having a cough means a friend is now dangerous to be around.","re":"You stay friends; just cover coughs, don't share food, and wash hands.","why":"Simple habits stop the germ. Ending a friendship does nothing useful."},"relearn":"A friend's cough needs clean habits, not the end of a friendship.","persona":"Diya","source":"infection basics"},
  {"id":"df-1205","cat":"how-germs-spread","type":"strike-rewrite","hook":"\"Boiling water is a waste; all water is safe.\"","myth":{"un":"All water is clean enough, so boiling it is pointless.","re":"Unclean water can carry germs; boiling or filtering makes it safe.","why":"You cannot see water germs, but boiling kills them."},"relearn":"Unclean water can carry germs; boiling or filtering makes it safe.","persona":"Asha","source":"infection basics / prevention"},
  {"id":"df-1206","cat":"how-germs-spread","type":"strike-rewrite","hook":"\"Sitting next to a sick person makes you sick.\"","myth":{"un":"Just sitting next to someone who is ill will make you ill too.","re":"Sitting near is safe; germs spread by coughs, shared things or unclean water.","why":"Closeness alone passes nothing. It takes a real route."},"relearn":"Sitting near someone is safe; germs need a real route to spread.","persona":"any","source":"infection basics"},
  {"id":"df-1207","cat":"how-germs-spread","type":"strike-rewrite","hook":"\"Flies on food are harmless.\"","myth":{"un":"A fly landing on your food does no harm at all.","re":"Flies can carry germs from waste to food; keeping food covered protects you.","why":"Flies move between dirty places and your plate."},"relearn":"Flies can carry germs to food; keep food covered.","persona":"any","source":"infection basics / India context"},
  {"id":"df-1208","cat":"how-germs-spread","type":"strike-rewrite","hook":"\"Donating blood can give you HIV.\"","myth":{"un":"You can catch HIV by donating your blood.","re":"Donating blood uses a fresh sterile needle each time, so it can't give you HIV.","why":"A new, single-use needle never touches anyone else's blood."},"relearn":"Donating blood is safe. Each donor gets a fresh, sterile needle.","persona":"Asha","source":"HIV basics / CDC-NIH"},
  {"id":"df-1209","cat":"how-germs-spread","type":"strike-rewrite","hook":"\"A village person catches more germs than a city person.\"","myth":{"un":"People in villages are simply more likely to catch germs than city folk.","re":"Germs spread by routes, not by where you live; clean water and soap matter anywhere.","why":"It is the route (air, water, hands) that decides, not the address."},"relearn":"Germs spread by routes, not by village or city; clean habits matter everywhere.","persona":"any","source":"infection basics / anti-stigma"},
  {"id":"df-1210","cat":"how-germs-spread","type":"strike-rewrite","hook":"\"Sharing a tiffin with a classmate who has HIV is risky.\"","myth":{"un":"Sharing lunch with a classmate who has HIV could give it to you.","re":"HIV does NOT spread through food, plates or cups. Sharing lunch is safe.","why":"HIV is not in food or saliva in a way that can infect you."},"relearn":"HIV never spreads through shared food, plates or cups.","persona":"Aarav","source":"HIV basics / CDC-NIH"},
  {"id":"df-1211","cat":"how-germs-spread","type":"strike-rewrite","hook":"\"Once one person coughs, the whole class will surely fall ill.\"","myth":{"un":"If one classmate coughs, every single child is bound to get sick.","re":"Covering coughs, fresh air and clean hands stop most of the spread.","why":"Germs spread far less when we use simple, calm habits."},"relearn":"One cough need not sicken everyone; covering and clean hands cut the spread.","persona":"any","source":"infection basics / prevention"},
  {"id":"df-1212","cat":"how-germs-spread","type":"strike-rewrite","hook":"\"Germs are so small they cannot really do anything.\"","myth":{"un":"Germs are too tiny to matter, so they cannot make you ill.","re":"Germs are tiny but real, and they can cause illness. That is why hygiene helps.","why":"Being invisible does not mean being harmless."},"relearn":"Germs are tiny but real; hygiene keeps them from making us ill.","persona":"any","source":"infection basics"},
  {"id":"df-1213","cat":"how-germs-spread","type":"strike-rewrite","hook":"\"Spitting on the street spreads nothing.\"","myth":{"un":"Spitting in public places spreads no germs to anyone.","re":"Spit can carry germs others may touch; using a bin or basin is kinder and safer.","why":"Germs in spit can reach hands and shared surfaces."},"relearn":"Spit can spread germs; keeping it off shared surfaces protects others.","persona":"Asha","source":"infection basics / India context"},
  {"id":"df-1214","cat":"how-germs-spread","type":"strike-rewrite","hook":"\"You can tell who is carrying germs by how they look.\"","myth":{"un":"You can spot who is spreading germs just by looking at them.","re":"You cannot tell by looking; that is why everyone uses the same clean habits.","why":"Germs are invisible. Looks tell you nothing about them."},"relearn":"You cannot tell who carries germs by looking; clean habits are for everyone.","persona":"any","source":"infection basics / anti-stigma"},
  {"id":"df-1215","cat":"how-germs-spread","type":"strike-rewrite","hook":"\"A toilet seat can give you any infection.\"","myth":{"un":"Sitting on a toilet seat will give you serious infections.","re":"Most germs do not spread from a seat; clean hands after the toilet matter far more.","why":"The big risk is unwashed hands touching your mouth or food, not the seat itself."},"relearn":"It is unwashed hands, not the toilet seat, that spread most germs.","persona":"Asha","source":"infection basics / prevention"},
  {"id":"df-1216","cat":"how-germs-spread","type":"match","hook":"Match each germ route to the habit that blocks it.","pairs":[{"left":"Germs on your hands","right":"Wash with soap and water"},{"left":"Germs in the air from a cough","right":"Cover your cough with your elbow"},{"left":"Germs in drinking water","right":"Boil or filter it first"},{"left":"Germs from flies on food","right":"Keep food covered"},{"left":"Germs on a shared glass","right":"Use your own glass when ill"}],"relearn":"Every germ route has a simple habit that blocks it.","persona":"any","source":"infection basics / prevention"},
  {"id":"df-1217","cat":"how-germs-spread","type":"match","hook":"Match each illness to where it usually comes from.","pairs":[{"left":"A sneezy cold","right":"Breathing air with cough germs"},{"left":"Typhoid","right":"Drinking unclean water"},{"left":"An infected scrape","right":"Germs entering a cut"},{"left":"A flu outbreak","right":"Crowded indoor air"},{"left":"A street-food tummy bug","right":"Unclean or stale food"}],"relearn":"Each illness has a knowable route: air, water, food or a wound.","persona":"Asha","source":"infection basics"},
  {"id":"df-1218","cat":"how-germs-spread","type":"match","hook":"Match the myth to the calm fact that replaces it.","pairs":[{"left":"\"HIV spreads by hugging\"","right":"Hugs never spread HIV"},{"left":"\"Mosquitoes spread HIV\"","right":"Mosquitoes spread no HIV"},{"left":"\"Sharing a plate spreads HIV\"","right":"Food and plates are safe"},{"left":"\"A toilet seat spreads HIV\"","right":"Seats and surfaces are safe"},{"left":"\"HIV spreads like a cold\"","right":"HIV is not airborne"}],"relearn":"Everyday contact never spreads HIV. Only blood or parent-to-baby routes do.","persona":"Asha","source":"HIV basics / CDC-NIH"},
  {"id":"df-1219","cat":"how-germs-spread","type":"match","hook":"Match the place to the germ route to watch there.","pairs":[{"left":"A crowded bus","right":"Coughs in close air"},{"left":"A handpump","right":"Unwashed hands and water"},{"left":"A wedding feast","right":"Shared bowls and one glass"},{"left":"A cricket ground","right":"A shared water bottle"},{"left":"A tea stall","right":"Glasses rinsed in dirty water"}],"relearn":"Each everyday place has one germ route worth knowing.","persona":"any","source":"infection basics / India context"},
  {"id":"df-1220","cat":"how-germs-spread","type":"match","hook":"Match safe contact to the worry it answers.","pairs":[{"left":"Hugging a friend with HIV","right":"Completely safe, hug freely"},{"left":"Sitting beside someone with a cold","right":"Safe if coughs are covered"},{"left":"Sharing a smile","right":"Passes no germs at all"},{"left":"Playing a game together","right":"Safe, germs need a real route"},{"left":"Passing notes in class","right":"Safe, no germs travel"}],"relearn":"Most everyday contact children worry about is completely safe.","persona":"Diya","source":"infection basics / anti-stigma"},
  {"id":"df-1221","cat":"how-germs-spread","type":"match","hook":"Match the germ to how far it can travel.","pairs":[{"left":"A cold sneeze","right":"Through nearby air"},{"left":"A water germ","right":"Through what you drink"},{"left":"A wound germ","right":"Into an open cut"},{"left":"A hand-passed germ","right":"On things many people touch"},{"left":"HIV","right":"Only through blood or parent to baby"}],"relearn":"Each germ has its own reach; knowing it helps you prevent it.","persona":"Asha","source":"infection basics"},
  {"id":"df-1222","cat":"how-germs-spread","type":"match","hook":"Match the slip to the smarter habit.","pairs":[{"left":"Eating with muddy hands","right":"Wash hands before food"},{"left":"Drinking puddle water","right":"Carry clean boiled water"},{"left":"Sneezing into bare hands","right":"Sneeze into your elbow"},{"left":"Sharing a glass when ill","right":"Keep your own glass"},{"left":"Leaving food uncovered","right":"Cover it from flies"}],"relearn":"Each germ-spreading slip has an easy, everyday fix.","persona":"any","source":"infection basics / prevention"},
  {"id":"df-1223","cat":"how-germs-spread","type":"match","hook":"Match each germ belief to what makes it real or false.","pairs":[{"left":"Germs are tiny but real","right":"True: they're just invisible"},{"left":"Germs can read your mind","right":"False: germs have no senses"},{"left":"Clean hands cut the spread","right":"True: soap removes germs"},{"left":"Looking at the ill makes you ill","right":"False: looking passes nothing"},{"left":"Some illnesses are not catching","right":"True: a sprain can't spread"}],"relearn":"Telling fact from fear is the first step to staying calm and well.","persona":"any","source":"infection basics"},
  {"id":"df-1224","cat":"how-germs-spread","type":"match","hook":"Match each thing to whether it can pass germs.","pairs":[{"left":"A shared, used tissue","right":"Can pass germs by contact"},{"left":"What a person wears","right":"Clothes never spread germs"},{"left":"A passed-round glass when ill","right":"Can pass germs by saliva"},{"left":"A person's caste or money","right":"These never spread germs"},{"left":"An open cough nearby","right":"Can pass germs through air"}],"relearn":"Germs pass by physical routes, never by clothes, caste or money.","persona":"Asha","source":"infection basics / anti-stigma"},
  {"id":"df-1225","cat":"how-germs-spread","type":"role-play","hook":"A cousin says germs spread by 'bad luck'. Say the calm fact.","setup":"At a family lunch, a cousin insists people fall ill from bad luck. What do you say?","yourLine":[{"text":"\"Actually, germs spread by air, water and hands, not luck.\"","best":true},{"text":"\"Maybe... I'm not really sure.\""}],"relearn":"Germs spread by real routes, not by luck: a calm fact helps.","persona":"Aarav","source":"infection basics"},
  {"id":"df-1226","cat":"how-germs-spread","type":"role-play","hook":"A friend won't sit by a kid with a cold. Say something steady.","setup":"Your friend refuses to sit near a classmate with a cold. What do you say?","yourLine":[{"text":"\"Sitting near is fine. We just cover coughs and wash hands.\"","best":true},{"text":"\"Yeah, better stay far from him.\""}],"relearn":"Sitting near is safe; covering coughs and clean hands are what matter.","persona":"Diya","source":"infection basics"},
  {"id":"df-1227","cat":"how-germs-spread","type":"role-play","hook":"Someone says 'don't drink water here, you'll get sick'. Reply well.","setup":"At a stall, a friend says all the water will make you ill. What do you say?","yourLine":[{"text":"\"Let's just use clean or boiled water. That's the real fix.\"","best":true},{"text":"\"Guess we can never drink anywhere safely.\""}],"relearn":"Clean or boiled water is the calm, sensible fix, not fearing all water.","persona":"Asha","source":"infection basics / prevention"},
  {"id":"df-1228","cat":"how-germs-spread","type":"role-play","hook":"A classmate blames a sick boy for being 'dirty'. Answer kindly.","setup":"A classmate says the boy got ill because he is 'dirty'. What do you say?","yourLine":[{"text":"\"Anyone can catch a germ. It's the route, not the person.\"","best":true},{"text":"\"Yeah, he probably is dirty.\""}],"relearn":"Anyone can catch a germ; it is never about being 'dirty'.","persona":"any","source":"infection basics / anti-stigma"},
  {"id":"df-1229","cat":"how-germs-spread","type":"role-play","hook":"A younger sibling fears germs are everywhere. Reassure them.","setup":"Your little sister thinks every touch will make her sick. What do you say?","yourLine":[{"text":"\"Most things are safe. We just wash hands and cover coughs.\"","best":true},{"text":"\"You're right, better not touch anything.\""}],"relearn":"Most everyday things are safe; a few simple habits keep germs in check.","persona":"any","source":"infection basics"},
  {"id":"df-1230","cat":"how-germs-spread","type":"role-play","hook":"A friend says you'll catch HIV from a classmate's lunch. Reply.","setup":"A friend warns you not to share lunch with a classmate who has HIV. What do you say?","yourLine":[{"text":"\"HIV doesn't spread through food. Sharing lunch is totally safe.\"","best":true},{"text":"\"Okay, I'll keep my food away from his.\""}],"relearn":"HIV never spreads through shared food. Lunch together is safe.","persona":"Aarav","source":"HIV basics / CDC-NIH"},
  {"id":"df-1231","cat":"how-germs-spread","type":"role-play","hook":"A teammate spits to grip the ball. Say the cleaner way.","setup":"A teammate spits on the ball to grip it before passing it round. What do you say?","yourLine":[{"text":"\"Let's not spit on it. That just passes germs to everyone.\"","best":true},{"text":"\"Whatever, just throw it here.\""}],"relearn":"Spit on shared things passes germs; a clean grip is kinder.","persona":"any","source":"infection basics"},
  {"id":"df-1232","cat":"how-germs-spread","type":"role-play","hook":"An aunt says rain caused your cold. Correct her gently.","setup":"Your aunt says the rain gave you your cold. What do you say, respectfully?","yourLine":[{"text":"\"It's actually germs, Auntie. Rain alone can't cause a cold.\"","best":true},{"text":"\"You're right, it was definitely the rain.\""}],"relearn":"Colds come from germs, not rain. A gentle fact corrects the myth.","persona":"Rohit","source":"infection basics"},
  {"id":"df-1233","cat":"how-germs-spread","type":"reflect","hook":"Which clean habit feels easiest for you to remember?","prompt":"There's no wrong pick. Which one would you reach for first?","options":["Washing hands with soap","Covering my cough","Carrying clean water","Keeping food covered"],"affirm":"Any one of these is a real, everyday way you help stop germs. Nicely chosen.","relearn":"Each of these habits blocks a real germ route.","persona":"any","source":"infection basics / prevention"},
  {"id":"df-1234","cat":"how-germs-spread","type":"reflect","hook":"When does covering a cough feel most natural to you?","prompt":"No right answer. When do you remember to do it?","options":["In class","On a crowded bus","At home with family","At a big gathering"],"affirm":"Wherever you do it, covering your cough keeps your germs from others. Good thinking.","relearn":"Covering a cough keeps your germs out of the shared air.","persona":"any","source":"infection basics"},
  {"id":"df-1235","cat":"how-germs-spread","type":"reflect","hook":"What helps you feel calm, not scared, about germs?","prompt":"Any answer is fine. What steadies you?","options":["Knowing the real routes","Having clean water ready","Washing my hands","Asking a trusted grown-up"],"affirm":"Knowing the facts is exactly what turns fear into calm. That's the whole idea.","relearn":"Knowing how germs really spread turns fear into calm.","persona":"any","source":"infection basics"},
  {"id":"df-1236","cat":"how-germs-spread","type":"reflect","hook":"Who would you ask if you weren't sure how an illness spreads?","prompt":"There's no wrong choice. Who do you trust with a health question?","options":["A parent or elder","The school teacher","A doctor or nurse","An ASHA didi"],"affirm":"Any trusted grown-up is a great person to ask. Curious questions are smart, not silly.","relearn":"A trusted grown-up, teacher, doctor or ASHA can answer health questions.","persona":"any","source":"infection basics"},
  {"id":"df-1237","cat":"how-germs-spread","type":"reflect","hook":"Which 'germs spread by feelings' idea have you heard before?","prompt":"No wrong answer. Just notice which one you've heard.","options":["'Anger makes you sick'","'Jealousy spreads illness'","'Bad luck causes germs'","I haven't heard these"],"affirm":"Noticing a myth is the first step to setting it aside. Germs only travel by real routes.","relearn":"Germs never spread by feelings or bad luck, only by real routes.","persona":"any","source":"infection basics"},
  {"id":"df-1238","cat":"how-germs-spread","type":"reflect","hook":"Where do you feel most ready to keep water clean?","prompt":"Any choice is good. Where would you start?","options":["Boiling water at home","Carrying my own bottle","Avoiding puddle water","Covering the storage pot"],"affirm":"Each of these blocks a real water-germ route. Whatever you pick, you're protecting yourself.","relearn":"Boiling, own bottle, avoiding puddles and covering pots all block water germs.","persona":"Asha","source":"infection basics / prevention"},
  {"id":"df-1239","cat":"how-germs-spread","type":"reflect","hook":"What would help you welcome a classmate who's been ill?","prompt":"No right answer. What feels right to you?","options":["Sitting with them","Sharing notes","Saying 'glad you're back'","Just being normal with them"],"affirm":"All of these are safe and kind. A classmate who was ill belongs right back with friends.","relearn":"Welcoming a classmate who was ill is both safe and kind.","persona":"Diya","source":"infection basics / anti-stigma"},
  {"id":"df-1240","cat":"how-germs-spread","type":"reflect","hook":"Which germ fact surprised you the most?","prompt":"There's no wrong pick. Which one stuck with you?","options":["Hugs never spread HIV","Sitting near is safe","Feelings don't spread germs","Mosquitoes don't spread HIV"],"affirm":"Whichever surprised you, it's a fact worth keeping. Facts beat fear.","relearn":"Every one of these is a true germ fact. Facts beat fear.","persona":"any","source":"infection basics"},
  {"id":"df-1241","cat":"how-germs-spread","type":"branch","hook":"You're about to eat, but your hands are dusty. What do you do?","options":[{"text":"Wash with soap and water first","consequence":"Clean hands keep germs out of your food.","best":true},{"text":"Wipe them on your shirt and eat","consequence":"Dust and germs from your hands go onto the food and into you."},{"text":"Just eat. They look fine","consequence":"Germs you can't see can still make your tummy unwell."}],"debrief":"Soap before eating blocks germs that ride in on your hands.","relearn":"Soap before eating blocks hand germs.","persona":"any","source":"infection basics / prevention"},
  {"id":"df-1242","cat":"how-germs-spread","type":"branch","hook":"A cough is coming and you're in a crowded room. What do you do?","options":[{"text":"Cough into your elbow","consequence":"Your germs stay off your hands and the air.","best":true},{"text":"Cough into your open hands","consequence":"Germs land on your hands, then on everything you touch next."},{"text":"Cough into the air","consequence":"Germs drift to the people standing close around you."}],"debrief":"Coughing into your elbow keeps germs from the shared air.","relearn":"Cough into your elbow to keep germs off hands and air.","persona":"any","source":"infection basics"},
  {"id":"df-1243","cat":"how-germs-spread","type":"branch","hook":"You're thirsty on a walk. Only a muddy puddle is nearby. What do you do?","options":[{"text":"Wait and drink clean water from home","consequence":"Clean water quenches your thirst without the tummy germs.","best":true},{"text":"Drink from the puddle","consequence":"Puddle water can carry germs that cause loose motions."},{"text":"Scoop it and let the mud settle first","consequence":"Letting mud settle doesn't remove the germs in it."}],"debrief":"Clean or boiled water is worth the wait.","relearn":"Puddle water carries tummy germs.","persona":"Asha","source":"infection basics / prevention"},
  {"id":"df-1244","cat":"how-germs-spread","type":"branch","hook":"A classmate with a cold offers a sip from his bottle. What do you do?","options":[{"text":"Thank him but use my own bottle","consequence":"You stay friendly; his germs never reach you.","best":true},{"text":"Take a big sip to be polite","consequence":"His cold germs are on the rim and can reach you."},{"text":"Wipe the rim and then drink","consequence":"A quick wipe doesn't remove all the germs."}],"debrief":"Your own bottle stays friendly and keeps cold germs away.","relearn":"Use your own bottle to keep cold germs from passing.","persona":"Diya","source":"infection basics"},
  {"id":"df-1245","cat":"how-germs-spread","type":"branch","hook":"Kids are passing one snack, hands in and out. What do you do?","options":[{"text":"Suggest serving it onto separate plates","consequence":"Everyone shares without sharing germs.","best":true},{"text":"Reach in like everyone else","consequence":"Many unwashed hands in one bowl spread germs around."},{"text":"Eat the whole bowl yourself","consequence":"That's unfair to friends and doesn't solve the germ issue."}],"debrief":"Separate plates let everyone share without sharing germs.","relearn":"Separate plates share food, not germs.","persona":"any","source":"infection basics"},
  {"id":"df-1246","cat":"how-germs-spread","type":"branch","hook":"You feel quite unwell with a cough before school. What do you do?","options":[{"text":"Rest at home and tell a grown-up","consequence":"You recover faster and your germs stay off the class.","best":true},{"text":"Go in and cough around the class","consequence":"Your germs can spread to many classmates in close air."},{"text":"Go in but hide that you're ill","consequence":"Others can't protect themselves if they don't know."}],"debrief":"Resting when very ill protects you and others.","relearn":"Rest when very ill; tell a grown-up.","persona":"any","source":"infection basics / prevention"},
  {"id":"df-1247","cat":"how-germs-spread","type":"branch","hook":"Friends say to keep away from a boy because 'he gives germs'. What do you do?","options":[{"text":"Say germs spread by routes, and include him","consequence":"The myth loses its grip and the boy stays in.","best":true},{"text":"Join them and avoid the boy","consequence":"He's left out for no real reason, and the myth grows."},{"text":"Stay quiet and walk away","consequence":"The fear keeps spreading and he stays excluded."}],"debrief":"Including him is safe and kind.","relearn":"Germs spread by routes, not by a person.","persona":"Diya","source":"infection basics / anti-stigma"},
  {"id":"df-1248","cat":"how-germs-spread","type":"branch","hook":"An elder says to throw out a sick relative's plate forever. What do you do?","options":[{"text":"Gently explain washing it well is enough","consequence":"The plate stays in use; dignity kept.","best":true},{"text":"Quietly agree and throw it out","consequence":"It wastes a plate and feeds the 'unclean' idea."},{"text":"Argue loudly that they're wrong","consequence":"A sharp argument makes the elder defensive."}],"debrief":"Washing dishes well handles germs; a calm fact protects dignity.","relearn":"Washing dishes well clears germs.","persona":"Rohit","source":"infection basics / anti-stigma"},
  {"id":"df-1260","cat":"kindness-not-fear","type":"branch","hook":"At the water cooler, a boy with HIV reaches for the shared glass and others step back.","options":[{"text":"Drink after him like normal and smile","consequence":"Everyone sees sharing a glass is safe.","outcome":"include","best":true},{"text":"Quietly use a different glass","consequence":"A shared glass never spreads HIV; it's safe."}],"debrief":"Shared cups don't spread HIV; drinking after a friend is safe.","relearn":"Sharing a glass is safe; use it to show there's nothing to fear.","persona":"Diya","source":"stigma reduction / inclusion"},
  {"id":"df-1261","cat":"kindness-not-fear","type":"branch","hook":"On a school trip the seat next to a girl known to have HIV stays empty.","options":[{"text":"Take the seat and chat with her","consequence":"She feels welcome; others fill in too.","outcome":"include","best":true},{"text":"Sit elsewhere, leave it empty","consequence":"Sitting beside her is safe; the gap only hurts."}],"debrief":"Sitting next to someone with HIV is safe; an empty seat stings.","relearn":"Take the seat beside a classmate with HIV; nearness is safe.","persona":"any","source":"stigma reduction / inclusion"},
  {"id":"df-1262","cat":"kindness-not-fear","type":"branch","hook":"A teammate with HIV scrapes his knee in the game and others freeze.","options":[{"text":"Help him up, calmly get the first-aid box","consequence":"He's cared for; the game carries on.","outcome":"care","best":true},{"text":"Back away from the blood","consequence":"A covered scrape is safe; freezing leaves him alone."}],"debrief":"A small cut is handled calmly with a plaster; a hurt friend needs help.","relearn":"Help an injured friend calmly; a covered scrape is managed like anyone's.","persona":"any","source":"stigma reduction / first aid"},
  {"id":"df-1263","cat":"kindness-not-fear","type":"branch","hook":"Picking teams, a boy is being skipped because his sister has HIV.","options":[{"text":"Pick him first; he's a strong player","consequence":"He's back in; the skipping stops.","outcome":"upstander","best":true},{"text":"Skip him too so it's not 'odd'","consequence":"His sister's health says nothing about him."}],"debrief":"A relative's illness is no reason to leave someone out.","relearn":"Don't judge a friend by a relative's illness; include him.","persona":"any","source":"stigma reduction / upstander"},
  {"id":"df-1264","cat":"kindness-not-fear","type":"branch","hook":"A shopkeeper aunty won't take coins from a man rumoured to have HIV.","options":[{"text":"Say coins are safe and pay normally","consequence":"You model calm facts; he keeps his dignity.","outcome":"informed","best":true},{"text":"Walk out to avoid the scene","consequence":"Coins and touch never spread HIV; a fact would help."}],"debrief":"Coins and hands are safe; a calm fact eases fear.","relearn":"Money and touch don't carry HIV; a gentle fact guards dignity.","persona":"Rohit","source":"stigma reduction / dignity"},
  {"id":"df-1265","cat":"kindness-not-fear","type":"branch","hook":"Your cousin won't let a neighbour's child with HIV into the birthday game.","options":[{"text":"Invite the child in; playing is safe","consequence":"The child joins; your cousin's fear fades.","outcome":"include","best":true},{"text":"Let your cousin decide, stay quiet","consequence":"Playing together is safe; a word lets him join."}],"debrief":"Playing together can't spread HIV; everyone belongs.","relearn":"Welcome a child with HIV into play; togetherness is safe.","persona":"Diya","source":"stigma reduction / inclusion"},
  {"id":"df-1266","cat":"kindness-not-fear","type":"branch","hook":"At a wedding feast, relatives say a guest with HIV should use separate plates.","options":[{"text":"Sit and eat with the guest, same row","consequence":"The whispering fades; he's treated as family.","outcome":"include","best":true},{"text":"Eat far off to dodge the whispers","consequence":"Sharing a meal is safe; eating together helps."}],"debrief":"Shared food and plates never spread HIV; eating together honours a guest.","relearn":"Eat alongside a guest with HIV; shared meals are safe.","persona":"any","source":"stigma reduction / inclusion"},
  {"id":"df-1267","cat":"kindness-not-fear","type":"branch","hook":"A classmate confides her mother has HIV and begs you not to tell.","options":[{"text":"Promise to keep it private; be her friend","consequence":"She trusts you and feels less alone.","outcome":"care","best":true},{"text":"Tell one 'safe' friend for support","consequence":"Her family's health is hers; privacy is the support."}],"debrief":"Someone's health is private; keep it and stay a friend.","relearn":"Guard a friend's health secret; privacy is the real support.","persona":"any","source":"stigma reduction / privacy"},
  {"id":"df-1268","cat":"kindness-not-fear","type":"branch","hook":"Your grandmother wants to wash a visiting child's plate apart because he has HIV.","options":[{"text":"Wash all plates together; it's safe","consequence":"Grandma relaxes; the child isn't singled out.","outcome":"informed","best":true},{"text":"Wash his plate apart for peace","consequence":"Plates are safe; a gentle fact keeps him included."}],"debrief":"Plates and washing-up never carry HIV; calm facts ease an elder's worry.","relearn":"Wash plates together; a respectful fact spares a child from being singled out.","persona":"Rohit","source":"stigma reduction / correct an elder"},
  {"id":"df-1269","cat":"kindness-not-fear","type":"branch","hook":"A boy with HIV is told he can't share the cricket bat the others use.","options":[{"text":"Hand him the bat; bat after him","consequence":"He plays; sharing gear is no risk.","outcome":"include","best":true},{"text":"Say he should bring his 'own' bat","consequence":"Sharing a bat is safe; handing it ends the exclusion."}],"debrief":"Shared sports gear can't spread HIV; everyone gets a turn.","relearn":"Share the bat with a friend who has HIV; gear is safe for all.","persona":"any","source":"stigma reduction / inclusion"},
  {"id":"df-1270","cat":"kindness-not-fear","type":"branch","hook":"A group chat is forwarding a 'warning' photo of a local person said to have HIV.","options":[{"text":"Don't forward; ask them to delete it","consequence":"The chain breaks; he's spared public shaming.","outcome":"upstander","best":true},{"text":"Forward it so people 'stay safe'","consequence":"Health is private; the photo shames, not protects."}],"debrief":"Exposing someone's health online is cruel and pointless; stop the chain.","relearn":"Refuse to forward a health-shaming photo; ask the chat to delete it.","persona":"Aarav","source":"stigma reduction / privacy"},
  {"id":"df-1271","cat":"kindness-not-fear","type":"branch","hook":"A younger child is scared to hug a cousin who has HIV at a family puja.","options":[{"text":"Hug the cousin first, then offer your hand","consequence":"The child copies you and joins in.","outcome":"reassure","best":true},{"text":"Let the child hang back","consequence":"Hugging is safe; showing the child eases the fear."}],"debrief":"Hugging never spreads HIV; modelling a hug shows a child it's safe.","relearn":"Show a scared child a hug is safe; lead with your own example.","persona":"any","source":"stigma reduction / reassure"},
  {"id":"df-1272","cat":"kindness-not-fear","type":"branch","hook":"A neighbour says a tutor should be fired because he is living with HIV.","options":[{"text":"Say he teaches well; HIV is no reason","consequence":"You defend a fair man with a steady fact.","outcome":"informed","best":true},{"text":"Stay out of grown-up business","consequence":"His health doesn't affect teaching; a fact defends him."}],"debrief":"HIV is no reason to lose work; everyday contact in class is safe.","relearn":"Defend a person's livelihood; HIV status is no reason to push them out.","persona":"Rohit","source":"stigma reduction / dignity"},
  {"id":"df-1273","cat":"kindness-not-fear","type":"branch","hook":"At the hostel mess, students leave a gap around a roommate on daily HIV medicine.","options":[{"text":"Sit next to him and pass the food","consequence":"The gap closes; mealtimes feel normal.","outcome":"include","best":true},{"text":"Sit apart so it's not 'weird'","consequence":"Sitting and sharing food is safe; close the gap."}],"debrief":"Daily medicine keeps people well; sharing a table is safe.","relearn":"Close the gap at the table; eating beside a friend on treatment is safe.","persona":"Diya","source":"stigma reduction / inclusion"},
  {"id":"df-1275","cat":"kindness-not-fear","type":"role-play","hook":"At the tap, a girl jokes that you'll 'catch it' if you wash hands next to a boy with HIV.","setup":"Set her straight, kindly. Say:","yourLine":[{"text":"\"Washing next to him can't pass HIV, come on, that's just a myth.\"","best":true},{"text":"\"Maybe, I'll use the other tap.\""}],"relearn":"Sharing a tap is safe; a calm fact can stop a hurtful joke.","persona":"any","source":"stigma reduction / voice"},
  {"id":"df-1276","cat":"kindness-not-fear","type":"role-play","hook":"A relative tells you not to share your tiffin with a friend who has HIV.","setup":"Reassure your relative. Say:","yourLine":[{"text":"\"Sharing food is safe, auntie, HIV doesn't spread that way.\"","best":true},{"text":"\"Okay, I'll keep my tiffin to myself.\""}],"relearn":"You can gently correct a relative's food fear with a fact.","persona":"Rohit","source":"stigma reduction / correct an elder"},
  {"id":"df-1277","cat":"kindness-not-fear","type":"role-play","hook":"A classmate with HIV thanks you for sitting with him and seems surprised.","setup":"Make it ordinary, not a big deal. Say:","yourLine":[{"text":"\"It's just lunch, yaar, we're friends.\"","best":true},{"text":"\"I'm being really brave, you know.\""}],"relearn":"Treating inclusion as normal, not heroic, is the kindest message.","persona":"Diya","source":"stigma reduction / friendship"},
  {"id":"df-1278","cat":"kindness-not-fear","type":"role-play","hook":"Kids chant a cruel nickname at a boy because of his illness.","setup":"Name it and stop it. Say:","yourLine":[{"text":"\"Stop, that's mean, and it's not even how illness works.\"","best":true},{"text":"\"Don't drag me into it.\""}],"relearn":"You can stop cruel teasing and correct the fear at once.","persona":"Aarav","source":"stigma reduction / voice"},
  {"id":"df-1279","cat":"kindness-not-fear","type":"role-play","hook":"A friend whispers that you should warn others a new girl has HIV.","setup":"Protect her privacy. Say:","yourLine":[{"text":"\"That's private, and it's safe to be near her anyway.\"","best":true},{"text":"\"Good idea, I'll pass it on.\""}],"relearn":"You can refuse to spread someone's private health news.","persona":"any","source":"stigma reduction / privacy"},
  {"id":"df-1280","cat":"kindness-not-fear","type":"role-play","hook":"A boy with HIV holds back from joining the kabaddi line.","setup":"Wave him in. Say:","yourLine":[{"text":"\"Come on, you're on my team, let's go!\"","best":true},{"text":"\"You can just watch if you want.\""}],"relearn":"An eager 'you're on my team' beats a polite sideline.","persona":"any","source":"stigma reduction / inclusion"},
  {"id":"df-1281","cat":"kindness-not-fear","type":"role-play","hook":"Your nani frets that a child with HIV touched the prasad.","setup":"Ease her worry. Say:","yourLine":[{"text":"\"It's safe, nani, touch can't pass HIV, the prasad is fine.\"","best":true},{"text":"\"You're right, let's not eat it.\""}],"relearn":"A respectful fact can calm an elder's fear about touch.","persona":"Rohit","source":"stigma reduction / correct an elder"},
  {"id":"df-1282","cat":"kindness-not-fear","type":"role-play","hook":"A friend asks if you're scared to be best mates with someone who has HIV.","setup":"Answer honestly. Say:","yourLine":[{"text":"\"Not at all, I know the facts, he's just my friend.\"","best":true},{"text":"\"A little, but I hide it.\""}],"relearn":"Knowing the facts lets friendship stay easy and unafraid.","persona":"Aarav","source":"stigma reduction / friendship"},
  {"id":"df-1283","cat":"kindness-not-fear","type":"role-play","hook":"A teacher pairs you with a student who is living with HIV for a project.","setup":"Start warmly. Say:","yourLine":[{"text":"\"Great, let's pick our topic, partner!\"","best":true},{"text":"\"Um, can I switch partners?\""}],"relearn":"A warm start tells a partner they belong, plain and simple.","persona":"any","source":"stigma reduction / inclusion"},
  {"id":"df-1284","cat":"kindness-not-fear","type":"role-play","hook":"Someone says a girl with HIV should sit at the 'back row, away from us'.","setup":"Refuse the seating. Say:","yourLine":[{"text":"\"No need, it's safe, she can sit right here with us.\"","best":true},{"text":"\"Fine, back row it is.\""}],"relearn":"You can refuse to push someone aside over a baseless fear.","persona":"Diya","source":"stigma reduction / inclusion"},
  {"id":"df-1285","cat":"kindness-not-fear","type":"role-play","hook":"A vendor won't shake hands with a customer rumoured to have HIV.","setup":"Model the handshake. Say:","yourLine":[{"text":"\"I'll shake your hand, sir, a handshake is perfectly safe.\"","best":true},{"text":"\"Maybe just wave, to be safe.\""}],"relearn":"A handshake is safe; modelling it quietly defends someone's dignity.","persona":"any","source":"stigma reduction / dignity"},
  {"id":"df-1286","cat":"kindness-not-fear","type":"role-play","hook":"A boy is being mocked because his uncle is in hospital with HIV.","setup":"Stand with him. Say:","yourLine":[{"text":"\"Leave him alone, his uncle's illness isn't his fault or yours.\"","best":true},{"text":"\"Bad luck, mate.\""}],"relearn":"No one's family illness is a reason to be mocked.","persona":"any","source":"stigma reduction / dignity"},
  {"id":"df-1287","cat":"kindness-not-fear","type":"role-play","hook":"A classmate worries her friendship with a girl on HIV medicine is 'risky'.","setup":"Reassure her. Say:","yourLine":[{"text":"\"It's not risky at all, being friends with her is totally safe.\"","best":true},{"text":"\"Yeah, maybe keep your distance.\""}],"relearn":"Friendship with someone on treatment carries no risk at all.","persona":"Diya","source":"stigma reduction / reassure"},
  {"id":"df-1288","cat":"kindness-not-fear","type":"role-play","hook":"An older boy tells juniors that a child with HIV is 'cursed'.","setup":"Correct him calmly. Say:","yourLine":[{"text":"\"That's not true, HIV is an infection, never a curse.\"","best":true},{"text":"\"If you say so, bhaiya.\""}],"relearn":"HIV is an infection, never a curse; you can say so plainly.","persona":"Aarav","source":"stigma reduction / voice"},
  {"id":"df-1289","cat":"kindness-not-fear","type":"role-play","hook":"A friend asks how to be a good friend to a classmate who just shared he has HIV.","setup":"Give the simplest answer. Say:","yourLine":[{"text":"\"Just be normal with him, like nothing changed.\"","best":true},{"text":"\"Treat him extra gently and carefully.\""}],"relearn":"The best friendship after a disclosure is staying exactly the same.","persona":"any","source":"stigma reduction / friendship"},
  {"id":"df-1290","cat":"kindness-not-fear","type":"role-play","hook":"A girl says she'll skip the class party because a boy with HIV is going.","setup":"Encourage her to come. Say:","yourLine":[{"text":"\"Please come, it's safe and the party won't be the same without you.\"","best":true},{"text":"\"Up to you, I get it.\""}],"relearn":"You can invite a hesitant friend in and reassure them it's safe.","persona":"Diya","source":"stigma reduction / reassure"},
  {"id":"df-1291","cat":"kindness-not-fear","type":"role-play","hook":"Someone insists a child with HIV must use a separate water bottle 'forever'.","setup":"Offer to share yours. Say:","yourLine":[{"text":"\"Here, share mine, drinking after each other is totally safe.\"","best":true},{"text":"\"Better keep bottles separate, na.\""}],"relearn":"Sharing a water bottle is safe; offering yours shows it plainly.","persona":"any","source":"stigma reduction / inclusion"},
  {"id":"df-1292","cat":"kindness-not-fear","type":"role-play","hook":"A relative says it's 'too risky' to let a child with HIV stay overnight.","setup":"Welcome the child. Say:","yourLine":[{"text":"\"It's safe to host him, uncle, sharing a room can't pass HIV.\"","best":true},{"text":"\"Okay, maybe another time then.\""}],"relearn":"Hosting and sharing a room is safe; you can welcome the child warmly.","persona":"Rohit","source":"stigma reduction / correct an elder"},
  {"id":"df-1293","cat":"kindness-not-fear","type":"role-play","hook":"A boy with HIV says he's nervous to tell the class he'll miss days for clinic visits.","setup":"Back him up. Say:","yourLine":[{"text":"\"I'll save your notes, take your time at the clinic.\"","best":true},{"text":"\"Maybe don't tell them at all.\""}],"relearn":"Practical support beats pressure to hide; offer to keep notes.","persona":"any","source":"stigma reduction / support"},
  {"id":"df-1294","cat":"kindness-not-fear","type":"role-play","hook":"A friend laughs that a girl 'gave HIV to the whole class by sharing pencils'.","setup":"Bust the myth out loud. Say:","yourLine":[{"text":"\"Pencils can't pass HIV, that's a myth, don't say it.\"","best":true},{"text":"\"Ha, good one.\""}],"relearn":"Sharing pencils is safe; you can name a myth and ask it to stop.","persona":"Aarav","source":"stigma reduction / voice"},
  {"id":"df-1295","cat":"kindness-not-fear","type":"role-play","hook":"A child asks why their new friend takes a tablet every morning.","setup":"Answer without making it a spectacle. Say:","yourLine":[{"text":"\"It's his medicine, that's private, but he's totally fine.\"","best":true},{"text":"\"He's sick, didn't you hear?\""}],"relearn":"You can answer a curious child while protecting a friend's privacy.","persona":"Diya","source":"stigma reduction / privacy"},
  {"id":"df-1296","cat":"kindness-not-fear","type":"role-play","hook":"At a community meet, an uncle proposes seating people with HIV 'in a corner'.","setup":"Speak up respectfully. Say:","yourLine":[{"text":"\"No need for that, uncle, sitting together is completely safe.\"","best":true},{"text":"\"As you wish, uncle.\""}],"relearn":"You can respectfully refuse to corner people over a baseless fear.","persona":"Rohit","source":"stigma reduction / dignity"},
  {"id":"df-1297","cat":"kindness-not-fear","type":"strike-rewrite","hook":"\"You should warn the whole school if a student has HIV.\"","myth":{"un":"Everyone must be warned when a student has HIV.","re":"A person's HIV status is private; there is nothing to warn about.","why":"Everyday school contact is safe, so a 'warning' only shames."},"relearn":"HIV status is private and school contact is safe; no warning is needed.","persona":"any","source":"stigma reduction / privacy"},
  {"id":"df-1298","cat":"kindness-not-fear","type":"strike-rewrite","hook":"\"Being kind to someone with HIV puts you at risk.\"","myth":{"un":"Showing kindness to someone with HIV is risky for you.","re":"Including, hugging and helping someone with HIV is completely safe.","why":"HIV never spreads through everyday kindness or contact."},"relearn":"Kindness to someone with HIV carries no risk; everyday contact is safe.","persona":"Asha","source":"stigma reduction / inclusion"},
  {"id":"df-1299","cat":"kindness-not-fear","type":"strike-rewrite","hook":"\"A child with HIV should study at home, away from the others.\"","myth":{"un":"Children with HIV should be kept home, away from classmates.","re":"Children with HIV belong in school and can do everything others do.","why":"Sitting, playing and learning together cannot spread HIV."},"relearn":"Children with HIV belong in school; togetherness in class is safe.","persona":"Asha","source":"stigma reduction / inclusion"},
  {"id":"df-1300","cat":"kindness-not-fear","type":"strike-rewrite","hook":"\"If you find out someone has HIV, you should tell everyone to be safe.\"","myth":{"un":"Telling everyone about someone's HIV keeps people safe.","re":"Their health is private; gossip protects no one and only hurts.","why":"There is no everyday-contact risk, so there is nothing to protect against."},"relearn":"Gossiping a person's HIV status protects no one; their health is private.","persona":"any","source":"stigma reduction / privacy"},
  {"id":"df-1301","cat":"kindness-not-fear","type":"strike-rewrite","hook":"\"It's brave and risky to be friends with someone who has HIV.\"","myth":{"un":"Befriending someone with HIV is a brave, risky thing to do.","re":"It's just ordinary friendship; there is no risk to be brave about.","why":"Friendship and everyday contact never spread HIV."},"relearn":"Friendship with someone who has HIV is ordinary and safe, not risky.","persona":"Diya","source":"stigma reduction / friendship"},
  {"id":"df-1302","cat":"kindness-not-fear","type":"strike-rewrite","hook":"\"Someone with HIV should keep their own cup, plate and towel apart.\"","myth":{"un":"People with HIV must keep their cup, plate and towel separate.","re":"They can share cups, plates and towels; none of it spreads HIV.","why":"HIV does not pass through food, dishes or shared cloth."},"relearn":"Cups, plates and towels can be shared safely; no need to set them apart.","persona":"Asha","source":"stigma reduction / inclusion"},
  {"id":"df-1303","cat":"kindness-not-fear","type":"reflect","hook":"Lensy: a classmate just told you, only you, that he's living with HIV. How does that feel?","prompt":"What comes up for you?","options":["He really trusts me","I'll keep it to myself","I'll just be his friend"],"affirm":"Holding a friend's secret with care is one of the kindest things you can do.","relearn":"A friend's private health is theirs to share; holding it with care is kindness.","persona":"any","source":"stigma reduction / privacy"},
  {"id":"df-1304","cat":"kindness-not-fear","type":"reflect","hook":"Lensy: you noticed yourself feel a flicker of worry, then chose to sit with her anyway. Sit with that.","prompt":"What do you notice?","options":["Facts calmed me","I'm glad I sat down","Worry can pass"],"affirm":"Feeling unsure and then choosing kindness is exactly how courage grows.","relearn":"It's okay to feel unsure; letting facts guide you back to kindness is brave.","persona":"any","source":"stigma reduction / self"},
  {"id":"df-1305","cat":"kindness-not-fear","type":"reflect","hook":"Lensy: imagine the new boy walks in, and the room goes quiet. What would a real defender do?","prompt":"Picture your move.","options":["Smile and wave him over","Make space beside me","Say hi first"],"affirm":"The bravest defenders use their warmth to make room for others.","relearn":"Being a defender means making space and warmth for someone left out.","persona":"any","source":"stigma reduction / values"},
  {"id":"df-1306","cat":"kindness-not-fear","type":"reflect","hook":"Lensy: someone you like repeats a scary HIV rumour. Part of you wants to agree. What now?","prompt":"Where do you land?","options":["I'll stick to the facts","I won't pass it on","Kindness over fear"],"affirm":"Choosing facts over a rumour, even with friends, takes real strength.","relearn":"You can choose facts over a rumour even when friends are pulling the other way.","persona":"Aarav","source":"stigma reduction / self"},
  {"id":"df-1307","cat":"kindness-not-fear","type":"reflect","hook":"Lensy: think of a person who once felt left out. What's one small thing that would've helped?","prompt":"What would it be?","options":["A friendly hello","Sitting beside them","Being asked to play"],"affirm":"The small, ordinary kindnesses are often the ones people remember most.","relearn":"Small, ordinary kindnesses, a hello, a seat, an invite, can mean the most.","persona":"any","source":"stigma reduction / empathy"},
  {"id":"df-1308","cat":"kindness-not-fear","type":"reflect","hook":"Lensy: a friend living with HIV is just a friend, with a song, a sport, a favourite snack. Picture them.","prompt":"What do you see?","options":["A whole person","Just my friend","More than an illness"],"affirm":"Seeing the whole person, not the illness, is the heart of kindness.","relearn":"A person living with HIV is a whole person, never just their illness.","persona":"any","source":"stigma reduction / dignity"},
  {"id":"df-1309","cat":"kindness-not-fear","type":"reflect","hook":"Lensy: an elder you love is afraid of someone's illness. How do you want to handle it?","prompt":"What feels right?","options":["Share a calm fact","Stay respectful","Be patient with them"],"affirm":"Meeting an elder's fear with calm respect is its own kind of courage.","relearn":"You can ease an elder's fear with a calm, respectful fact, gently and patiently.","persona":"Rohit","source":"stigma reduction / correct an elder"},
  {"id":"df-1310","cat":"kindness-not-fear","type":"reflect","hook":"Lensy: of everything you've learned here, what will you carry into how you treat people?","prompt":"Choose what stays with you.","options":["Include, don't exclude","Facts over fear","Protect dignity"],"affirm":"Carrying these into how you treat people is what makes a true defender.","relearn":"Include people, choose facts over fear, and protect everyone's dignity.","persona":"any","source":"consolidation"},
  {"id":"df-1311","cat":"kindness-not-fear","type":"match","hook":"Match each unkind move to the kinder thing you could do instead.","pairs":[{"left":"Whisper about her illness","right":"Keep her health private"},{"left":"Leave the seat empty","right":"Sit down beside him"},{"left":"Skip him for the team","right":"Pick him to play"},{"left":"Forward the rumour","right":"Ask the chat to stop"},{"left":"Stay silent at the teasing","right":"Speak up for him"}],"relearn":"For every unkind move there's a kinder one: include, protect, speak up.","persona":"any","source":"stigma reduction / behaviour"},
  {"id":"df-1312","cat":"kindness-not-fear","type":"match","hook":"Match the fear someone voices to the calm, true reassurance.","pairs":[{"left":"\"Can I catch it from a hug?\"","right":"\"No, hugging is safe.\""},{"left":"\"Is sharing food risky?\"","right":"\"No, food won't spread HIV.\""},{"left":"\"Will sitting together harm me?\"","right":"\"No, that's safe.\""},{"left":"\"Is he always sick?\"","right":"\"No, medicine keeps him well.\""},{"left":"\"Is it his fault?\"","right":"\"No, it's never a fault.\""}],"relearn":"Every common HIV fear has a calm, true answer: it's safe, never a fault.","persona":"Asha","source":"stigma reduction / reassure"},
  {"id":"df-1313","cat":"kindness-not-fear","type":"match","hook":"Match each kind act to what it protects for a friend with HIV.","pairs":[{"left":"Keeping their status quiet","right":"Their privacy"},{"left":"Saving their class notes","right":"Their learning"},{"left":"Inviting them to play","right":"Their belonging"},{"left":"Defending them from teasing","right":"Their dignity"},{"left":"Sitting and eating together","right":"Their everyday normal"}],"relearn":"Kind acts protect a friend's privacy, learning, belonging, dignity and normal.","persona":"any","source":"stigma reduction / values"},
  {"id":"df-1314","cat":"kindness-not-fear","type":"match","hook":"Match the person's worry to the kind upstander move.","pairs":[{"left":"A child shut out of games","right":"Wave them into the team"},{"left":"A guest eating alone","right":"Sit and share the meal"},{"left":"A name being chanted","right":"Tell them to stop"},{"left":"A photo being forwarded","right":"Break the chain"},{"left":"An elder who's afraid","right":"Offer a calm fact"}],"relearn":"The upstander move fits the moment: include, sit, stop it, break it, explain.","persona":"any","source":"stigma reduction / upstander"},
  {"id":"df-1315","cat":"kindness-not-fear","type":"match","hook":"Match each myth a friend might say to the kind, true reply.","pairs":[{"left":"\"He's cursed.\"","right":"\"It's an infection, not a curse.\""},{"left":"\"She's dangerous.\"","right":"\"She's safe to be around.\""},{"left":"\"Keep him apart.\"","right":"\"He belongs with us.\""},{"left":"\"It's her fault.\"","right":"\"It's nobody's fault.\""},{"left":"\"Warn everyone.\"","right":"\"Her health is private.\""}],"relearn":"Each stigma myth has a kind, true reply that includes instead of excludes.","persona":"Aarav","source":"stigma reduction / voice"},
  {"id":"df-1316","cat":"kindness-not-fear","type":"match","hook":"Match each friend's small worry to a warm thing you could say back.","pairs":[{"left":"\"Will it be weird?\"","right":"\"It'll be totally normal.\""},{"left":"\"Should I tell people?\"","right":"\"Only if you want to.\""},{"left":"\"Will you still hang out?\"","right":"\"Same as always.\""},{"left":"\"Am I a burden now?\"","right":"\"Never, you're my friend.\""},{"left":"\"Will they stare?\"","right":"\"I've got your back.\""}],"relearn":"A worried friend just needs warm, steady words: normal, your choice, always.","persona":"Diya","source":"stigma reduction / reassure"},
  {"id":"df-1317","cat":"kindness-not-fear","type":"match","hook":"Match the setting to the kind, safe thing to do there.","pairs":[{"left":"At the lunch table","right":"Share the same plate"},{"left":"On the playground","right":"Pick him for the game"},{"left":"In the group chat","right":"Refuse to forward gossip"},{"left":"At a family function","right":"Greet with a warm hug"},{"left":"In the classroom","right":"Sit right beside her"}],"relearn":"Wherever you are, the kind, safe move is to include and share normally.","persona":"any","source":"stigma reduction / inclusion"},
  {"id":"df-1318","cat":"kindness-not-fear","type":"match","hook":"Match what a true defender values to how it shows up in action.","pairs":[{"left":"Inclusion","right":"Saving a seat for everyone"},{"left":"Privacy","right":"Keeping health news quiet"},{"left":"Dignity","right":"Standing up to teasing"},{"left":"Facts","right":"Calmly correcting a myth"},{"left":"Friendship","right":"Treating them the same"}],"relearn":"A defender's values, inclusion, privacy, dignity, facts, become everyday acts.","persona":"any","source":"consolidation"},
  {"id":"df-1319","cat":"kindness-not-fear","type":"sort","hook":"Sort each move into Kind and includes or Unkind and excludes.","items":[{"id":"a","text":"Save him a seat at lunch"},{"id":"b","text":"Whisper that she has HIV"},{"id":"c","text":"Share your water bottle"},{"id":"d","text":"Leave him off every team"},{"id":"e","text":"Greet her with a hug"},{"id":"f","text":"Spread a scary rumour"}],"bins":[{"id":"kind","label":"Kind, includes","valence":"pos"},{"id":"unkind","label":"Unkind, excludes","valence":"neg"}],"key":{"a":"kind","b":"unkind","c":"kind","d":"unkind","e":"kind","f":"unkind"},"relearn":"Saving a seat, sharing, hugging include; whispering and excluding hurt.","persona":"any","source":"stigma reduction / behaviour"},
  {"id":"df-1320","cat":"kindness-not-fear","type":"sort","hook":"Sort each thing into Keep private or Okay to share aloud.","items":[{"id":"a","text":"A friend's HIV status"},{"id":"b","text":"Your favourite cricket team"},{"id":"c","text":"Which medicine a classmate takes"},{"id":"d","text":"The film you watched"},{"id":"e","text":"A neighbour's clinic visits"},{"id":"f","text":"Your weekend plans"}],"bins":[{"id":"private","label":"Keep private","valence":"uhoh"},{"id":"open","label":"Okay to share","valence":"pos"}],"key":{"a":"private","b":"open","c":"private","d":"open","e":"private","f":"open"},"relearn":"Someone's health, medicine and clinic visits are private; everyday fun is fine to share.","persona":"any","source":"stigma reduction / privacy"},
  {"id":"df-1321","cat":"kindness-not-fear","type":"sort","hook":"Sort each reply to a friend's fear into Calm and true or Fearful and false.","items":[{"id":"a","text":"\"Hugging him is safe.\""},{"id":"b","text":"\"Stay away, you'll catch it.\""},{"id":"c","text":"\"Sharing food is fine.\""},{"id":"d","text":"\"Don't touch anything she touched.\""},{"id":"e","text":"\"He's well, his medicine works.\""},{"id":"f","text":"\"She's dangerous to be near.\""}],"bins":[{"id":"calm","label":"Calm, true","valence":"pos"},{"id":"fearful","label":"Fearful, false","valence":"neg"}],"key":{"a":"calm","b":"fearful","c":"calm","d":"fearful","e":"calm","f":"fearful"},"relearn":"Hugging, sharing food and being near are safe; fear-talk is false.","persona":"Asha","source":"stigma reduction / reassure"},
  {"id":"df-1322","cat":"kindness-not-fear","type":"sort","hook":"Sort each line into Speak up or Stay out of it, for an upstander.","items":[{"id":"a","text":"\"Stop teasing him.\""},{"id":"b","text":"Laugh along quietly"},{"id":"c","text":"\"Come sit with us.\""},{"id":"d","text":"Look away from it"},{"id":"e","text":"\"That rumour isn't true.\""},{"id":"f","text":"Forward it anyway"}],"bins":[{"id":"speak","label":"Speak up","valence":"tell"},{"id":"silent","label":"Stay out of it","valence":"neg"}],"key":{"a":"speak","b":"silent","c":"speak","d":"silent","e":"speak","f":"silent"},"relearn":"An upstander speaks up to include and correct, instead of looking away.","persona":"any","source":"stigma reduction / upstander"},
  {"id":"df-1323","cat":"kindness-not-fear","type":"sort","hook":"Sort each act into Protects dignity or Wounds dignity.","items":[{"id":"a","text":"Treating him the same as always"},{"id":"b","text":"Calling her 'the sick one'"},{"id":"c","text":"Inviting him to your party"},{"id":"d","text":"Pointing her out to strangers"},{"id":"e","text":"Defending him from a mean joke"},{"id":"f","text":"Mocking his medicine"}],"bins":[{"id":"protect","label":"Protects dignity","valence":"pos"},{"id":"wound","label":"Wounds dignity","valence":"neg"}],"key":{"a":"protect","b":"wound","c":"protect","d":"wound","e":"protect","f":"wound"},"relearn":"Sameness, invites and defence protect dignity; labels and mockery wound it.","persona":"any","source":"stigma reduction / dignity"},
  {"id":"df-1324","cat":"kindness-not-fear","type":"sort","hook":"Sort each idea into Kindness fact or Stigma myth.","items":[{"id":"a","text":"People with HIV belong in school"},{"id":"b","text":"HIV is a punishment for being bad"},{"id":"c","text":"Everyday contact is safe"},{"id":"d","text":"You should warn everyone"},{"id":"e","text":"A person is more than their virus"},{"id":"f","text":"Keep them apart from others"}],"bins":[{"id":"fact","label":"Kindness fact","valence":"pos"},{"id":"myth","label":"Stigma myth","valence":"neg"}],"key":{"a":"fact","b":"myth","c":"fact","d":"myth","e":"fact","f":"myth"},"relearn":"Belonging, safe contact and full personhood are facts; punishment and apartness are myths.","persona":"any","source":"stigma reduction / facts"},
  {"id":"df-1325","cat":"kindness-not-fear","type":"sort","hook":"Sort each thing you might say to a new friend with HIV into Warm welcome or Cold distance.","items":[{"id":"a","text":"\"Come join us at lunch!\""},{"id":"b","text":"\"Sit over there, please.\""},{"id":"c","text":"\"You're on my team.\""},{"id":"d","text":"\"Use your own things.\""},{"id":"e","text":"\"We're glad you're here.\""},{"id":"f","text":"\"Keep your distance.\""}],"bins":[{"id":"warm","label":"Warm welcome","valence":"pos"},{"id":"cold","label":"Cold distance","valence":"neg"}],"key":{"a":"warm","b":"cold","c":"warm","d":"cold","e":"warm","f":"cold"},"relearn":"Inviting, including and gladness welcome; distance-talk shuts a friend out.","persona":"Diya","source":"stigma reduction / inclusion"},
  {"id":"df-1326","cat":"kindness-not-fear","type":"sort","hook":"Sort each contact with a friend who has HIV into Safe, go ahead or Just a myth to drop.","items":[{"id":"a","text":"Sharing a tiffin"},{"id":"b","text":"Catching HIV from a hug"},{"id":"c","text":"Holding hands in a game"},{"id":"d","text":"Catching it from a toilet seat"},{"id":"e","text":"Drinking from the same tap"},{"id":"f","text":"Catching it from a mosquito"}],"bins":[{"id":"safe","label":"Safe, go ahead","valence":"pos"},{"id":"mythbin","label":"Just a myth","valence":"neg"}],"key":{"a":"safe","b":"mythbin","c":"safe","d":"mythbin","e":"safe","f":"mythbin"},"relearn":"Tiffins, hands and taps are safe; hugs, toilet seats and mosquitoes are myths.","persona":"any","source":"stigma reduction / facts"},
  {"id":"df-1327","cat":"kindness-not-fear","type":"spot","hook":"Spot the two unkind moves among these kind ones at lunch.","scene":[{"id":"a","text":"You wave a lonely classmate over to your table","trick":false},{"id":"b","text":"You whisper that he 'has HIV, be careful'","trick":true},{"id":"c","text":"You pass him the shared rice, no fuss","trick":false},{"id":"d","text":"You swap your plate so it never touched his","trick":true},{"id":"e","text":"You ask about his favourite cricketer","trick":false}],"why":"Whispering and swapping the plate spread fear; the rest include.","persona":"any","source":"stigma reduction / behaviour","relearn":"Whispering and avoiding a plate exclude; waving over and sharing include."},
  {"id":"df-1328","cat":"kindness-not-fear","type":"spot","hook":"Spot the two fear-driven actions among these calm ones in the chat.","scene":[{"id":"a","text":"You reply that everyday contact is safe","trick":false},{"id":"b","text":"You forward the 'warning' photo of her","trick":true},{"id":"c","text":"You ask everyone to delete the photo","trick":false},{"id":"d","text":"You add, 'better avoid her, just in case'","trick":true},{"id":"e","text":"You message her privately to check in","trick":false}],"why":"Forwarding the photo and 'avoid her' spread stigma; the rest protect.","persona":"Aarav","source":"stigma reduction / privacy","relearn":"Forwarding and 'avoid her' spread stigma; calm replies protect her."},
  {"id":"df-1329","cat":"kindness-not-fear","type":"spot","hook":"Spot the two moves that hurt dignity among these respectful ones.","scene":[{"id":"a","text":"You greet the guest with a warm hug","trick":false},{"id":"b","text":"You point him out as 'the HIV one'","trick":true},{"id":"c","text":"You offer him the same sweets as all","trick":false},{"id":"d","text":"You wipe your hand after shaking his","trick":true},{"id":"e","text":"You introduce him by name and hobby","trick":false}],"why":"Labelling him and wiping your hand wound dignity; the rest honour it.","persona":"any","source":"stigma reduction / dignity","relearn":"Labelling and hand-wiping wound dignity; greeting and sharing honour it."},
  {"id":"df-1330","cat":"kindness-not-fear","type":"spot","hook":"Spot the two replies that miss the mark when a friend says she has HIV.","scene":[{"id":"a","text":"\"Thanks for trusting me, I've got you.\"","trick":false},{"id":"b","text":"\"Don't worry, I won't tell a soul.\"","trick":false},{"id":"c","text":"\"Should I let the teacher know?\"","trick":true},{"id":"d","text":"\"Nothing changes, still friends.\"","trick":false},{"id":"e","text":"\"Maybe sit further from me?\"","trick":true}],"why":"Telling the teacher and asking her to sit apart break trust; rest kind.","persona":"any","source":"stigma reduction / privacy","relearn":"Telling a teacher or sitting apart break trust; the kind replies stay close."},
  {"id":"df-1331","cat":"kindness-not-fear","type":"spot","hook":"Spot the two excluding moves among these including ones at team picks.","scene":[{"id":"a","text":"You call his name first for your side","trick":false},{"id":"b","text":"You 'forget' him because his uncle has HIV","trick":true},{"id":"c","text":"You cheer when he scores","trick":false},{"id":"d","text":"You tell him to 'just keep score'","trick":true},{"id":"e","text":"You high-five him at the break","trick":false}],"why":"Skipping and benching him exclude; picking and cheering include.","persona":"any","source":"stigma reduction / inclusion","relearn":"Skipping and benching exclude; picking, cheering and high-fives include."},
  {"id":"df-1332","cat":"kindness-not-fear","type":"spot","hook":"Spot the two fearful things an elder might say that you'd gently correct.","scene":[{"id":"a","text":"\"He's a sweet boy, invite him in.\"","trick":false},{"id":"b","text":"\"Don't eat from his plate.\"","trick":true},{"id":"c","text":"\"His medicine keeps him healthy.\"","trick":false},{"id":"d","text":"\"Keep the children away from him.\"","trick":true},{"id":"e","text":"\"Treat him like family.\"","trick":false}],"why":"Plate-fear and keeping children away are myths; the rest are kind.","persona":"Rohit","source":"stigma reduction / correct an elder","relearn":"Plate-fear and keeping children away are myths to correct; the rest are kind."},
  {"id":"df-1333","cat":"kindness-not-fear","type":"spot","hook":"Spot the two unkind moves among these welcoming ones for a new classmate.","scene":[{"id":"a","text":"You show her where the library is","trick":false},{"id":"b","text":"You tell others to 'watch out' for her","trick":true},{"id":"c","text":"You save her a seat in the front","trick":false},{"id":"d","text":"You won't share your textbook with her","trick":true},{"id":"e","text":"You ask her to join your study group","trick":false}],"why":"Warning others and refusing your book exclude her; the rest welcome.","persona":"Diya","source":"stigma reduction / inclusion","relearn":"Warning others and refusing your book exclude; the rest make her welcome."},
  {"id":"df-1334","cat":"kindness-not-fear","type":"spot","hook":"Spot the two myths a classmate repeats that you'd kindly bust.","scene":[{"id":"a","text":"\"You can't catch HIV from a hug.\"","trick":false},{"id":"b","text":"\"His pencil could give it to you.\"","trick":true},{"id":"c","text":"\"His medicine keeps the virus in check.\"","trick":false},{"id":"d","text":"\"Mosquitoes near him pass it on.\"","trick":true},{"id":"e","text":"\"He's safe to sit and play with.\"","trick":false}],"why":"Pencils and mosquitoes never spread HIV; those two are myths.","persona":"Aarav","source":"stigma reduction / facts","relearn":"Pencils and mosquitoes are myths; hugs, medicine and play facts are true."},
  {"id":"df-1350","type":"strike-rewrite","persona":"Asha","source":"transmission / stigma (CDC)","hook":"\"Drinking from the same water cooler at school spreads HIV.\"","myth":{"un":"The shared school water cooler can pass on HIV.","re":"A shared water cooler or tap never spreads HIV.","why":"HIV isn't in water you drink."},"relearn":"Sharing a school water cooler is safe.","cat":"spreads-or-not"},
  {"id":"df-1351","type":"strike-rewrite","persona":"any","source":"transmission / stigma (CDC)","hook":"\"Swimming in the same pool or pond as someone with HIV is risky.\"","myth":{"un":"Sharing a pool or pond with someone with HIV can infect you.","re":"Swimming together is completely safe.","why":"Water and swimming never carry HIV."},"relearn":"Swimming with someone with HIV is safe.","cat":"spreads-or-not"},
  {"id":"df-1352","type":"strike-rewrite","persona":"Aarav","source":"transmission / stigma (CDC)","hook":"\"You can catch HIV from a mate's sweat after kabaddi.\"","myth":{"un":"Touching someone's sweat can give you HIV.","re":"Sweat does not spread HIV.","why":"HIV isn't carried in sweat."},"relearn":"Sweat never spreads HIV.","cat":"spreads-or-not"},
  {"id":"df-1353","type":"strike-rewrite","persona":"Diya","source":"transmission / stigma (CDC)","hook":"\"Sharing a school bench or desk with a kid with HIV is risky.\"","myth":{"un":"Sitting on the same bench spreads HIV.","re":"Sharing a bench or desk is completely safe.","why":"Furniture and surfaces don't carry HIV."},"relearn":"Sharing a bench or desk is safe.","cat":"spreads-or-not"},
  {"id":"df-1354","type":"strike-rewrite","persona":"any","source":"transmission / stigma (CDC)","hook":"\"You can get HIV from someone's tears.\"","myth":{"un":"Crying near someone, or their tears, can pass on HIV.","re":"Tears do not spread HIV.","why":"HIV isn't carried in tears."},"relearn":"Tears never spread HIV.","cat":"spreads-or-not"},
  {"id":"df-1355","type":"strike-rewrite","persona":"Asha","source":"transmission / stigma (CDC)","hook":"\"Sharing a comb or hairclip spreads HIV.\"","myth":{"un":"Borrowing a friend's comb or hairclip can give you HIV.","re":"Combs and hairclips never spread HIV.","why":"Hair and skin contact don't carry it."},"relearn":"Sharing a comb is safe.","cat":"spreads-or-not"},
  {"id":"df-1356","type":"strike-rewrite","persona":"any","source":"transmission / stigma (CDC)","hook":"\"A handshake or a high-five can pass on HIV.\"","myth":{"un":"Shaking hands or a high-five spreads HIV.","re":"Handshakes and high-fives are completely safe.","why":"Skin touch never carries HIV."},"relearn":"Handshakes and high-fives are safe.","cat":"spreads-or-not"},
  {"id":"df-1357","type":"strike-rewrite","persona":"Asha","source":"transmission / stigma (CDC)","hook":"\"You can get HIV from someone coughing on you.\"","myth":{"un":"A cough or sneeze from someone with HIV can infect you.","re":"Coughs and sneezes never spread HIV.","why":"HIV is not airborne like a cold."},"relearn":"Coughs and sneezes don't spread HIV.","cat":"spreads-or-not"},
  {"id":"df-1358","type":"strike-rewrite","persona":"Aarav","source":"transmission / stigma (CDC)","hook":"\"Sharing a phone or earphones spreads HIV.\"","myth":{"un":"Lending your phone or earphones can pass on HIV.","re":"Phones and earphones never spread HIV.","why":"Everyday objects don't carry it."},"relearn":"Sharing a phone is safe.","cat":"spreads-or-not"},
  {"id":"df-1359","type":"strike-rewrite","persona":"Diya","source":"transmission / stigma (CDC)","hook":"\"You can get HIV by sharing a school tiffin or roti.\"","myth":{"un":"Sharing a tiffin or tearing the same roti spreads HIV.","re":"Sharing a tiffin or roti is completely safe.","why":"HIV isn't passed through food."},"relearn":"Sharing a tiffin is safe.","cat":"spreads-or-not"},
  {"id":"df-1360","type":"strike-rewrite","persona":"any","source":"transmission / stigma (CDC)","hook":"\"Touching a doorknob after someone with HIV is dangerous.\"","myth":{"un":"A doorknob touched by someone with HIV can infect you.","re":"Doorknobs and surfaces never spread HIV.","why":"HIV can't live and spread on surfaces."},"relearn":"Touching shared surfaces is safe.","cat":"spreads-or-not"},
  {"id":"df-1361","type":"strike-rewrite","persona":"Asha","source":"transmission / stigma (CDC)","hook":"\"Sharing a temple or shared cup of prasad water spreads HIV.\"","myth":{"un":"Sipping shared prasad water can give you HIV.","re":"Shared prasad or water never spreads HIV.","why":"HIV isn't passed by what you drink."},"relearn":"Sharing prasad water is safe.","cat":"spreads-or-not"},
  {"id":"df-1362","type":"strike-rewrite","persona":"any","source":"transmission / stigma (CDC)","hook":"\"You can catch HIV from a wet patch on a shared towel.\"","myth":{"un":"Drying off with a shared towel spreads HIV.","re":"Sharing a towel does not spread HIV.","why":"HIV isn't carried on cloth or skin."},"relearn":"Sharing a towel is safe.","cat":"spreads-or-not"},
  {"id":"df-1363","type":"strike-rewrite","persona":"Aarav","source":"transmission / stigma (CDC)","hook":"\"Letting a friend with HIV pet your dog passes it on.\"","myth":{"un":"A pet touched by someone with HIV can carry HIV to you.","re":"Pets never carry or spread HIV.","why":"Animals can't pass HIV between people."},"relearn":"Pets don't spread HIV.","cat":"spreads-or-not"},
  {"id":"df-1364","type":"strike-rewrite","persona":"any","source":"transmission / stigma (CDC)","hook":"\"You can get HIV from spit when someone talks close to you.\"","myth":{"un":"Tiny spit drops from talking spread HIV.","re":"Saliva and talking never spread HIV.","why":"HIV isn't carried in saliva."},"relearn":"Saliva and talking don't spread HIV.","cat":"spreads-or-not"},
  {"id":"df-1365","type":"strike-rewrite","persona":"Aarav","source":"transmission / stigma (CDC)","hook":"\"Sharing a cricket bat or ball spreads HIV.\"","myth":{"un":"Holding the same bat or ball can give you HIV.","re":"Sharing sports gear is completely safe.","why":"Objects and skin touch don't carry it."},"relearn":"Sharing a bat or ball is safe.","cat":"spreads-or-not"},
  {"id":"df-1366","type":"strike-rewrite","persona":"Asha","source":"transmission / stigma (CDC)","hook":"\"You can catch HIV from a friend's water bottle sip.\"","myth":{"un":"Sipping from a friend's bottle spreads HIV.","re":"Sharing a water bottle never spreads HIV.","why":"HIV isn't passed through drinking."},"relearn":"Sharing a water bottle is safe.","cat":"spreads-or-not"},
  {"id":"df-1367","type":"strike-rewrite","persona":"any","source":"transmission / stigma (CDC)","hook":"\"Sleeping in the same room as someone with HIV is risky.\"","myth":{"un":"Sharing a room or charpai spreads HIV.","re":"Sharing a room is completely safe.","why":"Being near someone never spreads HIV."},"relearn":"Sharing a room is safe.","cat":"spreads-or-not"},
  {"id":"df-1368","type":"strike-rewrite","persona":"any","source":"transmission / stigma (CDC)","hook":"\"You can get HIV from an insect that bites you both.\"","myth":{"un":"Any insect that bites two people can pass on HIV.","re":"Insects and bugs never spread HIV.","why":"The virus can't survive or pass in insects."},"relearn":"Insect bites don't spread HIV.","cat":"spreads-or-not"},
  {"id":"df-1369","type":"strike-rewrite","persona":"Diya","source":"transmission / stigma (CDC)","hook":"\"Hugging a relative with HIV at a wedding is risky.\"","myth":{"un":"A wedding hug with a relative with HIV can infect you.","re":"Hugging is completely safe; hug freely.","why":"HIV isn't in everyday touch."},"relearn":"Hugging a relative with HIV is safe.","cat":"spreads-or-not"},
  {"id":"df-1370","type":"strike-rewrite","persona":"Asha","source":"transmission / stigma (CDC)","hook":"\"You can catch HIV by sharing a steel thali at a langar.\"","myth":{"un":"Eating from shared thalis at a langar spreads HIV.","re":"Shared plates and thalis never spread HIV.","why":"HIV isn't passed through plates or food."},"relearn":"Sharing a thali is safe.","cat":"spreads-or-not"},
  {"id":"df-1371","type":"strike-rewrite","persona":"any","source":"transmission / stigma (CDC)","hook":"\"Walking barefoot where someone with HIV walked is risky.\"","myth":{"un":"Stepping where someone with HIV stepped can infect you.","re":"Floors and ground never spread HIV.","why":"HIV can't live or spread on surfaces."},"relearn":"Shared floors and ground are safe.","cat":"spreads-or-not"},
  {"id":"df-1372","type":"sort","persona":"Asha","source":"transmission","hook":"Sort each into Safe or a Real (blood) risk.","items":[{"id":"a","text":"Sharing a tiffin"},{"id":"b","text":"A reused, unclean needle"},{"id":"c","text":"A hug"},{"id":"d","text":"Sharing a razor (blood)"},{"id":"e","text":"Holding hands"},{"id":"f","text":"A shared comb"}],"bins":[{"id":"safe","label":"Safe","valence":"pos"},{"id":"risk","label":"Real blood risk","valence":"neg"}],"key":{"a":"safe","b":"risk","c":"safe","d":"risk","e":"safe","f":"safe"},"relearn":"Hugs, food and combs are safe; only blood-contact items carry a real risk.","cat":"spreads-or-not"},
  {"id":"df-1373","type":"sort","persona":"any","source":"transmission","hook":"Sort: spreads HIV, or does not?","items":[{"id":"a","text":"A mosquito bite"},{"id":"b","text":"Shared, unclean needles"},{"id":"c","text":"A toilet seat"},{"id":"d","text":"Parent to baby"},{"id":"e","text":"A sneeze"},{"id":"f","text":"A shared cup"}],"bins":[{"id":"yes","label":"Can spread it","valence":"neg"},{"id":"no","label":"Cannot spread it","valence":"pos"}],"key":{"a":"no","b":"yes","c":"no","d":"yes","e":"no","f":"no"},"relearn":"Only shared needles and parent-to-baby can spread HIV; the rest cannot.","cat":"spreads-or-not"},
  {"id":"df-1374","type":"sort","persona":"Aarav","source":"transmission","hook":"Sort each saying into Fact or Myth.","items":[{"id":"a","text":"\"HIV spreads through toilet seats\""},{"id":"b","text":"\"HIV is not airborne\""},{"id":"c","text":"\"Mosquitoes spread HIV\""},{"id":"d","text":"\"Hugs are safe\""},{"id":"e","text":"\"Sharing food spreads HIV\""},{"id":"f","text":"\"You can't tell by looking\""}],"bins":[{"id":"fact","label":"Fact","valence":"pos"},{"id":"myth","label":"Myth","valence":"neg"}],"key":{"a":"myth","b":"fact","c":"myth","d":"fact","e":"myth","f":"fact"},"relearn":"Toilet seats, mosquitoes and food are myths; the safe-contact facts are true.","cat":"spreads-or-not"},
  {"id":"df-1375","type":"sort","persona":"Diya","source":"transmission","hook":"Sort: everyday contact (safe), or a real risk?","items":[{"id":"a","text":"Sharing a school bus seat"},{"id":"b","text":"Playing carrom together"},{"id":"c","text":"A reused unclean needle"},{"id":"d","text":"Sharing earphones"},{"id":"e","text":"Eating from the same packet"},{"id":"f","text":"A high-five"}],"bins":[{"id":"safe","label":"Safe everyday contact","valence":"pos"},{"id":"risk","label":"A real risk","valence":"neg"}],"key":{"a":"safe","b":"safe","c":"risk","d":"safe","e":"safe","f":"safe"},"relearn":"Bus seats, games, snacks and high-fives are safe; only unclean needles are a risk.","cat":"spreads-or-not"},
  {"id":"df-1376","type":"sort","persona":"any","source":"transmission","hook":"Sort: a way HIV really spreads, or a fear-myth?","items":[{"id":"a","text":"Holding hands"},{"id":"b","text":"Shared needles"},{"id":"c","text":"A swimming pool"},{"id":"d","text":"Coughing"},{"id":"e","text":"Parent to baby"},{"id":"f","text":"Sharing a towel"}],"bins":[{"id":"real","label":"Really spreads it","valence":"neg"},{"id":"myth","label":"A fear-myth","valence":"pos"}],"key":{"a":"myth","b":"real","c":"myth","d":"myth","e":"real","f":"myth"},"relearn":"Only shared needles and parent-to-baby really spread HIV; the rest are myths.","cat":"spreads-or-not"},
  {"id":"df-1377","type":"sort","persona":"Asha","source":"transmission","hook":"Sort these school moments: Safe, or actually risky?","items":[{"id":"a","text":"Sharing a pencil"},{"id":"b","text":"Sharing a water cooler"},{"id":"c","text":"Sitting at the same desk"},{"id":"d","text":"A reused unclean needle"},{"id":"e","text":"Sharing a textbook"},{"id":"f","text":"Drinking from the same tap"}],"bins":[{"id":"safe","label":"Safe","valence":"pos"},{"id":"risk","label":"Actually risky","valence":"neg"}],"key":{"a":"safe","b":"safe","c":"safe","d":"risk","e":"safe","f":"safe"},"relearn":"Pencils, water, desks and books are all safe; only unclean needles carry a risk.","cat":"spreads-or-not"},
  {"id":"df-1378","type":"sort","persona":"any","source":"transmission","hook":"Sort: this carries HIV, or it does not.","items":[{"id":"a","text":"Saliva / spit"},{"id":"b","text":"Sweat"},{"id":"c","text":"Blood"},{"id":"d","text":"Tears"},{"id":"e","text":"A mosquito"},{"id":"f","text":"A hug"}],"bins":[{"id":"carries","label":"Can carry HIV","valence":"neg"},{"id":"not","label":"Cannot","valence":"pos"}],"key":{"a":"not","b":"not","c":"carries","d":"not","e":"not","f":"not"},"relearn":"Only blood can carry HIV; saliva, sweat, tears, insects and hugs cannot.","cat":"spreads-or-not"},
  {"id":"df-1379","type":"sort","persona":"Diya","source":"transmission","hook":"Sort: hug freely, or this needs care?","items":[{"id":"a","text":"Hugging a friend with HIV"},{"id":"b","text":"Sharing food with them"},{"id":"c","text":"Sharing a razor (blood)"},{"id":"d","text":"Sitting beside them"},{"id":"e","text":"Sharing a needle"},{"id":"f","text":"Holding their hand"}],"bins":[{"id":"free","label":"Hug freely / safe","valence":"pos"},{"id":"care","label":"Needs care (blood)","valence":"neg"}],"key":{"a":"free","b":"free","c":"care","d":"free","e":"care","f":"free"},"relearn":"Hugs, food, sitting and hands are free; only blood-contact items need care.","cat":"spreads-or-not"},
  {"id":"df-1380","type":"sort","persona":"Asha","source":"transmission","hook":"Sort: a kind, true response, or a fearful myth?","items":[{"id":"a","text":"\"Come sit with us\""},{"id":"b","text":"\"Don't touch her things\""},{"id":"c","text":"\"Everyday contact is safe\""},{"id":"d","text":"\"Keep him away\""},{"id":"e","text":"\"You can still be friends\""},{"id":"f","text":"\"It spreads from a hug\""}],"bins":[{"id":"kind","label":"Kind & true","valence":"tell"},{"id":"fear","label":"A fearful myth","valence":"neg"}],"key":{"a":"kind","b":"fear","c":"kind","d":"fear","e":"kind","f":"fear"},"relearn":"Including and reassuring are kind and true; the exclusion lines are fear-myths.","cat":"spreads-or-not"},
  {"id":"df-1381","type":"spot","persona":"Asha","source":"transmission / media literacy","hook":"A 'how HIV spreads' poster. Spot the 2 false (myth) entries.","scene":[{"id":"a","text":"\"Shared, unclean needles\"","trick":false},{"id":"b","text":"\"Sharing a meal\" listed as a way","trick":true},{"id":"c","text":"\"Parent to baby\"","trick":false},{"id":"d","text":"\"A mosquito bite\" listed as a way","trick":true},{"id":"e","text":"\"Blood\"","trick":false}],"why":"Meals and mosquitoes never spread HIV; only needles, parent-to-baby and blood are real.","relearn":"Spot the myths on a poster: meals and mosquitoes never spread HIV.","cat":"spreads-or-not"},
  {"id":"df-1382","type":"spot","persona":"Diya","source":"transmission / media literacy","hook":"A school notice about a kid with HIV. Spot the 2 false claims.","scene":[{"id":"a","text":"\"Everyday contact is safe\"","trick":false},{"id":"b","text":"\"Keep their cup separate\"","trick":true},{"id":"c","text":"\"They can play with everyone\"","trick":false},{"id":"d","text":"\"Don't sit next to them\"","trick":true},{"id":"e","text":"\"Treatment keeps them healthy\"","trick":false}],"why":"Separate cups and 'don't sit' are myths; sitting, cups and play are all safe.","relearn":"Spot the false lines: cups and sitting together are completely safe.","cat":"spreads-or-not"},
  {"id":"df-1383","type":"spot","persona":"Aarav","source":"transmission / media literacy","hook":"A forwarded message about HIV. Spot the 2 lies hiding in it.","scene":[{"id":"a","text":"\"You can't catch it from a hug\"","trick":false},{"id":"b","text":"\"Sweat can spread it\"","trick":true},{"id":"c","text":"\"It isn't airborne\"","trick":false},{"id":"d","text":"\"Toilet seats pass it on\"","trick":true},{"id":"e","text":"\"Mosquitoes don't spread it\"","trick":false}],"why":"Sweat and toilet seats are lies; hugs, air and mosquitoes are all safe facts.","relearn":"Spot the lies in a forward: sweat and toilet seats never spread HIV.","cat":"spreads-or-not"},
  {"id":"df-1384","type":"spot","persona":"any","source":"transmission / media literacy","hook":"A 'safe or not' chart for a friend with HIV. Spot the 2 wrong entries.","scene":[{"id":"a","text":"\"Sharing food: safe\"","trick":false},{"id":"b","text":"\"Hugging: risky\"","trick":true},{"id":"c","text":"\"Holding hands: safe\"","trick":false},{"id":"d","text":"\"Sharing a bench: risky\"","trick":true},{"id":"e","text":"\"Playing together: safe\"","trick":false}],"why":"Hugging and sharing a bench are safe, so marking them risky is wrong.","relearn":"Spot the wrong labels: hugging and sharing a bench are both safe.","cat":"spreads-or-not"},
  {"id":"df-1385","type":"branch","persona":"Diya","source":"transmission / stigma action","hook":"Kids won't drink from the cooler after a boy with HIV used it.","options":[{"text":"Drink from it and say \"water doesn't spread HIV\"","consequence":"You show the cooler is safe and ease the fear.","outcome":"informed","best":true},{"text":"Avoid the cooler too, just in case","consequence":"Water never spreads HIV; the worry is a myth."}],"debrief":"A shared cooler is safe; showing it calms a whole group's fear.","relearn":"Shared water never spreads HIV; drink freely.","cat":"spreads-or-not"},
  {"id":"df-1386","type":"branch","persona":"Rohit","source":"transmission / stigma action","hook":"At a party, an aunty tells you not to eat the cake a man with HIV cut.","options":[{"text":"Eat a slice and gently say \"food doesn't spread HIV\"","consequence":"You correct the myth without shaming anyone.","outcome":"informed","best":true},{"text":"Quietly skip the cake to avoid an argument","consequence":"Food never spreads HIV; the fear isn't true."}],"debrief":"Sharing food and cake is safe; a calm fact eases a relative's worry.","relearn":"HIV never spreads through food or cake.","cat":"spreads-or-not"},
  {"id":"df-1387","type":"branch","persona":"Aarav","source":"transmission / stigma action","hook":"A teammate won't share the kabaddi mat with a player who has HIV.","options":[{"text":"Say \"sweat and play don't spread HIV. Let's play\"","consequence":"The team relaxes and the game goes on.","outcome":"informed","best":true},{"text":"Suggest the player sit out to keep peace","consequence":"Sweat and play are safe; benching them is unfair and unneeded."}],"debrief":"Sweat and play never spread HIV; everyone can share the mat.","relearn":"Sweat and play are safe; share the mat.","cat":"spreads-or-not"},
  {"id":"df-1388","type":"branch","persona":"any","source":"transmission / stigma action","hook":"Someone says \"don't use that toilet, a girl with HIV used it\".","options":[{"text":"Say \"toilet seats don't spread HIV, it's fine\"","consequence":"You stop a myth from spreading further.","outcome":"informed","best":true},{"text":"Wait for another toilet to be safe","consequence":"Toilet seats never spread HIV; the fear is a myth."}],"debrief":"Toilet seats are safe; correcting the myth protects someone from cruelty.","relearn":"Toilet seats never spread HIV.","cat":"spreads-or-not"},
  {"id":"df-1389","type":"branch","persona":"Aarav","source":"transmission / stigma action","hook":"A friend deletes a classmate's number after hearing he has HIV.","options":[{"text":"Say \"texting and being mates can't give you HIV\"","consequence":"Your friend keeps the friendship instead of fearing it.","outcome":"informed","best":true},{"text":"Agree it's safer to cut contact","consequence":"Phones and friendship never spread HIV; there's nothing to fear."}],"debrief":"Messaging and friendship are safe; there's no reason to drop a friend.","relearn":"Phones and friendship never spread HIV.","cat":"spreads-or-not"},
  {"id":"df-1390","type":"branch","persona":"any","source":"transmission / stigma action","hook":"At a langar, people leave a gap around a man known to have HIV.","options":[{"text":"Sit beside him and say \"sharing food here is safe\"","consequence":"Others see the gap was only fear, not fact.","outcome":"informed","best":true},{"text":"Leave the gap too so no one stares at you","consequence":"Sharing food and sitting together are completely safe."}],"debrief":"Sitting and sharing food are safe; one calm move can shrink a whole gap.","relearn":"Sharing food and sitting together never spread HIV.","cat":"spreads-or-not"},
  {"id":"df-1391","type":"reflect","persona":"any","source":"transmission","hook":"Lensy: think of all the things you do with a friend in a day.","prompt":"Which of these could spread HIV?","options":["None of them","They're all safe","Only blood would"],"affirm":"Almost everything friends do together is completely safe.","relearn":"Everyday things friends do never spread HIV.","cat":"spreads-or-not"},
  {"id":"df-1392","type":"reflect","persona":"Asha","source":"transmission","hook":"Lensy: people fear HIV from hugs, food, toilets, mosquitoes.","prompt":"How does it feel to know those are all safe?","options":["A relief","Less scary","Good to know"],"affirm":"Learning what's safe melts a lot of fear away.","relearn":"Hugs, food, toilets and mosquitoes are all safe.","cat":"spreads-or-not"},
  {"id":"df-1393","type":"reflect","persona":"Aarav","source":"transmission","hook":"Lensy: a forward said you can 'catch' HIV from sweat in PT class.","prompt":"What would you do with a claim like that?","options":["Check the facts","Not believe it","Ask a trusted adult"],"affirm":"Pausing to check a scary claim is exactly the smart move.","relearn":"Sweat doesn't spread HIV; check scary claims before believing.","cat":"spreads-or-not"},
  {"id":"df-1394","type":"reflect","persona":"any","source":"transmission","hook":"Lensy: only blood and parent-to-baby can pass HIV at your age.","prompt":"What does that tell you about everyday life?","options":["Most of it is safe","Little to fear","I can relax"],"affirm":"It means nearly everything in your day is safe.","relearn":"Only blood and parent-to-baby pass HIV; daily life is safe.","cat":"spreads-or-not"},
  {"id":"df-1395","type":"reflect","persona":"Diya","source":"transmission","hook":"Lensy: imagine a new classmate everyone whispers about over an illness.","prompt":"What kind of friend do you want to be?","options":["One who includes","One with facts","A kind one"],"affirm":"Choosing facts and kindness is the brave kind of friend.","relearn":"Everyday contact is safe; choose to include, not fear.","cat":"spreads-or-not"},
  {"id":"df-1396","type":"reflect","persona":"Diya","source":"transmission","hook":"Lensy: you've learned hugs, food and play with a friend with HIV are safe.","prompt":"What will you do with that next time?","options":["Hug freely","Share and play","Pass it on"],"affirm":"Knowing it's safe means you can just be a normal friend.","relearn":"Hugs, food and play are safe; be a normal friend.","cat":"spreads-or-not"},
  {"id":"df-1397","type":"role-play","persona":"Diya","source":"stigma reduction / voice","hook":"A kid yells \"don't touch her, she'll give you HIV!\" in the playground.","setup":"Step in. Say:","yourLine":[{"text":"\"You can't catch HIV from touching. Let's all play.\"","best":true},{"text":"Stay back so no one yells at you"}],"relearn":"A calm fact in the moment can stop a whole crowd's fear.","cat":"spreads-or-not"},
  {"id":"df-1398","type":"role-play","persona":"Rohit","source":"stigma reduction / voice","hook":"Your cousin won't sit on the same charpai as an uncle with HIV.","setup":"Set him at ease. Say:","yourLine":[{"text":"\"Sitting together can't pass HIV. Come, sit.\"","best":true},{"text":"Shrug and let him stand apart"}],"relearn":"Inviting someone to sit shows the fear was only a myth.","cat":"spreads-or-not"},
  {"id":"df-1399","type":"role-play","persona":"Aarav","source":"stigma reduction / voice","hook":"Friends refuse a snack a girl with HIV brought to share.","setup":"Reach for it. Say:","yourLine":[{"text":"\"Food can't carry HIV. Thanks, this looks great.\"","best":true},{"text":"Say you're not hungry to dodge it"}],"relearn":"Accepting her food warmly says louder than words that it's safe.","cat":"spreads-or-not"},
  {"id":"df-1400","type":"role-play","persona":"any","source":"stigma reduction / voice","hook":"A neighbour warns your mother not to let you swim with a boy who has HIV.","setup":"Speak up kindly. Say:","yourLine":[{"text":"\"Pool water can't spread HIV, so it's safe to swim.\"","best":true},{"text":"Quietly agree to stay out of the pool"}],"relearn":"A clear, calm fact reassures a worried adult.","cat":"spreads-or-not"},
  {"id":"df-1401","type":"role-play","persona":"Diya","source":"stigma reduction / voice","hook":"Classmates won't share the carrom board with a kid who has HIV.","setup":"Pull up a stool. Say:","yourLine":[{"text":"\"Playing games can't spread HIV. Deal me in.\"","best":true},{"text":"Find a different group to play with"}],"relearn":"Sitting down to play is the simplest way to break the gap.","cat":"spreads-or-not"},
  {"id":"df-1402","type":"role-play","persona":"Aarav","source":"stigma reduction / voice","hook":"Someone in the group says \"don't drink after him, he has HIV\".","setup":"Take a sip. Say:","yourLine":[{"text":"\"Sharing a bottle can't pass HIV. It's fine.\"","best":true},{"text":"Pour your own to avoid the fuss"}],"relearn":"Sharing the bottle shows the warning was a myth.","cat":"spreads-or-not"},
  {"id":"df-1403","type":"role-play","persona":"any","source":"stigma reduction / voice","hook":"At a wedding, relatives leave an empty chair beside an aunt with HIV.","setup":"Take the seat. Say:","yourLine":[{"text":"\"Sitting beside you is totally safe, Maasi.\"","best":true},{"text":"Pick a far chair so no one comments"}],"relearn":"Choosing the seat beside her quietly corrects the whole room.","cat":"spreads-or-not"},
  {"id":"df-1404","type":"role-play","persona":"Aarav","source":"stigma reduction / voice","hook":"A friend wants to throw away a pen a boy with HIV lent you.","setup":"Keep the pen. Say:","yourLine":[{"text":"\"A pen can't carry HIV. No need to bin it.\"","best":true},{"text":"Let her toss it to keep her happy"}],"relearn":"Keeping the everyday object shows the fear isn't real.","cat":"spreads-or-not"},
  {"id":"df-1405","type":"match","persona":"Asha","source":"transmission / stigma","hook":"Match each everyday act to why it's safe with a friend with HIV.","pairs":[{"left":"A hug","right":"Touch never carries the virus"},{"left":"Sharing food","right":"It isn't passed through eating"},{"left":"A mosquito bite","right":"Insects can't pass it on"},{"left":"A toilet seat","right":"Surfaces don't carry it"},{"left":"A cough","right":"HIV isn't airborne"}],"relearn":"Each everyday worry is safe for a clear reason: none of them carry HIV.","cat":"spreads-or-not"},
  {"id":"df-1406","type":"match","persona":"any","source":"transmission / stigma","hook":"Match the myth to the fact that busts it.","pairs":[{"left":"\"Hugs spread HIV\"","right":"Hug freely, it's safe"},{"left":"\"Food spreads HIV\"","right":"Plates and meals are safe"},{"left":"\"Mosquitoes spread HIV\"","right":"Insects spread nothing"},{"left":"\"Toilets spread HIV\"","right":"Seats and surfaces are safe"},{"left":"\"It's airborne\"","right":"Coughs don't pass it"}],"relearn":"Every common HIV myth has a calm, true fact that busts it.","cat":"spreads-or-not"},
  {"id":"df-1407","type":"match","persona":"Asha","source":"transmission / stigma","hook":"Match each fluid or contact to whether it can carry HIV.","pairs":[{"left":"Blood","right":"Can carry HIV"},{"left":"Saliva","right":"Cannot carry it"},{"left":"Sweat","right":"Never carries it"},{"left":"Tears","right":"Carry nothing"},{"left":"A handshake","right":"Totally safe"}],"relearn":"Only blood can carry HIV; saliva, sweat, tears and touch cannot.","cat":"spreads-or-not"},
  {"id":"df-1408","type":"match","persona":"Aarav","source":"transmission / stigma","hook":"Match each shared object to why it's safe to use.","pairs":[{"left":"A water bottle","right":"Drinking can't pass HIV"},{"left":"A pencil","right":"Objects don't carry it"},{"left":"Earphones","right":"Skin contact is safe"},{"left":"A cricket bat","right":"Holding it is harmless"},{"left":"A school bench","right":"Surfaces never carry it"}],"relearn":"Shared everyday objects never spread HIV; using them is safe.","cat":"spreads-or-not"},
  {"id":"df-1409","type":"match","persona":"Diya","source":"transmission / stigma","hook":"Match each scared question to its reassuring answer.","pairs":[{"left":"\"From a hug?\"","right":"No, hug freely"},{"left":"\"From the pool?\"","right":"No, swim together"},{"left":"\"From his spoon?\"","right":"No, share away"},{"left":"\"From a mosquito?\"","right":"No, bites are safe"},{"left":"\"From sitting close?\"","right":"No, sit together"}],"relearn":"To every everyday 'what if' the answer is the same: it's safe.","cat":"spreads-or-not"},
  {"id":"df-1410","type":"match","persona":"Diya","source":"transmission / stigma","hook":"Match the kind action to the fear it gently corrects.","pairs":[{"left":"Sit beside them","right":"Fear of being near"},{"left":"Share your lunch","right":"Fear of food"},{"left":"Hold their hand","right":"Fear of touch"},{"left":"Drink after them","right":"Fear of a shared cup"},{"left":"Play together","right":"Fear of games"}],"relearn":"Each small kind act answers a fear with a calm, lived-out fact.","cat":"spreads-or-not"},
  {"id":"df-1411","type":"match","persona":"any","source":"transmission / stigma","hook":"Match each way HIV can or cannot spread to the right label.","pairs":[{"left":"Shared unclean needle","right":"A real route"},{"left":"Parent to baby","right":"A real route too"},{"left":"A friendly hug","right":"Not a route"},{"left":"Sharing a thali","right":"Also not a route"},{"left":"An insect bite","right":"Never a route"}],"relearn":"Only needles and parent-to-baby are real routes; everyday contact is not.","cat":"spreads-or-not"},
  {"id":"df-1412","type":"match","persona":"Aarav","source":"transmission / stigma","hook":"Match the rumour to what you'd calmly say back.","pairs":[{"left":"\"Don't share his bottle\"","right":"\"Water can't pass it\""},{"left":"\"Don't sit by her\"","right":"\"Sitting is safe\""},{"left":"\"Don't eat that\"","right":"\"Food is fine\""},{"left":"\"Mosquitoes carry it\"","right":"\"Insects don't\""},{"left":"\"It's in the air\"","right":"\"It isn't airborne\""}],"relearn":"Every fearful rumour meets a short, calm, true reply.","cat":"spreads-or-not"},
];

